import MermaidBlock from "@/components/common/MermaidBlock"

import { t } from "i18next"
import mermaid from "mermaid"
import React, { useEffect, useRef, useState } from "react"

/**
 * Corresponds to vscode's ColorThemeKind enum
 */
enum ColorThemeKind {
	Light = 1,
	Dark = 2,
	HighContrast = 3,
	HighContrastLight = 4,
}

const DARK_MERMAID_THEME_VARIABLES = {
	darkMode: true,
	primaryColor: "#161616",
	primaryTextColor: "#f4f4f4",
	primaryBorderColor: "#f4f4f4",
	lineColor: "#f4f4f4",
}

const LIGHT_MERMAID_THEME_VARIABLES = {
	darkMode: false,
	primaryColor: "#f4f4f4",
	primaryTextColor: "#161616",
	primaryBorderColor: "#161616",
	lineColor: "#161616",
}

const IBM_MERMAID_THEME_VARIABLES = {
	[ColorThemeKind.Light]: LIGHT_MERMAID_THEME_VARIABLES,
	[ColorThemeKind.Dark]: DARK_MERMAID_THEME_VARIABLES,
	[ColorThemeKind.HighContrast]: DARK_MERMAID_THEME_VARIABLES,
	[ColorThemeKind.HighContrastLight]: LIGHT_MERMAID_THEME_VARIABLES,
}

interface MermaidDiagramProps {
	code: string
	colorThemeKind?: ColorThemeKind
}

interface MermaidErrorBlockProps {
	error: string
}

/**
 * Based on error element in {@link MermaidBlock}.
 */
export const MermaidErrorBlock: React.FC<MermaidErrorBlockProps> = ({ error }) => {
	return (
		<div
			style={{
				display: "flex",
				alignItems: "center",
				gap: "10px",
				flexGrow: 1,
			}}>
			<span
				className="codicon codicon-warning"
				style={{
					color: "var(--vscode-editorWarning-foreground)",
					opacity: 0.8,
					fontSize: 16,
					marginBottom: "-1.5px",
				}}></span>
			<span style={{ fontWeight: "bold" }}>{error}</span>
		</div>
	)
}

/**
 * MermaidDiagram component renders a Mermaid diagram from a string definition.
 * Enhances `MermaidBlock` with additional color themes support.
 *
 * @example
 * ```tsx
 * const rawCode: string = `
 *   graph TD
 *     A[Start] --> B{Is it working?}
 *     B -->|Yes| C[Great!]
 *     B -->|No| D[Debug]
 *     D --> B`
 *
 * <MermaidDiagram code={rawCode} />
 * ```
 */
const MermaidDiagram: React.FC<MermaidDiagramProps> = ({ code, colorThemeKind = ColorThemeKind.Light }) => {
	const [error, setError] = useState<string | null>(null)
	const isInitializedRef = useRef<boolean>(false)

	useEffect(() => {
		if (!isInitializedRef.current) {
			try {
				mermaid.initialize({
					startOnLoad: false,
					theme: "base", // Only `base` theme can be styled with `themeVariables`
					securityLevel: "strict",
					fontFamily: "monospace",
					themeVariables: IBM_MERMAID_THEME_VARIABLES[colorThemeKind],
				})
				isInitializedRef.current = true
			} catch (err) {
				console.error("Mermaid initialization error:", err)
				setError(t("ibm:javaModernization.mermaid.error.initializationFailed"))
			}
		}
	}, [colorThemeKind])

	if (error) {
		return <MermaidErrorBlock error={error}></MermaidErrorBlock>
	}

	return <MermaidBlock code={code}></MermaidBlock>
}

export default MermaidDiagram
