import React from "react"
import { Todo } from "./types"
import { StatusIcon } from "./StatusIcon"
import { feedbackBackgroundColor } from "../chatRow/say/UserFeedbackMessage"

interface TodoStatusMarkerProps {
	showLineUp: boolean
	showLineDown: boolean
	status: Todo["status"]
}

export const TodoStatusMarker: React.FC<TodoStatusMarkerProps> = ({ showLineUp, showLineDown, status }) => {
	return (
		<div className="">
			{showLineUp && (
				<div
					className="w-[1px] translate-x-[3.5px]"
					style={{
						background: "var(--vscode-descriptionForeground)",
						height: "8px",
					}}
				/>
			)}

			<div className={`${showLineUp ? "" : "pt-[8px]"} ${showLineDown ? "" : "pb-[8px]"} flex items-center`}>
				<StatusIcon status={status} />
			</div>

			{showLineDown && (
				<div
					className="w-[1px] translate-x-[3.5px]"
					style={{
						background: "var(--vscode-descriptionForeground)",
						height: "8px",
					}}
				/>
			)}
		</div>
	)
}

export interface TodoItemProps {
	todo: Todo
	isCurrentTodo?: boolean
	isFirst?: boolean
	isLast?: boolean
	itemRef?: (el: HTMLLIElement | null) => void
	isHeaderItem?: boolean
	className?: string
}

export const TodoItem: React.FC<TodoItemProps> = ({
	todo,
	isCurrentTodo = false,
	isFirst = true,
	isLast = true,
	itemRef,
	isHeaderItem = false,
	className = "",
}) => {
	// Determine which connecting lines to show
	const showLineUp = !isFirst
	const showLineDown = !isLast

	// Create the content element with the todo item
	const content = (
		<div className="flex items-center w-full">
			<TodoStatusMarker showLineUp={showLineUp} showLineDown={showLineDown} status={todo.status} />

			<span
				data-testid={`todo-content-${todo.id}`}
				className={`${isCurrentTodo ? "font-bold" : "font-medium"} truncate whitespace-nowrap overflow-hidden flex-1 ml-1`}
				title={todo.content}>
				{todo.content}
			</span>
		</div>
	)

	// Return as list item or div based on asListItem prop
	return isHeaderItem ? (
		<div data-testid={`todo-header-${todo.id}`} className={`pl-[8px] w-full ${className}`}>
			{content}
		</div>
	) : (
		<li
			data-testid={`todo-item-${todo.id}`}
			key={todo.id || todo.content}
			ref={itemRef}
			className={`relative w-full ${className}`}>
			{isCurrentTodo && (
				<div
					className={`absolute inset-0 rounded-[5px]`}
					style={{
						backgroundColor: feedbackBackgroundColor,
					}}
				/>
			)}
			<div className="relative z-10 px-[8px]">{content}</div>
		</li>
	)
}

