import React, { useState, useEffect } from "react"
import { useTranslation } from "react-i18next"
import { ListChecked } from "@carbon/icons-react" // ibm_change
import { ToolUseBlock, ToolUseBlockHeader } from "../chatRow/common/ToolUseBlock"
import MarkdownBlock from "@/components/common/MarkdownBlock"
import UserFeedbackMessage from "../chatRow/say/UserFeedbackMessage"
import { UpdateTodoListToolBlockProps } from "./types"
import { TodoItem } from "./TodoItem"
import { TodoAddForm } from "./TodoAddForm"
import { DeleteConfirmationDialog } from "./DeleteConfirmationDialog"

interface TodoItemType {
	id?: string
	content: string
	status?: "completed" | "in_progress" | string
}

const genId = () => Math.random().toString(36).slice(2, 10)

/**
 * UpdateTodoListToolBlock component
 *
 * Displays an editable todo list that synchronizes with the model
 */
const UpdateTodoListToolBlock: React.FC<UpdateTodoListToolBlockProps> = ({
	todos = [],
	content,
	onChange,
	editable = true,
	userEdited = false,
	isFirstCreation,
}) => {
	const { t } = useTranslation("ibm")
	const [editTodos, setEditTodos] = useState<TodoItemType[]>(
		todos.length > 0 ? todos.map((todo) => ({ ...todo, id: todo.id || genId() })) : [],
	)
	const [adding, setAdding] = useState(false)
	const [deleteId, setDeleteId] = useState<string | null>(null)
	const [isEditing, setIsEditing] = useState(false)

	// Automatically exit edit mode when external editable becomes false
	useEffect(() => {
		if (!editable && isEditing) {
			setIsEditing(false)
		}
	}, [editable, isEditing])

	// Check if onChange is passed
	useEffect(() => {
		if (typeof onChange !== "function") {
			console.warn(
				"UpdateTodoListToolBlock: onChange callback not passed, cannot notify model after todo changes!",
			)
		}
		// Only check once on mount
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [])

	// Sync when external props.todos changes
	useEffect(() => {
		setEditTodos(todos.length > 0 ? todos.map((todo) => ({ ...todo, id: todo.id || genId() })) : [])
	}, [todos])

	// Edit content
	const handleContentChange = (id: string, value: string) => {
		const newTodos = editTodos.map((todo) => (todo.id === id ? { ...todo, content: value } : todo))
		setEditTodos(newTodos)
		onChange?.(newTodos)
	}

	// Change status
	const handleStatusChange = (id: string, status: string) => {
		const newTodos = editTodos.map((todo) => (todo.id === id ? { ...todo, status } : todo))
		setEditTodos(newTodos)
		onChange?.(newTodos)
	}

	// Delete (confirmation dialog)
	const handleDelete = (id: string) => {
		setDeleteId(id)
	}
	const confirmDelete = () => {
		if (!deleteId) return
		const newTodos = editTodos.filter((todo) => todo.id !== deleteId)
		setEditTodos(newTodos)
		onChange?.(newTodos)
		setDeleteId(null)
	}
	const cancelDelete = () => setDeleteId(null)

	// Add
	const handleAdd = (newContent: string) => {
		if (!newContent.trim()) return
		const newTodo: TodoItemType = {
			id: genId(),
			content: newContent.trim(),
			status: "",
		}
		const newTodos = [...editTodos, newTodo]
		setEditTodos(newTodos)
		onChange?.(newTodos)
		setAdding(false)
	}

	const handleCancelAdd = () => {
		setAdding(false)
	}

	// If user edited, show feedback message
	if (userEdited) {
		return (
			<UserFeedbackMessage
				message={{
					text: t("todoList.userEdited"),
					type: "ask",
					ts: 0,
				}}
			/>
		)
	}
	return (
		<ToolUseBlock>
			<ToolUseBlockHeader>
				<div className="flex items-center w-full">
					<ListChecked className="mr-1.5 text-vscode-foreground" size={16} /> {/* ibm_change */}
					<span className="font-bold mr-2">
						{isFirstCreation ? t("todoList.createdTitle") : t("todoList.title")}
					</span>
					<div className="flex-grow" />
					{editable && (
						<button
							onClick={() => setIsEditing(!isEditing)}
							className={`
                border rounded px-2 py-0.5 cursor-pointer text-xs ml-2
                ${
					isEditing
						? "border-vscode-button-border bg-vscode-button-background text-vscode-button-foreground"
						: "border-vscode-button-secondaryBorder bg-vscode-button-secondaryBackground text-vscode-button-secondaryForeground"
				}
              `}>
							{isEditing ? t("todoList.done") : t("todoList.edit")}
						</button>
					)}
				</div>
			</ToolUseBlockHeader>

			<div className="overflow-x-auto max-w-full">
				{Array.isArray(editTodos) && editTodos.length > 0 ? (
					<ul className="m-0 pl-0 list-none">
						{editTodos.map((todo, idx) => (
							<TodoItem
								key={todo.id || idx}
								todo={todo}
								isEditing={isEditing}
								isFirst={idx === 0}
								isLast={idx === editTodos.length - 1}
								onContentChange={handleContentChange}
								onStatusChange={handleStatusChange}
								onDelete={handleDelete}
							/>
						))}

						{adding ? (
							<TodoAddForm onAdd={handleAdd} onCancel={handleCancelAdd} />
						) : (
							<li className="mt-0.5">
								{isEditing && (
									<button
										onClick={() => setAdding(true)}
										className="border border-dashed border-vscode-button-secondaryBorder bg-vscode-button-secondaryBackground text-vscode-button-secondaryForeground rounded px-2 py-0.5 cursor-pointer text-xs">
										{t("todoList.addTodo")}
									</button>
								)}
							</li>
						)}
					</ul>
				) : (
					<MarkdownBlock markdown={content} />
				)}
			</div>

			{/* Delete confirmation dialog */}
			<DeleteConfirmationDialog isOpen={deleteId !== null} onConfirm={confirmDelete} onCancel={cancelDelete} />
		</ToolUseBlock>
	)
}

export default UpdateTodoListToolBlock

