import React, { memo, useState, Dispatch, SetStateAction } from "react"
import { ClineMessage, ModelInfo } from "@roo-code/types"
import { Mode } from "@roo/modes"
import { useExtensionState } from "@src/context/ExtensionStateContext"
import { parseApiRequestInfo } from "./utils"

/**
 * Get API request failed message if applicable
 */
function getApiRequestFailedMessage(isLast: boolean, lastModifiedMessage?: ClineMessage): string | undefined {
	return isLast && lastModifiedMessage?.ask === "api_req_failed" ? lastModifiedMessage?.text : undefined
}

// Import say message components
import ApiRequestMessage from "./say/ApiRequestMessage"
import TextMessage from "./say/TextMessage"
import DiffErrorMessage from "./say/DiffErrorMessage"
import SubtaskResultMessage from "./say/SubtaskResultMessage"
import ErrorMessage from "./say/ErrorMessage"
import WarningMessage from "./say/WarningMessage"
import UserFeedbackMessage from "./say/UserFeedbackMessage"
import UserFeedbackDiffMessage from "./say/UserFeedbackDiffMessage"
import ImageMessage from "./say/ImageMessage"
import CodebaseSearchResultMessage from "./say/CodebaseSearchResultMessage"
import ToolMessage from "./say/ToolMessage"

// Import existing components
import CompletionResult from "@/ibm/components/chat/completionResult/CompletionResult"
import { ReasoningBlock } from "@/components/chat/ReasoningBlock"
import { CommandExecutionError } from "@/components/chat/CommandExecutionError"
import { CheckpointSaved } from "@/components/chat/checkpoints/CheckpointSaved"
import { CondensingContextRow, ContextCondenseRow, CondenseContextErrorRow } from "@/components/chat/ContextCondenseRow"
import ApiErrorBoundary from "../apiError/ApiErrorBoundary"
import { Markdown } from "@/components/chat/Markdown"
import UpdateTodoListTool from "./tools/UpdateTodoListTool"
import { GitNotificationNewBranch } from "./say/GitNotificationNewBranch"
import { GitNotificationCommit } from "./say/GitNotificationCommit"

/**
 * Props for the SayRouter component
 */
interface SayRouterProps {
	message: ClineMessage
	lastModifiedMessage?: ClineMessage
	isExpanded: boolean
	isLast: boolean
	isStreaming: boolean
	onToggleExpand: (ts: number) => void
	taskId?: string
	// ibm_change_start: Add edit functionality props
	isEditing?: boolean
	editedContent?: string
	editMode?: Mode
	editImages?: string[]
	model?: ModelInfo
	onEditClick?: () => void
	onCancelEdit?: () => void
	onSaveEdit?: () => void
	onSelectImages?: () => void
	setEditedContent?: Dispatch<SetStateAction<string>>
	setEditImages?: Dispatch<SetStateAction<string[]>>
	setEditMode?: Dispatch<SetStateAction<Mode>>
	// ibm_change_end: Add edit functionality props
}

/**
 * Router component for say-related messages
 */
export const SayRouter: React.FC<SayRouterProps> = ({
	message,
	lastModifiedMessage,
	isExpanded,
	isLast,
	isStreaming,
	onToggleExpand,
	taskId,
	// ibm_change: Destructure edit props
	isEditing,
	editedContent,
	editMode,
	editImages,
	model,
	onEditClick,
	onCancelEdit,
	onSaveEdit,
	onSelectImages,
	setEditedContent,
	setEditImages,
	setEditMode,
}) => {
	const { currentCheckpoint } = useExtensionState()
	const [isDiffErrorExpanded, setIsDiffErrorExpanded] = useState(false)
	const [isDiffWarningExpanded, setIsDiffWarningExpanded] = useState(false)

	// Memoized callback to prevent re-renders caused by inline arrow functions.
	const handleToggleExpand = React.useCallback(() => {
		onToggleExpand(message.ts)
	}, [onToggleExpand, message.ts])

	// Parse API request information
	const [_cost, apiReqCancelReason, apiReqStreamingFailedMessage] = React.useMemo(
		() => parseApiRequestInfo(message),
		[message],
	)

	// Get API request failed message if applicable
	const apiRequestFailedMessage = React.useMemo(
		() => getApiRequestFailedMessage(isLast, lastModifiedMessage),
		[isLast, lastModifiedMessage],
	)

	if (message.type !== "say") return null

	switch (message.say) {
		case "diff_error":
			return (
				<DiffErrorMessage
					message={message}
					isDiffErrorExpanded={isDiffErrorExpanded}
					setIsDiffErrorExpanded={setIsDiffErrorExpanded}
				/>
			)
		case "subtask_result":
			return <SubtaskResultMessage message={message} />
		case "reasoning":
			return (
				<ReasoningBlock
					content={message.text || ""}
					ts={message.ts}
					isStreaming={isStreaming}
					isLast={isLast}
				/>
			)
		case "api_req_started":
			return (
				<ApiErrorBoundary
					apiRequestFailedMessage={apiRequestFailedMessage}
					apiReqStreamingFailedMessage={apiReqStreamingFailedMessage}
					message={message}
					taskId={taskId}>
					<ApiRequestMessage
						message={message}
						isExpanded={isExpanded}
						onToggleExpand={handleToggleExpand}
						apiRequestFailedMessage={apiRequestFailedMessage}
						apiReqStreamingFailedMessage={apiReqStreamingFailedMessage}
						apiReqCancelReason={apiReqCancelReason}
					/>
				</ApiErrorBoundary>
			)
		case "text":
			return <TextMessage message={message} />
		case "user_feedback":
			return (
				<UserFeedbackMessage
					message={message}
					isStreaming={isStreaming}
					// ibm_change: Pass edit props
					isEditing={isEditing}
					editedContent={editedContent}
					editMode={editMode}
					editImages={editImages}
					model={model}
					onEditClick={onEditClick}
					onCancelEdit={onCancelEdit}
					onSaveEdit={onSaveEdit}
					onSelectImages={onSelectImages}
					setEditedContent={setEditedContent}
					setEditImages={setEditImages}
					setEditMode={setEditMode}
				/>
			)
		case "user_feedback_diff":
			return (
				<UserFeedbackDiffMessage
					message={message}
					isExpanded={isExpanded}
					onToggleExpand={handleToggleExpand}
				/>
			)
		case "error":
			return (
				<ErrorMessage
					message={message}
					isErrorExpanded={isDiffErrorExpanded}
					setIsErrorExpanded={setIsDiffErrorExpanded}
				/>
			)
		case "warning":
			return (
				<WarningMessage
					message={message}
					isWarningExpanded={isDiffWarningExpanded}
					setIsWarningExpanded={setIsDiffWarningExpanded}
				/>
			)
		case "completion_result":
			return <CompletionResult message={message} />
		case "shell_integration_warning":
			return <CommandExecutionError />
		case "checkpoint_saved":
			return (
				<CheckpointSaved
					ts={message.ts!}
					commitHash={message.text!}
					currentHash={currentCheckpoint}
					checkpoint={message.checkpoint}
				/>
			)
		case "condense_context":
			if (message.partial) {
				return <CondensingContextRow />
			}
			return message.contextCondense ? <ContextCondenseRow {...message.contextCondense} /> : null
		case "condense_context_error":
			return <CondenseContextErrorRow errorText={message.text} />
		case "codebase_search_result":
			return <CodebaseSearchResultMessage message={message} />
		case "user_edit_todos":
			return <UpdateTodoListTool tool={{ tool: "updateTodoList", todos: [] }} userEdited={true} />
		case "tool" as any:
			return <ToolMessage message={message} />
		case "image":
			return <ImageMessage message={message} />
		case "git_new_branch":
			return <GitNotificationNewBranch branchName={message.text} />
		case "git_commit":
			return <GitNotificationCommit commitMessage={message.text} />
		// ibm_change_start: Add browser action cases
		case "browser_action":
		case "browser_action_result":
			// Handled by BrowserSessionRow; prevent raw JSON (action/result) from rendering here
			return null
		// ibm_change_end: Add browser action cases
		default:
			return (
				<ApiErrorBoundary
					apiRequestFailedMessage={apiRequestFailedMessage}
					apiReqStreamingFailedMessage={apiReqStreamingFailedMessage}
					message={message}
					taskId={taskId}>
					<div style={{ paddingTop: 10 }}>
						<Markdown markdown={message.text} partial={message.partial} />
					</div>
				</ApiErrorBoundary>
			)
	}
}

export default memo(SayRouter)

