import React from "react"
import { useTranslation } from "react-i18next"
import { DeleteConfirmationDialogProps } from "./types"

/**
 * Component for confirming todo item deletion
 */
export const DeleteConfirmationDialog: React.FC<DeleteConfirmationDialogProps> = ({ isOpen, onConfirm, onCancel }) => {
	const { t } = useTranslation("ibm")

	if (!isOpen) return null

	return (
		<div className="fixed inset-0 bg-black/15 z-50 flex items-center justify-center" onClick={onCancel}>
			<div
				className="bg-white rounded-lg shadow-lg p-4 min-w-[200px] z-[60]"
				onClick={(e) => e.stopPropagation()}>
				<div className="mb-3 text-sm text-gray-800">{t("todoList.deleteConfirm")}</div>
				<div className="flex justify-end gap-2">
					<button
						onClick={onCancel}
						className="border border-gray-300 bg-transparent text-gray-600 rounded px-2.5 py-0.5 text-xs cursor-pointer">
						{t("todoList.cancel")}
					</button>
					<button
						onClick={onConfirm}
						className="border border-red-500 bg-red-500 text-white rounded px-2.5 py-0.5 text-xs cursor-pointer">
						{t("todoList.delete")}
					</button>
				</div>
			</div>
		</div>
	)
}

