import { t } from "i18next"
import React from "react"
import { GitCommit } from "lucide-react"
import { GenericAction } from "../common/GenericAction"

export interface GitNotificationCommitProps {
	commitMessage: string | undefined
}

export const GitNotificationCommit: React.FC<GitNotificationCommitProps> = ({ commitMessage }) => {
	return (
		<GenericAction
			icon={<GitCommit size={16} />}
			title={t("ibm:gitNotification:commit")}
			content={commitMessage || ""}
		/>
	)
}
