import ContextMenu from "@/components/chat/ContextMenu"
import { Input } from "@/components/ui"
import { useExtensionState } from "@/context/ExtensionStateContext"
import { cn } from "@/lib/utils"
import { ContextMenuOptionType, SearchResult, getContextMenuOptions } from "@/utils/context-mentions"
import { vscode } from "@/utils/vscode"
import { WebviewMessage } from "@roo/WebviewMessage"
import { Fzf } from "fzf"
import { FolderOpen } from "lucide-react"
import * as React from "react"
import { useCallback, useEffect, useRef, useState } from "react"

interface FilePathInputProps {
	/** current value of the input field */
	value: string
	/** callback function triggered when the input value changes */
	onValueChange: (value: string) => void
	/** placeholder text to display when the input is empty */
	placeholder?: string
	/** whether the input field is disabled */
	disabled?: boolean
	/** optional filter function to limit which file paths appear in suggestions */
	suggestionFilter?: (value: string) => boolean
	/** additional CSS class names to apply to the component */
	className?: string
	/** whether to show a browse button for file selection */
	showBrowseButton?: boolean
	/** file filters for the browse dialog (e.g., { "ZIP files": ["zip"] }) */
	browseFileFilters?: { [name: string]: string[] }
	/** browse mode: "file" for file selection, "folder" for folder selection */
	browseMode?: "file" | "folder"
	/** title for the browse dialog */
	browseTitle?: string
}

/**
 * A file path input component with autocomplete functionality.
 *
 * This component provides an input field for entering file paths with autocomplete suggestions from the workspace.
 * Use ``suggestionFilter`` to limit displayed suggestions.
 * Supports keyboard navigation.
 */
export const FilePathInput: React.FC<FilePathInputProps> = ({
	value,
	onValueChange: onValueChange,
	placeholder,
	disabled = false,
	suggestionFilter,
	className,
	showBrowseButton = false,
	browseFileFilters,
	browseMode = "file",
	browseTitle,
}) => {
	const [showFilePopover, setShowFilePopover] = useState(false)
	const [fileSearchResults, setFileSearchResults] = useState<SearchResult[]>([])
	const [searchLoading, setSearchLoading] = useState(false)
	const [selectedMenuIndex, setSelectedMenuIndex] = useState(-1)
	const [isInputFocused, setInputFocused] = useState(false)

	const contextMenuContainerRef = useRef<HTMLDivElement>(null)
	const { filePaths } = useExtensionState()

	// filtered file paths for initial suggestions
	const filteredFilePaths = React.useMemo(() => {
		// In folder mode, only show directories (paths ending with /)
		// In file mode, only show files (paths not ending with /)
		const pathFilter = browseMode === "folder" ? (path: string) => path.endsWith("/") : (path: string) => !path.endsWith("/")

		return filePaths.filter((path) => !suggestionFilter || suggestionFilter(path)).filter(pathFilter)
	}, [filePaths, suggestionFilter, browseMode])

	// filtered workspace files that would appear as initial suggestions
	const queryItems = React.useMemo(() => {
		return filteredFilePaths.map((path) => ({
			type: ContextMenuOptionType.File,
			value: path,
		}))
	}, [filteredFilePaths])

	// handle input focus and trigger file fuzzy search if typed
	useEffect(() => {
		if (!isInputFocused) return

		if (value === "") {
			setShowFilePopover(true)
			setSelectedMenuIndex(-1)
			setFileSearchResults([])
			return
		}

		setSearchLoading(true)

		const searchableItems = filteredFilePaths.map((path) => ({
			original: path,
			searchStr: path,
		}))

		const fzf = new Fzf(searchableItems, {
			selector: (item) => item.searchStr,
		})

		const matchingItems = fzf.find(value).map((result) => ({
			type: "file" as const,
			path: result.item.original,
		}))

		setFileSearchResults(matchingItems)
		setSearchLoading(false)
	}, [isInputFocused, value, filteredFilePaths])

	// close popover when clicking outside
	useEffect(() => {
		const handleClickOutside = (event: MouseEvent) => {
			if (contextMenuContainerRef.current && !contextMenuContainerRef.current.contains(event.target as Node)) {
				setShowFilePopover(false)
			}
		}

		if (showFilePopover) {
			document.addEventListener("mousedown", handleClickOutside)
		}

		return () => {
			document.removeEventListener("mousedown", handleClickOutside)
		}
	}, [showFilePopover])

	const handleInputFocusClick = useCallback(() => {
		setInputFocused(true)
		setShowFilePopover(true)
		setSelectedMenuIndex(-1)
	}, [])

	/**
	 * Handles file selection from the context menu.
	 * Normalizes the selected file path to start with "./" and updates the input value.
	 *
	 * @param type - The type of context menu option selected
	 * @param selectedValue - The selected file path value
	 */
	const handleFileSelect = useCallback(
		(type: ContextMenuOptionType, selectedValue?: string) => {
			if (type === ContextMenuOptionType.NoResults) {
				return
			}

			if (selectedValue && (type === ContextMenuOptionType.File || type === ContextMenuOptionType.OpenedFile)) {
				if (!selectedValue.startsWith("./")) {
					selectedValue = "./" + selectedValue.replace(/^\//, "")
				}
				onValueChange(selectedValue)
				setShowFilePopover(false)
			}
		},
		[onValueChange],
	)

	/**
	 * Handles keyboard navigation within the file suggestion popover.
	 *
	 * Supported keys:
	 * - Escape: Close the popover
	 * - ArrowUp/ArrowDown: Navigate through suggestions
	 * - Enter/Tab: Select the currently highlighted suggestion
	 *
	 * @param event - The keyboard event
	 */
	const handleKeyDown = useCallback(
		(event: React.KeyboardEvent) => {
			if (!showFilePopover) return

			if (event.key === "Escape") {
				setShowFilePopover(false)
				return
			}

			const selectableOptions = getContextMenuOptions(
				value,
				ContextMenuOptionType.File,
				queryItems,
				fileSearchResults,
			)

			if (event.key === "ArrowUp" || event.key === "ArrowDown") {
				event.preventDefault()

				if (selectableOptions.length === 0) return

				const direction = event.key === "ArrowUp" ? -1 : 1
				const currentSelectableIndex = selectableOptions.findIndex(
					(option) => option === selectableOptions[selectedMenuIndex],
				)
				const newSelectableIndex =
					(currentSelectableIndex + direction + selectableOptions.length) % selectableOptions.length

				setSelectedMenuIndex(newSelectableIndex)
				return
			}

			if ((event.key === "Enter" || event.key === "Tab") && selectedMenuIndex !== -1) {
				event.preventDefault()
				const selectedOption = selectableOptions[selectedMenuIndex]
				if (selectedOption) {
					handleFileSelect(selectedOption.type, selectedOption.value)
				}
			}
		},
		[showFilePopover, selectedMenuIndex, queryItems, fileSearchResults, handleFileSelect, value],
	)

	const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
		onValueChange(e.target.value)
	}

	const handleBrowseClick = useCallback(() => {
		const eventId = `select${browseMode === "folder" ? "Folder" : "File"}-${Date.now()}`

		const handleMessage = (event: MessageEvent) => {
			const message = event.data
			if (message.type === "commandResult" && message.requestId === eventId) {
				if (message.commandResult) {
					onValueChange(message.commandResult)
				}
				window.removeEventListener("message", handleMessage)
			}
		}

		window.addEventListener("message", handleMessage)

		const command = browseMode === "folder" ? "bob-code.selectFolder" : "bob-code.selectFile"
		const commandArgs =
			browseMode === "folder" ? [browseTitle || "Select a folder"] : [browseFileFilters, browseTitle || "Select a file"]

		const message: WebviewMessage = {
			type: "executeCommand",
			commands: [command],
			commandArgs: commandArgs,
			eventId: eventId,
		}
		vscode.postMessage(message)
	}, [browseFileFilters, browseMode, browseTitle, onValueChange])

	return (
		<div className={cn("relative", className)}>
			<div className="flex gap-2">
				<div className="relative w-full">
					<Input
						placeholder={placeholder}
						value={value}
						onChange={handleInputChange}
						disabled={disabled}
						onKeyDown={handleKeyDown}
						className="rounded"
						onFocus={handleInputFocusClick}
					/>
					{showFilePopover && (
						<div ref={contextMenuContainerRef} className={cn("absolute mb-3 w-full bottom-full z-[1000]")}>
							<ContextMenu
								onSelect={handleFileSelect}
								searchQuery={value}
								inputValue=""
								onMouseDown={() => {}}
								selectedIndex={selectedMenuIndex}
								setSelectedIndex={setSelectedMenuIndex}
								selectedType={ContextMenuOptionType.File}
								queryItems={queryItems}
								loading={searchLoading}
								dynamicSearchResults={fileSearchResults}
							/>
						</div>
					)}
				</div>
				{showBrowseButton && (
					<button
						type="button"
						onClick={handleBrowseClick}
						disabled={disabled}
						className={cn(
							"px-3 py-1",
							"text-[var(--vscode-button-foreground)]",
							"bg-[var(--vscode-button-secondaryBackground)]",
							"hover:bg-vscode-button-hoverBackground hover:cursor-pointer",
							"disabled:opacity-50 disabled:cursor-not-allowed",
							"rounded",
						)}>
						<FolderOpen size={16} />
					</button>
				)}
			</div>
		</div>
	)
}

export default FilePathInput
