import React from "react"
import { useTranslation } from "react-i18next"
import { ClineMessage } from "@roo-code/types"
import ErrorMessage from "./ErrorMessage"
import UserFeedbackMessage from "./UserFeedbackMessage"

/**
 * Props for ApiRequestMessage component
 */
export interface ApiRequestMessageProps {
	message: ClineMessage
	isExpanded: boolean
	onToggleExpand: () => void
	apiRequestFailedMessage?: string
	apiReqStreamingFailedMessage?: string
	apiReqCancelReason?: string
}

/**
 * Component for handling API request messages
 */
export const ApiRequestMessage: React.FC<ApiRequestMessageProps> = ({
	message,
	isExpanded,
	onToggleExpand,
	apiRequestFailedMessage,
	apiReqStreamingFailedMessage,
	apiReqCancelReason,
}) => {
	const { t } = useTranslation()

	if (
		(apiReqCancelReason !== null && apiReqCancelReason !== undefined) ||
		apiRequestFailedMessage ||
		apiReqStreamingFailedMessage
	) {
		if (apiReqCancelReason === "user_cancelled") {
			const errorMessage = {
				text: t("chat:apiRequest.cancelled"),
				type: message.type,
				ts: message.ts,
			}
			return <UserFeedbackMessage message={errorMessage} isStreaming={false} />
		}
		return (
			<ErrorMessage
				message={message}
				title={apiRequestFailedMessage ? t("chat:apiRequest.failed") : t("chat:apiRequest.streamingFailed")}
				isErrorExpanded={isExpanded}
				setIsErrorExpanded={onToggleExpand}
				hidePreview={true}
			/>
		)
	}

	return null
}

export default ApiRequestMessage

