import React from "react"
import { Trans } from "react-i18next"
import ToolIcon from "../common/ToolIcon"
import { headerStyle } from "../common/HeaderStyles"

interface CodebaseSearchToolProps {
	tool: {
		tool: string
		path?: string
		query: string
	}
}

/**
 * Component for handling codebase search operations
 */
export const CodebaseSearchTool: React.FC<CodebaseSearchToolProps> = ({ tool }) => {
	return (
		<div style={headerStyle}>
			<ToolIcon name="search" />
			<span style={{ fontWeight: "bold" }}>
				{tool.path ? (
					<Trans
						i18nKey="chat:codebaseSearch.wantsToSearchWithPath"
						components={{ code: <code></code> }}
						values={{ query: tool.query, path: tool.path }}
					/>
				) : (
					<Trans
						i18nKey="chat:codebaseSearch.wantsToSearch"
						components={{ code: <code></code> }}
						values={{ query: tool.query }}
					/>
				)}
			</span>
		</div>
	)
}

export default CodebaseSearchTool

