import * as React from "react"
import { memo } from "react"
import StepButton from "../../../common/StepButton"
import { vscode } from "@/utils/vscode"
import { WebviewMessage } from "@roo/WebviewMessage"
import { StepLike } from "@roo-code/types"
import { useAppTranslation } from "@/i18n/TranslationContext"

const FallbackButton: React.FC<{ steps: StepLike[] }> = ({ steps}) => {
	const { t } = useAppTranslation()

	const handleProceed = () => {
        const message: WebviewMessage = {
            type: "executeCommand",
            commands: ["bob-code.executeFallbackSubtask"],
            commandArgs: [steps],
            eventId: `fallback-${Date.now()}`,
        }
        vscode.postMessage(message)
	}

	return (
		<>
			<StepButton onClick={handleProceed}>
				{t("ibm:javaModernization.fallbackButton")}
			</StepButton>
		</>
	)
}

export default memo(FallbackButton)