import React from "react"
import { Markdown } from "@/components/chat/Markdown"
import ImageBlock from "@/components/common/ImageBlock"
import { ClineMessage } from "@roo-code/types"

/**
 * Props for TextMessage component
 */
export interface TextMessageProps {
	message: ClineMessage
}

/**
 * Component for handling text messages with optional images
 */
export const TextMessage: React.FC<TextMessageProps> = ({ message }) => {
	const displayImages = message.images
	const hasImages = displayImages && displayImages.length > 0

	return (
		<div>
			<Markdown markdown={message.text} partial={message.partial} />
			{hasImages && (
				<div style={{ marginTop: "10px" }}>
					{displayImages.map((image, index) => (
						<ImageBlock key={index} imageData={image} />
					))}
				</div>
			)}
		</div>
	)
}

export default TextMessage

