import React, { memo } from "react"
import { useTranslation } from "react-i18next"
import { ErrorWarning, ErrorWarningProps } from "./ErrorWarning"
import { vscode } from "@/utils/vscode"
import { useExtensionState } from "@/context/ExtensionStateContext"

type ContextWindowExceededWarningProps = {
	showContenseButton?: boolean
}

/**
 * Component to display a warning when the context window has been exceeded
 * Provides options to condense the context or start a new task
 */
export const ContextWindowExceededWarning = memo(
	({ showContenseButton = false }: ContextWindowExceededWarningProps) => {
		const { t } = useTranslation("ibm")
		const { currentTaskItem } = useExtensionState()

		// Handler for condensing context
		const handleCondenseContext = () => {
			if (currentTaskItem?.id) {
				vscode.postMessage({ type: "condenseTaskContextRequest", text: currentTaskItem.id })
			}
		}

		// Handler for starting a new task
		const handleStartNewTask = () => {
			vscode.postMessage({ type: "clearTask" })
		}

		const props: ErrorWarningProps = {
			title: t("apiRequest.contextWindowExceeded.title"),
			description: t("apiRequest.contextWindowExceeded.description"),
			secondaryAction: {
				label: t("apiRequest.contextWindowExceeded.newTaskButton"),
				onClick: handleStartNewTask,
			},
		}

		if (showContenseButton) {
			props.description = t("apiRequest.contextWindowExceeded.descriptionCondense")
			props.primaryAction = {
				label: t("apiRequest.contextWindowExceeded.condenseButton"),
				onClick: handleCondenseContext,
			}
		}

		return <ErrorWarning {...props} />
	},
)

export default ContextWindowExceededWarning

