import { useAppTranslation } from "@/i18n/TranslationContext"
import { vscode } from "@/utils/vscode"
import { StepLike, UnitTestingResult, UnitTestingStatus } from "@roo-code/types"
import { WebviewMessage } from "@roo/WebviewMessage"
import * as React from "react"
import { memo } from "react"
import { SettingToggleRow } from "../../../common/SettingToggleRow"
import StepButton from "../../../common/StepButton"
import StepContainer from "../../../common/StepContainer"
import { StepProgressTodoList } from "../../../common/StepProgressComponents"
import { _StepId } from "../types"

// unit test step
const UnitTestingStep: React.FC<{ config: any }> = ({ config }) => {
	const { t } = useAppTranslation()
	const [projectPath] = React.useState<string>(config.props?.projectPath || "")
	const [branchName] = React.useState<string>(config?.props?.branchName || undefined)

	const [enableGeneration, setEnableGeneration] = React.useState<boolean>(
		config.props?.unitTesting?.enableGeneration || false,
	)
	const [unitTestingStatus, setUnitTestingStatus] = React.useState<UnitTestingStatus>(
		config.props?.unitTesting?.unitTestingStatus || UnitTestingStatus.NOT_STARTED,
	)
	const [steps, setSteps] = React.useState<StepLike[]>(config.props?.unitTesting?.steps || [])

	// handle command results sent by unitTestRunner and update state accordingly
	React.useEffect(() => {
		const handleMessage = (event: MessageEvent) => {
			const message = event.data
			if (message.type === "commandResult" && message.requestId === _StepId.UNIT_TESTING) {
				const commandResult = message.commandResult as UnitTestingResult
				setUnitTestingStatus(commandResult.unitTestingStatus)
				setSteps([...commandResult.steps])
				console.log(
					`[UnitTestingStep] Command result unitTestingStatus: ${commandResult.unitTestingStatus} isCompleted: ${commandResult.isCompleted}`,
				)
				if (commandResult.isCompleted === true) {
					console.log(`[UnitTestingStep] Updating isCompleted`)
				}
			}
		}

		// Add event listener for messages from the extension
		window.addEventListener("message", handleMessage)

		// Clean up the event listener when the component unmounts
		return () => {
			window.removeEventListener("message", handleMessage)
		}
	}, [])

	const handleButtonClick = async () => {
		// invoke unit test runner via vscode command
		// the command will send a series of commandResult messages, so the progress can be tracked
		// the command (!) will also send the ask response (or chat response)
		setUnitTestingStatus(UnitTestingStatus.RUNNING_TESTS)
		const stepsToInvoke = enableGeneration
			? [
					"detectUnitTests",
					"generateUnitTestStrategy",
					"planUnitTestGeneration",
					"generateUnitTests",
					"runUnitTests",
					"runCoverage",
				]
			: ["detectUnitTests", "runUnitTests", "runCoverage"]

		const message: WebviewMessage = {
			type: "executeCommand",
			commands: ["bob-code.runJavaUnitTests"],
			commandArgs: [projectPath, stepsToInvoke, true, branchName], // true -> command to send chat response
			eventId: `${_StepId.UNIT_TESTING}-${Date.now()}`,
		}
		vscode.postMessage(message)
	}

	const buttonText = (unitTestingStatus: UnitTestingStatus) => {
		switch (unitTestingStatus) {
			case UnitTestingStatus.STARTED:
			case UnitTestingStatus.GENRATING_STRATEGY:
			case UnitTestingStatus.GENERATING_TESTS:
			case UnitTestingStatus.RUNNING_TESTS:
			case UnitTestingStatus.RUNNING_COVERAGE:
				return t("ibm:javaModernization.unitTesting.buttonTextRunning")
			case UnitTestingStatus.NOT_STARTED:
			case UnitTestingStatus.COMPLETED:
			case UnitTestingStatus.FAILED:
				return t("ibm:javaModernization.unitTesting.buttonText")
			default:
				return t("ibm:javaModernization.unitTesting.butonText")
		}
	}

	return (
		<>
			<h3>{t("ibm:javaModernization.unitTesting.title")}</h3>
			<p>{t("ibm:javaModernization.unitTesting.subTitle")}</p>
			<StepContainer>
				<div className="p-1">
					<SettingToggleRow
						title={t(`ibm:javaModernization.unitTesting.enableGeneration.label`)}
						description={t(`ibm:javaModernization.unitTesting.enableGeneration.description`)}
						disabled={unitTestingStatus !== UnitTestingStatus.NOT_STARTED}
						checked={enableGeneration}
						onChange={(checked: boolean) => {
							setEnableGeneration(checked)
						}}
					/>
				</div>

				<StepButton disabled={unitTestingStatus !== UnitTestingStatus.NOT_STARTED} onClick={handleButtonClick}>
					{buttonText(unitTestingStatus)}
				</StepButton>
				<StepProgressTodoList subSteps={steps} />
			</StepContainer>
		</>
	)
}

export default memo(UnitTestingStep)
