import React, { memo } from "react"
import { ClineMessage } from "@roo-code/types"

// Import tool components
import DiffTool from "./tools/DiffTool"
import ReadFileTool from "./tools/ReadFileTool"
import InsertContentTool from "./tools/InsertContentTool"
import CodebaseSearchTool from "./tools/CodebaseSearchTool"
import SearchFilesTool from "./tools/SearchFilesTool"
import NewFileCreatedTool from "./tools/NewFileCreatedTool"
import ListFilesRecursiveTool from "./tools/ListFilesRecursiveTool"
import ListFilesTopLevelTool from "./tools/ListFilesTopLevelTool"
import ListCodeDefinitionNamesTool from "./tools/ListCodeDefinitionNamesTool"
import FetchInstructionsTool from "./tools/FetchInstructionsTool"
import SwitchModeTool from "./tools/SwitchModeTool"
import NewTaskTool from "./tools/NewTaskTool"
import FinishTaskTool from "./tools/FinishTaskTool"
import RunSlashCommandTool from "./tools/RunSlashCommandTool"
import GenerateImageTool from "./tools/GenerateImageTool"
import UpdateTodoListTool from "./tools/UpdateTodoListTool"
import CreatePullRequestTool from "./tools/CreatePullRequestTool"
import { GeneratePrDescriptionTool } from "./tools/GeneratePrDescriptionTool"
import { ClineSayTool } from "@roo/ExtensionMessage"

/**
 * Common props shared across message components
 */
export interface ToolMessageComponentProps {
	message: ClineMessage
	isExpanded: boolean
	onToggleExpand: () => void
}

/**
 * Props for the ToolRouter component
 */
interface ToolRouterProps {
	message: ClineMessage
	tool: ClineSayTool
	isExpanded: boolean
	onToggleExpand: (ts: number) => void
	onBatchFileResponse?: (response: { [key: string]: boolean }) => void
	editable?: boolean
}

/**
 * Router component for tool-related messages
 */
export const ToolRouter: React.FC<ToolRouterProps> = ({
	message,
	tool,
	isExpanded,
	onToggleExpand,
	onBatchFileResponse,
	editable,
}) => {
	// Memoized callback to prevent re-renders caused by inline arrow functions.
	const handleToggleExpand = React.useCallback(() => {
		onToggleExpand(message.ts)
	}, [onToggleExpand, message.ts])
	// Return null if no tool is found
	if (!tool) return null

	switch (tool.tool) {
		case "editedExistingFile":
		case "appliedDiff":
			return (
				<DiffTool
					message={message}
					tool={{
						tool: tool.tool,
						path: tool.path || "",
						content: tool.content,
						diff: tool.diff,
						isProtected: tool.isProtected,
						isOutsideWorkspace: tool.isOutsideWorkspace,
						batchDiffs: tool.batchDiffs,
					}}
					isExpanded={isExpanded}
					onToggleExpand={handleToggleExpand}
				/>
			)
		case "insertContent":
			return (
				<InsertContentTool
					message={message}
					tool={{
						tool: tool.tool,
						path: tool.path || "",
						diff: tool.diff || "",
						lineNumber: tool.lineNumber || 0,
						isProtected: tool.isProtected,
						isOutsideWorkspace: tool.isOutsideWorkspace,
					}}
					isExpanded={isExpanded}
					onToggleExpand={handleToggleExpand}
				/>
			)
		case "codebaseSearch":
			return (
				<CodebaseSearchTool
					tool={{
						tool: tool.tool,
						path: tool.path,
						query: tool.query || "",
					}}
				/>
			)
		case "updateTodoList" as any: {
			return (
				<UpdateTodoListTool
					tool={{
						tool: tool.tool,
						todos: (tool as any).todos || [],
						content: (tool as any).content,
						isFirstCreation: (tool as any).isFirstCreation === true,
						isTodoContentModified: (tool as any).isTodoContentModified === true,
					}}
					editable={editable}
				/>
			)
		}
		case "newFileCreated":
			return (
				<NewFileCreatedTool
					message={message}
					tool={{
						tool: tool.tool,
						path: tool.path,
						content: tool.content,
						isProtected: tool.isProtected,
						isOutsideWorkspace: tool.isOutsideWorkspace,
					}}
					isExpanded={isExpanded}
					onToggleExpand={handleToggleExpand}
				/>
			)
		case "readFile":
			return (
				<ReadFileTool
					message={message}
					tool={{
						tool: tool.tool,
						path: tool.path,
						content: tool.content || "",
						reason: tool.reason,
						isOutsideWorkspace: tool.isOutsideWorkspace,
						additionalFileCount: tool.additionalFileCount,
						batchFiles: tool.batchFiles,
					}}
					isExpanded={isExpanded}
					onToggleExpand={handleToggleExpand}
					onBatchFileResponse={onBatchFileResponse}
				/>
			)
		case "fetchInstructions":
			return (
				<FetchInstructionsTool
					message={message}
					tool={{
						tool: tool.tool,
						content: tool.content,
					}}
					isExpanded={isExpanded}
					onToggleExpand={handleToggleExpand}
				/>
			)
		case "listFilesTopLevel":
			return (
				<ListFilesTopLevelTool
					message={message}
					tool={{
						tool: tool.tool,
						path: tool.path,
						content: tool.content,
						isOutsideWorkspace: tool.isOutsideWorkspace,
					}}
					isExpanded={isExpanded}
					onToggleExpand={handleToggleExpand}
				/>
			)
		case "listFilesRecursive":
			return (
				<ListFilesRecursiveTool
					message={message}
					tool={{
						tool: tool.tool,
						path: tool.path,
						content: tool.content,
						isOutsideWorkspace: tool.isOutsideWorkspace,
					}}
					isExpanded={isExpanded}
					onToggleExpand={handleToggleExpand}
				/>
			)
		case "listCodeDefinitionNames":
			return (
				<ListCodeDefinitionNamesTool
					message={message}
					tool={{
						tool: tool.tool,
						path: tool.path,
						content: tool.content,
						isOutsideWorkspace: tool.isOutsideWorkspace,
					}}
					isExpanded={isExpanded}
					onToggleExpand={handleToggleExpand}
				/>
			)
		case "searchFiles":
			return (
				<SearchFilesTool
					message={message}
					tool={{
						tool: tool.tool,
						path: tool.path,
						regex: tool.regex,
						filePattern: tool.filePattern,
						content: tool.content,
						isOutsideWorkspace: tool.isOutsideWorkspace,
					}}
					isExpanded={isExpanded}
					onToggleExpand={handleToggleExpand}
				/>
			)
		case "switchMode":
			return (
				<SwitchModeTool
					message={message}
					tool={{
						tool: tool.tool,
						mode: tool.mode,
						reason: tool.reason,
					}}
				/>
			)
		case "newTask":
			return (
				<NewTaskTool
					message={message}
					tool={{
						tool: tool.tool,
						mode: tool.mode,
						content: tool.content,
					}}
					isExpanded={isExpanded}
					onToggleExpand={handleToggleExpand}
				/>
			)
		case "finishTask":
			return (
				<FinishTaskTool
					tool={{
						tool: tool.tool,
					}}
				/>
			)
		case "runSlashCommand":
			return (
				<RunSlashCommandTool
					message={message}
					tool={{
						tool: tool.tool,
						command: tool.command,
						args: tool.args,
						description: tool.description,
						source: tool.source,
					}}
					isExpanded={isExpanded}
					onToggleExpand={handleToggleExpand}
				/>
			)
		case "generateImage":
			return (
				<GenerateImageTool
					message={message}
					tool={{
						tool: tool.tool,
						path: tool.path,
						content: tool.content,
						isProtected: tool.isProtected,
						isOutsideWorkspace: tool.isOutsideWorkspace,
					}}
					isExpanded={isExpanded}
					onToggleExpand={handleToggleExpand}
				/>
			)
		case "generate_description_from_diff":
			return (
				<GeneratePrDescriptionTool
					message={message}
					tool={{
						tool: tool.tool,
						content: tool.content,
						reason: tool.reason,
					}}
				/>
			)
		case "create_pull_request":
			return (
				<CreatePullRequestTool
					message={message}
					tool={{
						tool: tool.tool,
						content: tool.content,
						query: tool.query,
						reason: tool.reason,
					}}
				/>
			)
		default:
			return null
	}
}

export default memo(ToolRouter)

