import { Button, ButtonProps } from "@/components/ui"
import { ActionIndicator } from "@/ibm/components/common/actionIndicator/ActionIndicator"
import { StepLike, StepLikeStatus } from "@roo-code/types"
import * as React from "react"

import { isStepRunning } from "./utils"

interface StepButtonProps extends ButtonProps {
	stepType?: "primary" | "secondary"
	subSteps?: StepLike[]
}

// Primary - for steps
const primaryButtonClasses =
	"rounded-lg py-1.5 px-2.5 h-7 w-full m-0 bg-[var(--vscode-button-background)] text-[var(--vscode-button-foreground)] border-0 hover:bg-[var(--vscode-button-hoverBackground)]"

// Secondary - for additional actions that do not influence the flow
const secondaryButtonClasses =
	"rounded-lg py-1.5 px-2.5 h-7 w-full m-0 bg-[var(--vscode-button-secondaryBackground)] text-[var(--vscode-button-foreground)] border-0 hover:bg-[var(--vscode-button-hoverBackground)]"

const StepButton: React.FC<StepButtonProps> = (props) => {
	let tailwindClasses = ""
	if (props.stepType === undefined || props.stepType === "primary") tailwindClasses = primaryButtonClasses
	else tailwindClasses = secondaryButtonClasses

	return (
		<Button {...props} className={`${props.className || ""} ${tailwindClasses}`}>
			{props.subSteps && isStepRunning(props.subSteps) ? (
				<div className="flex flex-row items-center gap-2">
					<ActionIndicator mode="building" />
					<span>{props.subSteps.find((s) => s.status === StepLikeStatus.RUNNING)?.description ?? ""}</span>
				</div>
			) : (
				props.children
			)}
		</Button>
	)
}

export default StepButton
