export const FLOW_ID: string = "java-modernization"
// -------------------------------------------------------------------------------------

// Base status types for steps and sub-steps
export type StepStatus = "pending" | "running" | "success" | "failure" | "skipped" | "cancelled"

// Define the JavaInstallation interface
export interface JavaInstallation {
	version: string
	path: string
	isSDKMan: boolean
}
// Base interface for results and summaries
export interface StepResult {
	/** Detailed result data from the step execution */
	data?: any
	/** Error information if the step failed */
	error?: string
	/** Execution time in milliseconds */
	executionTime?: number
	/** Additional metadata */
	metadata?: Record<string, any>
}

export interface StepSummary {
	/** Brief description of what was accomplished */
	description: string
	/** Key metrics or statistics */
	metrics?: Record<string, number | string>
	/** Important findings or recommendations */
	findings?: string[]
	/** Warnings or issues encountered */
	warnings?: string[]
}

// Base interface for sub-steps
export interface JavaModernizationSubStep {
	/** Unique identifier for the sub-step */
	id: string
	/** Display name of the sub-step */
	name: string
	/** Detailed description of what this sub-step does */
	description: string
	/** Current status of the sub-step */
	status: StepStatus
	/** Result data from sub-step execution */
	result?: StepResult
	/** Summary of sub-step execution */
	summary?: StepSummary
	/** Start time of sub-step execution */
	startTime?: Date
	/** End time of sub-step execution */
	endTime?: Date
	/** Whether this sub-step is optional */
	optional?: boolean
	/** Dependencies on other sub-steps */
	dependencies?: string[]
}

// Base interface for main steps
export interface JavaModernizationStep {
	/** Unique identifier for the step */
	id: string
	/** Display name of the step */
	name: string
	/** Detailed description of what this step accomplishes */
	description: string
	/** Current status of the step */
	status: StepStatus
	/** Sub-steps within this main step */
	subSteps: JavaModernizationSubStep[]
	/** Result data from step execution */
	result?: StepResult
	/** Summary of step execution */
	summary?: StepSummary
	/** Start time of step execution */
	startTime?: Date
	/** End time of step execution */
	endTime?: Date
	/** Progress percentage (0-100) */
	progress?: number
}

// Analyze Step Types
export interface AnalyzeSubStepTypes {
	/** Project structure analysis */
	PROJECT_STRUCTURE: "project-structure"
	/** Java version detection */
	JAVA_VERSION_DETECTION: "java-version-detection"
	/** Dependency analysis */
	DEPENDENCY_ANALYSIS: "dependency-analysis"
	/** Build tool detection */
	BUILD_TOOL_DETECTION: "build-tool-detection"
	/** Code quality assessment */
	CODE_QUALITY_ASSESSMENT: "code-quality-assessment"
	/** Security vulnerability scan */
	SECURITY_SCAN: "security-scan"
	/** Framework detection */
	FRAMEWORK_DETECTION: "framework-detection"
}

export interface AnalyzeStepResult extends StepResult {
	/** Detected Java version */
	javaVersion?: string
	/** Project structure information */
	projectStructure?: {
		sourceDirectories: string[]
		testDirectories: string[]
		resourceDirectories: string[]
		buildFiles: string[]
	}
	/** Detected dependencies */
	dependencies?: {
		name: string
		version: string
		scope: string
		vulnerabilities?: string[]
	}[]
	/** Build tool information */
	buildTool?: {
		type: "maven" | "gradle"
		version?: string
		configFiles: string[]
	}
	/** Code quality metrics */
	codeQuality?: {
		linesOfCode: number
		complexity: number
		duplicateLines: number
		testCoverage?: number
	}
	/** Detected frameworks */
	frameworks?: {
		name: string
		version?: string
		migrationPath?: string
	}[]
}

export interface AnalyzeStep extends JavaModernizationStep {
	id: "analyze"
	name: "Analyze"
	result?: AnalyzeStepResult
}

// Upgrade Step Types
export interface UpgradeSubStepTypes {
	/** Java version upgrade */
	JAVA_VERSION_UPGRADE: "java-version-upgrade"
	/** Framework migration */
	FRAMEWORK_MIGRATION: "framework-migration"
	/** Dependency updates */
	DEPENDENCY_UPDATES: "dependency-updates"
	/** Code transformation */
	CODE_TRANSFORMATION: "code-transformation"
	/** API migration */
	API_MIGRATION: "api-migration"
	/** Configuration updates */
}

export interface UpgradeStepResult extends StepResult {
	/** Source Java version */
	sourceJavaVersion: string
	/** Target Java version */
	targetJavaVersion: string
	/** Files modified during upgrade */
	modifiedFiles?: string[]
	/** Dependencies updated */
	updatedDependencies?: {
		name: string
		oldVersion: string
		newVersion: string
		status: "success" | "failed" | "manual-required"
	}[]
	/** Code transformations applied */
	codeTransformations?: {
		type: string
		description: string
		filesAffected: string[]
		status: "success" | "failed"
	}[]
	/** API migrations performed */
	apiMigrations?: {
		oldApi: string
		newApi: string
		occurrences: number
		status: "success" | "failed" | "manual-required"
	}[]
	/** Configuration changes */
	configurationChanges?: {
		file: string
		changes: string[]
		status: "success" | "failed"
	}[]
	/** Build script modifications */
	buildScriptChanges?: {
		file: string
		changes: string[]
		status: "success" | "failed"
	}[]
}

export interface UpgradeStep extends JavaModernizationStep {
	id: "upgrade"
	name: "Upgrade"
	result?: UpgradeStepResult
}

// Validate Step Types
export interface ValidateSubStepTypes {
	/** Compilation validation */
	COMPILATION_VALIDATION: "compilation-validation"
	/** Unit test execution */
	UNIT_TEST_EXECUTION: "unit-test-execution"
	/** Integration test execution */
	INTEGRATION_TEST_EXECUTION: "integration-test-execution"
	/** Security validation */
	SECURITY_VALIDATION: "security-validation"
	/** Compatibility validation */
	COMPATIBILITY_VALIDATION: "compatibility-validation"
	/** Regression testing */
	REGRESSION_TESTING: "regression-testing"
	/** Deployment validation */
	DEPLOYMENT_VALIDATION: "deployment-validation"
}

export interface ValidateStepResult extends StepResult {
	/** Compilation results */
	compilationResults?: {
		success: boolean
		errors: string[]
		warnings: string[]
		buildTime: number
	}
	/** Test execution results */
	testResults?: {
		unitTests?: {
			total: number
			passed: number
			failed: number
			skipped: number
			failures: string[]
		}
		integrationTests?: {
			total: number
			passed: number
			failed: number
			skipped: number
			failures: string[]
		}
		coverage?: {
			percentage: number
			coveredLines: number
			totalLines: number
		}
	}
	/** Performance validation results */
	performanceResults?: {
		buildTime: number
		memoryUsage: number
		startupTime?: number
		throughput?: number
		regressions: string[]
	}
	/** Security validation results */
	securityResults?: {
		vulnerabilitiesFound: number
		criticalIssues: string[]
		resolved: string[]
		recommendations: string[]
	}
	/** Compatibility validation results */
	compatibilityResults?: {
		javaVersionCompatible: boolean
		dependencyCompatible: boolean
		frameworkCompatible: boolean
		issues: string[]
	}
	/** Deployment validation results */
	deploymentResults?: {
		success: boolean
		environment: string
		issues: string[]
		recommendations: string[]
	}
}

export interface ValidateStep extends JavaModernizationStep {
	id: "validate"
	name: "Validate"
	result?: ValidateStepResult
}

// Main Java Modernization Flow Type
export interface JavaModernizationFlow {
	/** Unique identifier for the modernization flow */
	id: string
	/** Display name of the modernization flow */
	name: string
	/** Description of the modernization flow */
	description: string
	/** Current status of the entire flow */
	status: StepStatus
	/** The three main steps: Analyze, Upgrade, Validate */
	steps: [AnalyzeStep, UpgradeStep, ValidateStep]
	/** Overall flow result */
	result?: StepResult
	/** Overall flow summary */
	summary?: StepSummary
	/** Flow start time */
	startTime?: Date
	/** Flow end time */
	endTime?: Date
	/** Overall progress percentage (0-100) */
	progress?: number
	/** Configuration options for the flow */
	configuration?: {
		/** Source Java version */
		sourceJavaVersion?: string
		/** Target Java version */
		targetJavaVersion?: string
		/** Project path */
		projectPath?: string
		/** Modernization type */
		modernizationType?: "JAVA_UPGRADE" | "LIBERTY_REPLATFORMING"
		/** Additional options */
		options?: Record<string, any>
	}
}

// Utility types for working with the flow
export type JavaModernizationStepType = "analyze" | "upgrade" | "validate"

export type JavaModernizationSubStepType =
	| AnalyzeSubStepTypes[keyof AnalyzeSubStepTypes]
	| UpgradeSubStepTypes[keyof UpgradeSubStepTypes]
	| ValidateSubStepTypes[keyof ValidateSubStepTypes]

// Event types for step updates
export interface StepUpdateEvent {
	flowId: string
	stepId: JavaModernizationStepType
	subStepId?: string
	status: StepStatus
	result?: StepResult
	summary?: StepSummary
	progress?: number
	timestamp: Date
}

// Factory functions for creating steps
export interface JavaModernizationStepFactory {
	createAnalyzeStep(): AnalyzeStep
	createUpgradeStep(): UpgradeStep
	createValidateStep(): ValidateStep
	createFlow(config?: Partial<JavaModernizationFlow>): JavaModernizationFlow
}

