import React, { ReactNode, useState } from "react"
import { Button } from "@/components/ui/button"

export interface ErrorWarningProps {
	title: string
	description: ReactNode
	primaryAction?: {
		label: string
		onClick: () => void
	}
	secondaryAction?: {
		label: string
		onClick: () => void
	}
}

/**
 * A reusable component for displaying error warnings with consistent styling
 * Can optionally include up to two action buttons
 * Buttons are disabled after any button is clicked
 */
export const ErrorWarning: React.FC<ErrorWarningProps> = ({ title, description, primaryAction, secondaryAction }) => {
	const [buttonsDisabled, setButtonsDisabled] = useState(false)

	const handlePrimaryClick = () => {
		setButtonsDisabled(true)
		primaryAction?.onClick()
	}

	const handleSecondaryClick = () => {
		setButtonsDisabled(true)
		secondaryAction?.onClick()
	}

	return (
		<div className="bg-vscode-editor-background flex gap-0.5 flex-col p-2 rounded border border-vscode-border">
			<div className="flex items-center gap-2 text-vscode-foreground mb-3">
				<span className="codicon codicon-warning" />
				<span className="font-bold">{title}</span>
			</div>
			<div className="mb-3">{description}</div>

			{(primaryAction || secondaryAction) && (
				<div className="flex flex-wrap gap-2 w-full">
					{primaryAction && (
						<Button
							onClick={handlePrimaryClick}
							variant="primary"
							className="flex-grow"
							disabled={buttonsDisabled}>
							{primaryAction.label}
						</Button>
					)}

					{secondaryAction && (
						<Button
							onClick={handleSecondaryClick}
							variant="secondary"
							className="flex-grow"
							disabled={buttonsDisabled}>
							{secondaryAction.label}
						</Button>
					)}
				</div>
			)}
		</div>
	)
}

export default ErrorWarning

