import { memo } from "react"
import { safeJsonParse } from "@roo/safeJsonParse"
import JavaModernizationProgress from "./controlled-chat-flows/java-modernization/JavaModernizationProgress"

/**
 * @fileoverview ControlledChatHeader component that renders a customizable header
 * above the controlled chat area and below the task overview.
 */

/**
 * Configuration object expected in the lastMessage.text
 * @typedef {Object} ControlledChatConfig
 * @property {string} flowId - Identifier for the specific chat flow (e.g., "java-modernization")
 * @property {string} stepId - Current step identifier within the flow
 * @property {Object} [props] - Optional additional properties for the flow
 */

/**
 * ControlledChatHeader component that conditionally renders different header components
 * based on the flow identified in the lastMessage.
 *
 * The component expects a specific message format with:
 * - ask: 'controlled_chat_flow'
 * - text: JSON string containing flowId and stepId
 *
 * @component
 * @param {Object} props - Component props
 * @param {Object} [props.lastMessage] - The last message object from the chat
 * @param {string} [props.lastMessage.text] - JSON string containing flow configuration
 * @param {string} [props.lastMessage.ask] - Message type identifier, must be 'controlled_chat_flow'
 *
 * @returns {React.ReactElement|null} The appropriate header component for the flow or null if no valid flow is identified
 *
 * @example
 * // Example usage:
 * <ControlledChatHeader lastMessage={{
 *   ask: 'controlled_chat_flow',
 *   text: '{"flowId":"java-modernization","stepId":"analyzeProject"}'
 * }} />
 */
const ControlledChatHeader: React.FC<{ lastMessage?: any }> = ({ lastMessage }) => {
	if (!lastMessage || !lastMessage.text || lastMessage.ask !== "controlled_chat_flow") {
		return null
	}
	// Parse the configuration from the message text
	const config = safeJsonParse<{ flowId: string; stepId: string; props?: any } | undefined>(lastMessage.text)
	if (!config) {
		return null
	}

	// Flow-specific header rendering based on flowId
	if (config?.flowId === "java-modernization") {
		return <JavaModernizationProgress config={config} />
	}

	// No matching flow found
	return null
}

/**
 * Memoized version of ControlledChatHeader to prevent unnecessary re-renders
 * when parent components re-render but the lastMessage prop hasn't changed.
 *
 * @see {@link ControlledChatHeader} for component documentation
 */
export default memo(ControlledChatHeader)
