import React from "react"
import MarkdownBlock from "@/components/common/MarkdownBlock"
import ToolIcon from "../common/ToolIcon"
import { ClineMessage } from "@roo-code/types"
import { headerStyle } from "../common/HeaderStyles"
import { useAppTranslation } from "@/i18n/TranslationContext"

interface GeneratePrDescriptionToolProps {
	message: ClineMessage
	tool: {
		tool: string
		content?: string
		reason?: string
	}
}

/**
 * Component for displaying generated pull request description preview
 */
export const GeneratePrDescriptionTool: React.FC<GeneratePrDescriptionToolProps> = ({ message, tool }) => {
	const { t } = useAppTranslation()

	// Hide component for approval messages or when content is missing/invalid
	if (!tool.content || tool.content === tool.reason || tool.content.trim().length === 0) {
		return null
	}

	return (
		<>
			<div style={headerStyle}>
				<ToolIcon name="git-pull-request" />
				<span className="font-bold">
					{message.type === "ask"
						? t("ibm:pullRequest.wantsToGenerateDescription")
						: t("ibm:pullRequest.didGenerateDescription")}
				</span>
			</div>
			<div className="mt-1 px-4 py-3 bg-vscode-editor-background border border-vscode-editorGroup-border rounded overflow-hidden">
				<div className="-mt-8 break-words [overflow-wrap:anywhere]">
					<MarkdownBlock markdown={tool.content} />
				</div>
			</div>
		</>
	)
}

export default GeneratePrDescriptionTool

