import React, { memo } from "react"
import { useTranslation } from "react-i18next"
import { ClineMessage } from "@roo-code/types"
import { Security } from "@carbon/icons-react"
import { ProgressIndicator } from "@/components/chat/ProgressIndicator"
import { headerStyle } from "../common/HeaderStyles"

/**
 * Props for CommandSecurityCheckingMessage component
 */
export interface CommandSecurityCheckingMessageProps {
	message: ClineMessage
}

/**
 * Component for displaying the security checking state while LLM verifies command safety.
 * Shows a loading indicator and the command being checked.
 */
export const CommandSecurityCheckingMessage: React.FC<CommandSecurityCheckingMessageProps> = memo(({ message }) => {
	const { t } = useTranslation()
	const normalColor = "var(--vscode-foreground)"

	return (
		<>
			<div style={headerStyle}>
				<ProgressIndicator mode="thinking" />
				<span style={{ color: normalColor, fontWeight: "bold" }}>
					{t("ibm:chat.securityChecking.title")}
				</span>
			</div>

			<div
				className="bg-vscode-panel-border flex flex-col gap-3"
				style={{
					borderRadius: "4px",
					marginTop: "15px",
					padding: "14px 16px",
				}}>
				<div style={{ color: normalColor, display: "flex", alignItems: "center", gap: "8px" }}>
					<Security style={{ marginBottom: "-2px" }} />
					{t("ibm:chat.securityChecking.description")}
				</div>

				{/* Display the command being checked */}
				<div
					className="bg-vscode-editor-background border border-vscode-border rounded-xs p-2"
					style={{
						fontFamily: "var(--vscode-editor-font-family)",
						fontSize: "var(--vscode-editor-font-size)",
						whiteSpace: "pre-wrap",
						wordBreak: "break-all",
					}}>
					{message.text}
				</div>
			</div>
		</>
	)
})

CommandSecurityCheckingMessage.displayName = "CommandSecurityCheckingMessage"

export default CommandSecurityCheckingMessage

