import React, { useRef, useState } from "react"
import { vscode } from "@src/utils/vscode"
import { useAppTranslation } from "@/i18n/TranslationContext"
import AiEffect, { AiEffectRef } from "../common/aiEffect/AiEffect"
import { TelemetryEventName } from "@roo-code/types"
import { FLOW_ID } from "../../components/chat/controlled-chat/controlled-chat-flows/java-modernization/types"
import { Button, StandardTooltip } from "@/components/ui"

// Define types for our step data
interface ModernizationStep {
	number: number
	label: string
}

// Extract step component for reusability
const StepIndicator: React.FC<{
	step: ModernizationStep
	isFirst: boolean
}> = ({ step, isFirst }) => {
	return (
		<div className="flex flex-col items-center relative">
			<div className="w-6 h-6 rounded-full bg-vscode-button-background flex items-center justify-center mb-1 relative z-10">
				<span className="text-vscode-button-foreground font-bold text-xs">{step.number}</span>
			</div>
			<div className="text-xs text-center text-vscode-button-secondaryForeground">{step.label}</div>
			{!isFirst && (
				<div className="absolute left-[-50%] top-3 w-[100%] h-0.5 bg-vscode-button-background z-0"></div>
			)}
		</div>
	)
}

const InfoPanel: React.FC<{ isVisible: boolean }> = ({ isVisible }) => {
	const { t } = useAppTranslation()

	// Define steps configuration
	const modernizationSteps: ModernizationStep[] = [
		{ number: 1, label: t("ibm:javaModernization.analyze") },
		{ number: 2, label: t("ibm:javaModernization.upgrade") },
		{ number: 3, label: t("ibm:javaModernization.validate") },
	]

	return (
		<div
			className={`transition-all duration-300 ease-in-out overflow-hidden ${
				isVisible ? "opacity-100 max-h-96 origin-top" : "opacity-0 max-h-0 origin-top -mt-2"
			}`}>
			<p className="text-sm text-vscode-button-secondaryForeground m-0 mb-2">
				<span className="font-bold">{t("ibm:javaModernization:descriptionPrefix")}</span>
				{t("ibm:javaModernization:description")}
			</p>
			{/* Steps progress indicator */}
			<div className="grid grid-cols-3 gap-2 mb-2">
				{modernizationSteps.map((step, index) => (
					<StepIndicator key={step.number} step={step} isFirst={index === 0} />
				))}
			</div>
		</div>
	)
}

// Extract header component
const ModernizationHeader: React.FC = () => {
	const { t } = useAppTranslation()
	return (
		<div className="flex items-center gap-1">
			<h2 className="text-lg font-semibold text-vscode-button-secondaryForeground m-0 mr-1">
				{t("ibm:javaModernization:title")}
			</h2>
		</div>
	)
}

/**
 * This component shows a Java Modernization section when conditions are met
 */
const JavaModernizationContent: React.FC = () => {
	const { t } = useAppTranslation()
	const aiEffectRef = useRef<AiEffectRef>(null)
	const [isOpen, setIsOpen] = useState(false)

	const toggleModernization = () => {
		setIsOpen(!isOpen)
	}

	const startJavaModernization = () => {
		vscode.postMessage({
			type: "executeCommand",
			commands: ["bob-code.captureTelemetryEvent"],
			commandArgs: [TelemetryEventName.TASK_CREATED, { flowID: FLOW_ID }],
		})
		vscode.postMessage({
			type: "newTask",
			text: `/start_java_modernization`,
		})
	}

	return (
		<div>
			<div className="px-1 py-2 text-sm font-medium text-vscode-descriptionForeground">
				{t("ibm:workflows:title")}
			</div>
			<AiEffect ref={aiEffectRef} onEffectEnd={startJavaModernization}>
				<div className="w-full bg-vscode-button-secondaryBackground rounded-lg overflow-hidden animate-in flex flex-col gap-2 p-2 @container">
					<div className="flex items-center justify-between gap-2">
						<ModernizationHeader />
						<div className="flex items-center">
							<StandardTooltip content={isOpen ? t("ibm:javaModernization.hideDetails") : t("ibm:javaModernization.moreDetails")}>
								<Button
									size="icon"
									variant="ghost"
									onClick={toggleModernization}
									aria-label={isOpen ? t("ibm:javaModernization.hideDetails") : t("ibm:javaModernization.moreDetails")}
									className="rounded-full">
									<span className="codicon codicon-info text-vscode-button-foreground transition-transform duration-200 hover:scale-125 w-4 h-4"></span>
								</Button>
							</StandardTooltip>
							<StandardTooltip content={t("ibm:javaModernization:startButton")}>
								<Button
									size="icon"
									variant="ghost"
									onClick={() => aiEffectRef.current?.triggerEffect()}
									aria-label={t("ibm:javaModernization:startButton")}
									className="rounded-full">
									<span className="codicon codicon-play text-vscode-button-foreground transition-transform duration-200 hover:scale-125 w-4 h-4"></span>
								</Button>
							</StandardTooltip>
						</div>
					</div>
					<InfoPanel isVisible={isOpen} />
				</div>
			</AiEffect>
		</div>
	)
}

export default JavaModernizationContent

