import { ProgressNotification } from "@/ibm/components/common/progressNotification/ProgressNotification"
import { callCommand } from "@/ibm/utils/callCommand"
import { ValidationStatus } from "@roo-code/types"
import { t } from "i18next"
import * as React from "react"
import { memo } from "react"
import StepButton from "../../../common/StepButton"
import StepContainer from "../../../common/StepContainer"
import { ControlledChatResponseObject, sendChatResponse } from "../../../sendChatResponse"

const ValidationProgress: React.FC<{ status: ValidationStatus }> = ({ status }) => {
	switch (status) {
		case ValidationStatus.COMPLETED_SUCCESS:
			return (
				<ProgressNotification
					mode="completed"
					message={t("ibm:javaModernization.runValidation.validateProgressCompletedSuccess")}
				/>
			)
		case ValidationStatus.COMPLETED_FAIL:
			return (
				<ProgressNotification
					mode="failure"
					message={t("ibm:javaModernization.runValidation.validateProgressCompletedFail")}
				/>
			)
		case ValidationStatus.COMPLETED_FAIL_TESTS:
			return (
				<ProgressNotification
					mode="failure"
					message={t("ibm:javaModernization.runValidation.validateProgressCompletedFailTests")}
				/>
			)
		case ValidationStatus.NOT_STARTED:
			return null
		case ValidationStatus.RUNNING:
			return (
				<ProgressNotification
					mode="building"
					message={t("ibm:javaModernization.runValidation.validateProgressRunning")}
				/>
			)
		default:
			return null
	}
}

const RunAndValidateStep: React.FC<{ config: any }> = ({ config }) => {
	const [projectPath] = React.useState<string>(config.props?.projectPath || "")
	const [modernizationType] = React.useState<string>(config.props?.modernizationType || "")
	const [validationStatus, setValidationStatus] = React.useState<ValidationStatus>(
		(config.props?.status as ValidationStatus) ?? ValidationStatus.NOT_STARTED,
	)

	const handleProceed = async () => {
		setValidationStatus(ValidationStatus.RUNNING)

		let results: any = null

		// We assume three conditions that need to be satisfied for validation to be successful:
		// 1. Modernization flow was done
		// 2. Build was successful
		// 3. Tests were successful
		//
		// We skip (1) and assume it was successfully initialized at least, since recipes ran.
		// If build fails, then tests will also fail.
		// In the final message, we will always assume (1) was at least "initialized",
		// but (2 & 3) or only (3) can fail.

		let buildSuccess: boolean = false // Did build pass?
		let testSuccess: boolean = false // Were tests ran and did they fail? If didn't run because of compilation errors, we assume true.

		let validationResultCode: number = 0

		// Determine the result
		if (modernizationType === "liberty-replatforming") {
			// TODO: proper liberty-replatflorming step
			results = JSON.parse((await callCommand("bob-code.deployApp", projectPath)) as string)
			buildSuccess = results.result.details.exitCode === 0
			testSuccess = true
		} else {
			results = JSON.parse(
				(await callCommand(
					"bob-code.buildApp",
					projectPath,
					undefined,
					config.props?.targetJavaVersion,
				)) as string,
			)
			const buildTraceAnalysis = (await callCommand("bob-code.analyzeTrace", results.result)) as any

			buildSuccess = buildTraceAnalysis.summary.totalErrors === 0 && results.result.details.exitCode === 0
			testSuccess =
				(results.result.testResult.ranTests && results.result.testResult.passed) ||
				(!results.result.testResult.ranTests && !results.result.testResult.passed)
		}

		if (buildSuccess && testSuccess) {
			validationResultCode = ValidationStatus.COMPLETED_SUCCESS
		} else if (testSuccess === false) {
			validationResultCode = ValidationStatus.COMPLETED_FAIL_TESTS
		} else {
			validationResultCode = ValidationStatus.COMPLETED_FAIL
		}

		// Prepare response object
		const responseObject: ControlledChatResponseObject = {
			flowId: config.flowId,
			stepId: config.stepId,
			message: t("ibm:javaModernization.runValidation.validationCompleted"),
			data: {
				isCompleted: true,
				description: t("ibm:javaModernization.runValidation.validationCompleted"),
				status: validationResultCode,
			},
		}

		setValidationStatus(validationResultCode)
		sendChatResponse(responseObject)
	}

	return (
		<>
			<h3>{t("ibm:javaModernization.runValidation.title")}</h3>
			<p>{t("ibm:javaModernization.runValidation.subTitle")}</p>
			<StepContainer>
				<StepButton disabled={validationStatus !== ValidationStatus.NOT_STARTED} onClick={handleProceed}>
					{validationStatus === ValidationStatus.RUNNING
						? t("ibm:javaModernization.runValidation.validateButtonProcessing")
						: t("ibm:javaModernization.runValidation.validateButton")}
				</StepButton>
			</StepContainer>
			<ValidationProgress status={validationStatus} />
		</>
	)
}

export default memo(RunAndValidateStep)
