import { useAppTranslation } from "@/i18n/TranslationContext"
import { vscode } from "@/utils/vscode"
import { StepLike, StepLikeStatus, SubStepId } from "@roo-code/types"
import { WebviewMessage } from "@roo/WebviewMessage"
import * as React from "react"
import { memo } from "react"

import StepButton from "../../../common/StepButton"
import StepContainer from "../../../common/StepContainer"
import { StepProgressNotifications, StepProgressTodoList } from "../../../common/StepProgressComponents"

const STEP_CONFIGS = {
	default: {
		steps: [],
		command: "bob-code.executeUpgradeJava",
		eventPrefix: "upgrade-",
	},
}

const UpgradeJavaVersionStep: React.FC<{ config: any }> = ({ config }) => {
	const { t } = useAppTranslation()
	const [stepCompleted, setStepCompleted] = React.useState<boolean>(
		config.props?.["upgradeJava.isCompleted"] || false,
	)

	const [subSteps, setSubSteps] = React.useState<StepLike[]>(config.props?.upgradeJavaSubSteps || [])
	const [isUpgrading, setIsUpgrading] = React.useState<boolean>(false)
	const projectPath = config.props?.projectPath
	const buildLogs = config.props?.recipeResults
	const sourceJavaVersion = config.props?.sourceJavaVersion
	const targetJavaVersion = config.props?.targetJavaVersion
	const jakartaEEEnabled = config.props?.jakartaEE?.enabled || false
	const jakartaEEVersion = config.props?.jakartaEE?.version
	const colorThemeKind = config.props?.["colorTheme.kind"]

	const handleProceed = () => {
		setSubSteps([])
		setIsUpgrading(true)
		const message: WebviewMessage = {
			type: "executeCommand",
			commands: [STEP_CONFIGS.default.command],
			commandArgs: [
				projectPath,
				buildLogs,
				sourceJavaVersion,
				targetJavaVersion,
				jakartaEEEnabled,
				jakartaEEVersion,
				colorThemeKind,
			],
			eventId: `${STEP_CONFIGS.default.eventPrefix}${Date.now()}`,
		}
		vscode.postMessage(message)
	}

	const handleUpgradeResult = (message: any) => {
		if (message.commandResult.subSteps) {
			try {
				const steps: StepLike[] = message.commandResult.subSteps
				const isCompleted: boolean = isUpgradeStepCompleted(subSteps)
				setSubSteps(steps)
				setIsUpgrading(didEndOnAnalysisStep(steps) ? false : !isCompleted)
				setStepCompleted(isCompleted)
			} catch (_) {
				// Error parsing upgrade results - reset to failed state
				setStepCompleted(false)
			}
		}
	}

	const didEndOnAnalysisStep = (upgradeSubSteps: StepLike[]): boolean => {
		if (upgradeSubSteps.length !== 1) {
			return false
		}

		const analysisStep = upgradeSubSteps[0]
		return analysisStep.id === SubStepId.JAVA_UPGRADE_ANALYZE_RECIPES && analysisStep.result?.data?.finish === true
	}

	const isUpgradeStepCompleted = (upgradeSubSteps: StepLike[]): boolean => {
		const lastSubStep = upgradeSubSteps.find((step) => step.id === SubStepId.MERMAID)
		return lastSubStep
			? lastSubStep.status === StepLikeStatus.SUCCESS || lastSubStep.status === StepLikeStatus.SKIPPED
			: false
	}

	React.useEffect(() => {
		const handleMessage = (event: MessageEvent) => {
			const message = event.data

			if (
				message.type === "commandResult" &&
				message.requestId &&
				message.requestId.startsWith(STEP_CONFIGS.default.eventPrefix)
			) {
				handleUpgradeResult(message)
			}
		}

		window.addEventListener("message", handleMessage)
		return () => {
			window.removeEventListener("message", handleMessage)
		}
	})

	return (
		<>
			<h3>{t("ibm:javaModernization.agenticChanges.title")}</h3>
			<p>{t("ibm:javaModernization.agenticChanges.subTitle")}</p>
			<StepContainer>
				<StepButton disabled={isUpgrading || stepCompleted} onClick={handleProceed}>
					{t("ibm:javaModernization.proceed")}
				</StepButton>
				<StepProgressTodoList subSteps={subSteps} />
			</StepContainer>
			<StepProgressNotifications subSteps={subSteps} />
		</>
	)
}

export default memo(UpgradeJavaVersionStep)
