import { useAppTranslation } from "@/i18n/TranslationContext"
import { vscode } from "@/utils/vscode"
import { StepLike, StepLikeStatus } from "@roo-code/types"
import { WebviewMessage } from "@roo/WebviewMessage"
import * as React from "react"
import { memo } from "react"

import StepButton from "../../../common/StepButton"
import StepContainer from "../../../common/StepContainer"
import { StepProgressTodoList } from "../../../common/StepProgressComponents"
import { ControlledChatResponseObject, sendChatResponse } from "../../../sendChatResponse"
import MermaidDiagram, { MermaidErrorBlock } from "../Mermaid"
import PreviewChangesButton from "./previewChangesButton"

const GenerateMermaidSummaryStep: React.FC<{ config: any }> = ({ config }) => {
	const { t } = useAppTranslation()
	const [isGenerating, setIsGenerating] = React.useState<boolean>(false)

	const [mermaidDiagram, setMermaidDiagram] = React.useState<string | undefined>(
		config.props?.generateMermaidSubSteps?.[0].result.data.mermaidContent,
	)
	const [subSteps, setSubSteps] = React.useState<StepLike[]>(config.props?.generateMermaidSubSteps || [])
	const [generationCompleted, setGenerationCompleted] = React.useState<boolean>(
		config.props?.["generateMermaidSummary.isCompleted"] || false,
	)

	const modernizationType = config.props?.modernizationType || ""
	const taskReports = config.props?.taskReports || []
	const colorThemeKind = config.props?.["colorTheme.kind"]
	const sourceJavaVersion = config.props?.sourceJavaVersion
	const targetJavaVersion = config.props?.targetJavaVersion
	const sourceAppServer = config.props?.sourceAppServer
	const targetAppServer = config.props?.targetAppServer
	const currentUIFramework = config.props?.currentUIFramework
	const toBeFrontend = config.props?.toBeFrontend
	const toBeBackend = config.props?.toBeBackend

	const skipPreview = (taskReports && taskReports.length === 0) || false

	const handleGenerateMermaid = () => {
		const config = {
			modernizationType,
			taskReports,
			colorThemeKind,
			...(sourceJavaVersion && targetJavaVersion
				? { javaVersions: { source: sourceJavaVersion, target: targetJavaVersion } }
				: {}),
			...(sourceAppServer || targetAppServer
				? { appServers: { source: sourceAppServer || "", target: targetAppServer || "" } }
				: {}),
			...(currentUIFramework || toBeFrontend || toBeBackend
				? {
						uiFrameworks: {
							current: currentUIFramework || "",
							frontend: toBeFrontend || "",
							backend: toBeBackend || "",
						},
					}
				: {}),
		}

		const message: WebviewMessage = {
			type: "executeCommand",
			commands: ["bob-code.executeGenerateMermaidSummary"],
			commandArgs: [config],
			eventId: `generate-mermaid-${Date.now()}`,
		}

		vscode.postMessage(message)
	}

	const handleMermaidContent = (steps: StepLike[]) => {
		if (steps[0].result?.data.mermaidContent) {
			setMermaidDiagram(steps[0].result?.data.mermaidContent)
		}
	}

	const isMermaidGenerationCompleted = (subSteps: StepLike[]): boolean => {
		return subSteps.every((s) => s.status !== StepLikeStatus.PENDING && s.status !== StepLikeStatus.RUNNING)
	}

	React.useEffect(() => {
		const handleMessage = (event: MessageEvent) => {
			const message = event.data
			if (message.type === "commandResult" && message.requestId && message.commandResult.subSteps) {
				const steps: StepLike[] = message.commandResult.subSteps
				setSubSteps(steps)
				handleMermaidContent(steps)
				setGenerationCompleted(isMermaidGenerationCompleted(steps))

				// give time todolist to deboundce to avoid UI flicker
				setTimeout(() => {
					setIsGenerating(!isMermaidGenerationCompleted(steps))
				}, 1000)
			}
		}

		window.addEventListener("message", handleMessage)

		return () => {
			window.removeEventListener("message", handleMessage)
		}
	}, [modernizationType])

	if (skipPreview) {
		if (!generationCompleted) {
			const responseObject: ControlledChatResponseObject = {
				flowId: "java-modernization",
				stepId: "generateMermaidSummary",
				message: `Generated Mermaid summary`,
				data: {
					isCompleted: true,
				},
			}
			sendChatResponse(responseObject)
		}
		return <></>
	} else
		return (
			<>
				<h3>{t("ibm:javaModernization.mermaid.title")}</h3>
				<p>{t("ibm:javaModernization.mermaid.subTitle")}</p>

				<StepContainer>
					<StepButton
						disabled={isGenerating || !!mermaidDiagram}
						onClick={handleGenerateMermaid}
						subSteps={subSteps}>
						<span>{t("ibm:javaModernization.mermaid.generate")}</span>
					</StepButton>
					<PreviewChangesButton config={config} />
					<StepProgressTodoList subSteps={subSteps} />
				</StepContainer>

				{mermaidDiagram && generationCompleted ? (
					<>
						<p>{t("ibm:javaModernization.mermaid.subTitle")}</p>
						<MermaidDiagram code={mermaidDiagram} colorThemeKind={colorThemeKind} />
					</>
				) : generationCompleted ? (
					<MermaidErrorBlock error={t("ibm:javaModernization.mermaid.error.fileMissing")} />
				) : isGenerating ? (
					<MermaidSkeleton />
				) : null}
			</>
		)
}

const MermaidSkeleton = () => (
	<div className="flex flex-col w-1/2 justify-self-center overflow-hidden">
		<div className="flex flex-row flex-1 justify-center overflow-hidden gap-4 m-2">
			<div className="h-[50px] w-1/2 bg-vscode-input-foreground opacity-20 rounded-sm animate-pulse" />
		</div>
		<div className="flex flex-row flex-1 overflow-hidden gap-4 m-2">
			<div className="h-[50px] w-full bg-vscode-input-foreground opacity-20 rounded-sm animate-pulse" />
			<div className="h-[50px] w-full bg-vscode-input-foreground opacity-20 rounded-sm animate-pulse" />
		</div>
		<div className="flex flex-row flex-1 overflow-hidden gap-4 m-2">
			<div className="h-[50px] w-full bg-vscode-input-foreground opacity-20 rounded-sm animate-pulse" />
			<div className="h-[50px] w-full bg-vscode-input-foreground opacity-20 rounded-sm animate-pulse" />
		</div>
		<div className="flex flex-row flex-1 justify-center overflow-hidden gap-4 m-2">
			<div className="h-[50px] w-1/2 bg-vscode-input-foreground opacity-20 rounded-sm animate-pulse" />
		</div>
	</div>
)

export default memo(GenerateMermaidSummaryStep)
