import React, { memo } from "react"
import { useExtensionState } from "@/context/ExtensionStateContext"

interface DevModeBoundaryProps {
	// Children to render if in dev mode
	children: React.ReactNode
}

/**
 * A component that acts as a boundary for components that should only be rendered in dev mode.
 */
export const DevModeBoundary = memo(({ children }: DevModeBoundaryProps) => {
	const { devMode } = useExtensionState()

	if (devMode) {
		return children
	}

	// If not in devMode return nothing
	return null
})

export default DevModeBoundary

