import React from "react"
import { Markdown } from "@/components/chat/Markdown"
import { FollowUpData, SuggestionItem, ClineMessage } from "@roo-code/types"
import { Help } from "@carbon/icons-react" // ibm_change
import { FollowUpSuggest } from "../FollowUpSuggest/FollowUpSuggest"
import { GenericAction } from "../common/GenericAction"

/**
 * Props for FollowUpMessage component
 */
interface FollowUpMessageProps {
	message: ClineMessage
	followUpData: FollowUpData | null
	onSuggestionClick?: (suggestion: SuggestionItem, event?: React.MouseEvent) => void
	onFollowUpUnmount?: () => void
	isFollowUpAnswered?: boolean
}

/**
 * Component for handling follow-up question messages
 */
export const FollowUpMessage: React.FC<FollowUpMessageProps> = ({
	message,
	followUpData,
	onSuggestionClick,
	onFollowUpUnmount,
	isFollowUpAnswered,
}) => {
	const normalColor = "var(--vscode-foreground)"

	// Generate icon and title based on message
	const icon = <Help style={{ color: normalColor }} />

	return (
		<GenericAction
			icon={icon}
			title={<Markdown markdown={message.partial === true ? message?.text : followUpData?.question} />}
			style={{ padding: "0" }}
			content={
				<FollowUpSuggest
					suggestions={followUpData?.suggest}
					onSuggestionClick={onSuggestionClick}
					ts={message?.ts}
					onCancelAutoApproval={onFollowUpUnmount}
					isAnswered={isFollowUpAnswered}
				/>
			}
		/>
	)
}

export default FollowUpMessage

