import React from "react"
import { useTranslation } from "react-i18next"
import { ClineMessage } from "@roo-code/types"
import { NotificationMessage } from "./NotificationMessage"

/**
 * Props for WarningMessage component
 */
export interface WarningMessageProps {
	message: ClineMessage
	isWarningExpanded: boolean
	setIsWarningExpanded: (value: boolean) => void
	title?: string
	hidePreview?: boolean
}

/**
 * Component for displaying warning messages
 */
export const WarningMessage: React.FC<WarningMessageProps> = ({
	message,
	isWarningExpanded,
	setIsWarningExpanded,
	title,
	hidePreview,
}) => {
	const { t } = useTranslation()
	const warningColor = "var(--vscode-editorWarning-foreground)"

	return (
		<NotificationMessage
			message={message}
			isExpanded={isWarningExpanded}
			setIsExpanded={setIsWarningExpanded}
			title={title || t("ibm:chat.warning")}
			hidePreview={hidePreview}
			icon="warning"
			iconColor={warningColor}
		/>
	)
}

export default WarningMessage

