import React from "react"
import { Trans } from "react-i18next"
import ToolIcon from "../common/ToolIcon"
import { ClineMessage } from "@roo-code/types"
import { headerStyle } from "../common/HeaderStyles"

interface SwitchModeToolProps {
	message: ClineMessage
	tool: {
		tool: string
		mode?: string
		reason?: string
	}
}

/**
 * Component for displaying mode switch requests
 */
export const SwitchModeTool: React.FC<SwitchModeToolProps> = ({ message, tool }) => {
	return (
		<div style={headerStyle}>
			<ToolIcon name="symbol-enum" />
			<span style={{ fontWeight: "bold" }}>
				{message.type === "ask" ? (
					<>
						{tool.reason ? (
							<Trans
								i18nKey="chat:modes.wantsToSwitchWithReason"
								components={{ code: <code>{tool.mode}</code> }}
								values={{ mode: tool.mode, reason: tool.reason }}
							/>
						) : (
							<Trans
								i18nKey="chat:modes.wantsToSwitch"
								components={{ code: <code>{tool.mode}</code> }}
								values={{ mode: tool.mode }}
							/>
						)}
					</>
				) : (
					<>
						{tool.reason ? (
							<Trans
								i18nKey="chat:modes.didSwitchWithReason"
								components={{ code: <code>{tool.mode}</code> }}
								values={{ mode: tool.mode, reason: tool.reason }}
							/>
						) : (
							<Trans
								i18nKey="chat:modes.didSwitch"
								components={{ code: <code>{tool.mode}</code> }}
								values={{ mode: tool.mode }}
							/>
						)}
					</>
				)}
			</span>
		</div>
	)
}

export default SwitchModeTool

