import { memo, useState } from "react"
import { Tooltip, TooltipTrigger, TooltipContent, TooltipProvider } from "../../../../components/ui/tooltip"
import { ThumbsUp, ThumbsDown, Send } from "lucide-react"
import { useAppTranslation } from "../../../../i18n/TranslationContext"
import { vscode } from "@/utils/vscode"
import { Button } from "../../../../components/ui/button"
import { Textarea } from "../../../../components/ui/textarea"

interface FeedbackButtonProps {
	isPositive: boolean
	isSelected: boolean
	isFeedbackSent: boolean
	onClick?: () => void
}

const FeedbackButton: React.FC<FeedbackButtonProps> = ({ isPositive, isSelected, isFeedbackSent, onClick }) => {
	const { t } = useAppTranslation()
	const Icon = isPositive ? ThumbsUp : ThumbsDown
	const tooltipText = isFeedbackSent
		? t("ibm:taskFeedback.feedbackGiven")
		: isPositive
			? t("ibm:taskFeedback.happy")
			: t("ibm:taskFeedback.notHappy")

	return (
		<TooltipProvider>
			<Tooltip>
				<TooltipTrigger asChild>
					<span
						style={{
							cursor: isFeedbackSent ? "default" : "pointer",
							opacity: isSelected ? 1 : 0.5,
						}}
						role="button"
						onClick={onClick}>
						<Icon size={18} strokeWidth={1.5} />
					</span>
				</TooltipTrigger>
				<TooltipContent>{tooltipText}</TooltipContent>
			</Tooltip>
		</TooltipProvider>
	)
}
interface TaskFeedbackProps {
	title: React.ReactNode
	icon: React.ReactNode
	feedback?: {
		isPositive: boolean
		comment: string
		timestamp: number
	}
}

const TaskFeedback: React.FC<TaskFeedbackProps> = ({ title, icon, feedback }) => {
	const { t } = useAppTranslation()
	const [selectedFeedback, setSelectedFeedback] = useState<boolean | null>(feedback?.isPositive ?? null)
	const [comment, setComment] = useState(feedback?.comment ?? "")
	const [feedbackSent, setFeedbackSent] = useState(!!feedback)

	const handleFeedback = (isPositive: boolean) => {
		if (!feedbackSent) {
			setSelectedFeedback(isPositive)
		}
	}

	const handleSendFeedback = () => {
		if (selectedFeedback !== null && !feedbackSent) {
			vscode.postMessage({
				type: "collectTaskFeedback",
				feedback: {
					isPositive: selectedFeedback,
					comment: comment.trim(),
				},
			})
			setFeedbackSent(true)
		}
	}

	// If feedback has already been collected, show the title and selected feedback buttons
	if (feedback) {
		return (
			<div style={{ display: "flex", justifyContent: "space-between", width: "100%" }}>
				<div style={{ display: "flex", alignItems: "center", gap: 8 }}>
					{icon}
					{title}
				</div>
				<div style={{ display: "flex", gap: 8 }}>
					<FeedbackButton isPositive={true} isSelected={feedback.isPositive} isFeedbackSent={true} />
					<FeedbackButton isPositive={false} isSelected={!feedback.isPositive} isFeedbackSent={true} />
				</div>
			</div>
		)
	}

	return (
		<div style={{ display: "flex", flexDirection: "column", gap: 12, width: "100%" }}>
			<div style={{ display: "flex", justifyContent: "space-between", width: "100%" }}>
				<div style={{ display: "flex", alignItems: "center", gap: 8 }}>
					{icon}
					{title}
				</div>
				<div style={{ display: "flex", gap: 8 }}>
					<FeedbackButton
						isPositive={true}
						isSelected={selectedFeedback === true}
						isFeedbackSent={feedbackSent}
						onClick={() => handleFeedback(true)}
					/>
					<FeedbackButton
						isPositive={false}
						isSelected={selectedFeedback === false}
						isFeedbackSent={feedbackSent}
						onClick={() => handleFeedback(false)}
					/>
				</div>
			</div>
			{selectedFeedback !== null && !feedbackSent && (
				<div style={{ width: "100%", display: "flex", flexDirection: "column", gap: 8 }}>
					<Textarea
						placeholder={t("ibm:taskFeedback.commentPlaceholder")}
						value={comment}
						onChange={(e) => setComment(e.target.value)}
						style={{ width: "100%" }}
					/>
					<div style={{ display: "flex", justifyContent: "flex-end" }}>
						<Button
							onClick={handleSendFeedback}
							disabled={!comment.trim()}
							style={{ opacity: !comment.trim() ? 0.5 : 1 }}>
							{t("ibm:taskFeedback.sendFeedback")}
							<Send size={16} strokeWidth={1.5} style={{ marginLeft: 6 }} />
						</Button>
					</div>
				</div>
			)}
		</div>
	)
}

export default memo(TaskFeedback)
