import { ProgressNotification } from "@/ibm/components/common/progressNotification/ProgressNotification"
import { vscode } from "@/utils/vscode"
import { WebviewMessage } from "@roo/WebviewMessage"
import { t } from "i18next"
import * as React from "react"
import { memo } from "react"

import StepButton from "../../../common/StepButton"
import StepContainer from "../../../common/StepContainer"
import { ControlledChatResponseObject, sendChatResponse } from "../../../sendChatResponse"

const ValidationProgress: React.FC<{ isRunning: boolean; stepCompleted: boolean }> = ({ isRunning, stepCompleted }) => {
	if (!isRunning && !stepCompleted) {
		return null
	}

	if (!isRunning) {
		return (
			<ProgressNotification
				mode="completed"
				message={t("ibm:javaModernization.deployApplication.deployCompleted")}
			/>
		)
	}

	return (
		<ProgressNotification mode="building" message={t("ibm:javaModernization.deployApplication.deployProcessing")} />
	)
}

const DeployAppStep: React.FC<{ config: any }> = ({ config }) => {
	const [projectPath] = React.useState<string>(config.props?.projectPath || "")
	const [stepCompleted, setStepCompleted] = React.useState<boolean>(
		config.props?.["deployApplication.isCompleted"] || false,
	)
	const [isRunning, setIsRunning] = React.useState<boolean>(config.props?.isRunning || false)

	const handleDeployAppResult = (message: any) => {
		if (message.commandResult) {
			console.log("==> handleDeployAppResult ", message.commandResult)
			try {
				const results = JSON.parse(message.commandResult)
				const deploySuccess = results && results.status === "completed" ? true : false

				const responseObject: ControlledChatResponseObject = {
					flowId: config.flowId,
					stepId: config.stepId,
					message: t("ibm:javaModernization.deployApplication.stepCompleted"),
					data: {
						isCompleted: true,
						description: deploySuccess
							? t("ibm:javaModernization.deployApplication.deploymentSuccess")
							: t("ibm:javaModernization.deployApplication.deploymentFailure"),
						status: deploySuccess ? "success" : "failure",
						result: results,
					},
				}
				console.log("==> sending ChatResponse ", responseObject)
				sendChatResponse(responseObject)
				setStepCompleted(true)
			} catch (e) {
				console.error("Failed to parse Liberty modernization results:", e)
			}
			setIsRunning(false)
		}
	}
	// Message handler effect
	React.useEffect(() => {
		const handleMessage = (event: MessageEvent) => {
			const message = event.data
			console.log("==> handleMessage ", `${message.type} -- ${message.requestId} `)
			if (message.type === "commandResult" && message.requestId) {
				// Handle Liberty modernization results
				if (message.requestId.startsWith("app-deploy-")) {
					handleDeployAppResult(message)
				}
			}
		}

		window.addEventListener("message", handleMessage)
		return () => {
			window.removeEventListener("message", handleMessage)
		}
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [])

	const handleProceed = () => {
		setIsRunning(true)
		const message: WebviewMessage = {
			type: "executeCommand",
			commands: ["bob-code.deployApp"], // Command ID to execute
			commandArgs: [projectPath], // Path to the zip file and project path
			eventId: `app-deploy-${Date.now()}`, // Unique ID for this request
		}
		vscode.postMessage(message)
	}

	return (
		<>
			<h3>{t("ibm:javaModernization.deployApplication.title")}</h3>
			<p>{t("ibm:javaModernization.deployApplication.subTitle")}</p>
			<StepContainer>
				<StepButton disabled={isRunning || stepCompleted} onClick={handleProceed}>
					{isRunning
						? t("ibm:javaModernization.deployApplication.deployButtonProcessing")
						: t("ibm:javaModernization.deployApplication.deployButton")}
				</StepButton>
			</StepContainer>
			<ValidationProgress isRunning={isRunning} stepCompleted={stepCompleted} />
		</>
	)
}

export default memo(DeployAppStep)
