import { memo, useMemo } from "react"
import { useTranslation } from "react-i18next"
import { TriangleAlert } from "lucide-react"
import { VSCodeButton } from "@vscode/webview-ui-toolkit/react"
import { useBudget } from "@/ibm/hooks/useBudget"
import { useFeatureFlag } from "@/ibm/hooks/useFeatureFlag"
import { vscode } from "@/utils/vscode"

/**
 * Component to display a warning when the user's budget has been exceeded
 * Handles different states:
 * - Max budget reached: Shows message that budget is at max allowance
 * - Budget exceeded: Shows message with feedback option
 */
export const BudgetExceededWarningInternal = memo(() => {
	const { t } = useTranslation("ibm")
	const { budget } = useBudget()
	const maxMonthlyBudgetAllowance = useFeatureFlag("max-monthly-budget-allowance")

	// Determine if we're at max budget allowance
	const isMaxBudget = useMemo(() => {
		return parseFloat(budget?.limit || "0") >= (maxMonthlyBudgetAllowance ?? 2000)
	}, [budget?.limit, maxMonthlyBudgetAllowance])

	// Determine title and description based on budget status
	const { title, description, showFeedbackButton } = useMemo(() => {
		if (isMaxBudget) {
			return {
				title: t("apiRequest.budgetExceededInternal.title"),
				description: t("apiRequest.budgetExceededInternal.descriptionMaxBudget", {
					maxBudget: budget?.limit,
				}),
				showFeedbackButton: false,
			}
		} else {
			return {
				title: t("apiRequest.budgetExceededInternal.title"),
				description: t("apiRequest.budgetExceededInternal.description", {
					maxBudget: budget?.limit,
				}),
				showFeedbackButton: true,
			}
		}
	}, [isMaxBudget, budget?.limit, t])

	const handleFeedbackClick = () => {
		vscode.postMessage({
			type: "executeCommand",
			commands: ["bob-code.sendFeedback"],
		})
	}

	return (
		<div className="flex flex-col gap-2 w-full">
			{/* Warning Icon and Title - gap-[5px] per Figma design */}
			<div className="flex gap-[5px] items-center w-full">
				<div className="flex gap-1 items-center justify-center p-[3px] shrink-0">
					<TriangleAlert size={16} />
				</div>
				<div className="flex-1 text-[13px] font-medium leading-normal">{title}</div>
			</div>

			{/* Description */}
			<div className="flex items-start w-full">
				<div className="flex-1 text-[13px] font-medium leading-normal">{description}</div>
			</div>

			{/* Feedback Button */}
			{showFeedbackButton && (
				<div className="flex items-start w-full">
					<div className="flex flex-1 items-center justify-center">
						<VSCodeButton onClick={handleFeedbackClick} className="w-full">
							<div className="flex flex-1 gap-1 items-center justify-center">
								<span className="text-[13px] font-medium text-center">
									{t("apiRequest.budgetExceededInternal.button")}
								</span>
							</div>
						</VSCodeButton>
					</div>
				</div>
			)}
		</div>
	)
})

export default BudgetExceededWarningInternal

