import React, { memo } from "react"
import { useTranslation } from "react-i18next"
import { ErrorWarning } from "./ErrorWarning"
import { vscode } from "@/utils/vscode"

/**
 * Component to display a warning when too many images and documents have been loaded
 * Provides option to start a new task with instructions to create subtasks for processing files
 */
export const TooManyImagesDocumentsWarning = memo(() => {
	const { t } = useTranslation("ibm")

	// Handler for starting a new task
	const handleStartNewTask = () => {
		vscode.postMessage({ type: "clearTask" })
	}

	return (
		<ErrorWarning
			title={t("apiRequest.tooManyImagesDocuments.title")}
			description={t("apiRequest.tooManyImagesDocuments.description")}
			primaryAction={{
				label: t("apiRequest.tooManyImagesDocuments.newTaskButton"),
				onClick: handleStartNewTask,
			}}
		/>
	)
})

export default TooManyImagesDocumentsWarning

