import React from "react"
import { useTranslation } from "react-i18next"
import { ClineMessage } from "@roo-code/types"
import FileOperation from "../common/FileOperation"

interface DiffToolProps {
	message: ClineMessage
	isExpanded: boolean
	onToggleExpand: () => void
	tool: {
		tool: string
		path: string
		content?: string
		diff?: string
		isProtected?: boolean
		isOutsideWorkspace?: boolean
		batchDiffs?: any[]
	}
}

/**
 * Component for handling diff-related tools (editedExistingFile, appliedDiff)
 */
export const DiffTool: React.FC<DiffToolProps> = ({ message, tool, isExpanded, onToggleExpand }) => {
	const { t } = useTranslation()

	// Determine the icon based on the tool type
	const icon = tool.tool === "appliedDiff" ? "diff" : "edit"

	// Determine the title based on protection status
	const title = tool.isProtected
		? t("chat:fileOperations.wantsToEditProtected")
		: tool.isOutsideWorkspace
			? t("chat:fileOperations.wantsToEditOutsideWorkspace")
			: t("chat:fileOperations.wantsToEdit")

	// Check if this is a batch diff request
	if (message.type === "ask" && tool.batchDiffs && Array.isArray(tool.batchDiffs)) {
		return (
			<FileOperation
				message={message}
				icon="diff"
				title={t("chat:fileOperations.wantsToApplyBatchChanges")}
				language="diff"
				path={tool.path}
				isExpanded={isExpanded}
				onToggleExpand={onToggleExpand}
				isProtected={tool.isProtected}
				batchFiles={tool.batchDiffs}
			/>
		)
	}

	// Regular single file diff
	return (
		<FileOperation
			message={message}
			icon={icon}
			title={title}
			path={tool.path}
			content={tool.content ?? tool.diff}
			language="diff"
			isExpanded={isExpanded}
			onToggleExpand={onToggleExpand}
			isProtected={tool.isProtected}
			isOutsideWorkspace={tool.isOutsideWorkspace}
		/>
	)
}

export default DiffTool

