import React from "react"
import { useTranslation } from "react-i18next"
import CodeAccordian from "@/components/common/CodeAccordian"
import ToolIcon from "../common/ToolIcon"
import { ClineMessage } from "@roo-code/types"
import { headerStyle } from "../common/HeaderStyles"

interface GenerateImageToolProps {
	message: ClineMessage
	isExpanded: boolean
	onToggleExpand: () => void
	tool: {
		tool: string
		path?: string
		content?: string
		isProtected?: boolean
		isOutsideWorkspace?: boolean
	}
}

/**
 * Component for displaying image generation requests
 */
export const GenerateImageTool: React.FC<GenerateImageToolProps> = ({ message, tool, isExpanded, onToggleExpand }) => {
	const { t } = useTranslation()

	return (
		<>
			<div style={headerStyle}>
				{tool.isProtected ? (
					<span
						className="codicon codicon-lock"
						style={{ color: "var(--vscode-editorWarning-foreground)", marginBottom: "-1.5px" }}
					/>
				) : (
					<ToolIcon name="file-media" />
				)}
				<span style={{ fontWeight: "bold" }}>
					{message.type === "ask"
						? tool.isProtected
							? t("chat:fileOperations.wantsToGenerateImageProtected")
							: tool.isOutsideWorkspace
								? t("chat:fileOperations.wantsToGenerateImageOutsideWorkspace")
								: t("chat:fileOperations.wantsToGenerateImage")
						: t("chat:fileOperations.didGenerateImage")}
				</span>
			</div>
			{message.type === "ask" && (
				<CodeAccordian
					path={tool.path}
					code={tool.content}
					language="text"
					isExpanded={isExpanded}
					onToggleExpand={onToggleExpand}
				/>
			)}
		</>
	)
}

export default GenerateImageTool

