import { memo } from "react"
import { BudgetExceededWarningInternal } from "./BudgetExceededWarningInternal"
import { BudgetExceededWarningPublic } from "./BudgetExceededWarningPublic"
import { StructuredApiError } from "@roo/apiError"
import { ErrorDetails } from "./errorTypeDetection"
import { useExtensionState } from "@/context/ExtensionStateContext"

type BudgetExceededWarningProps = {
	errorDetails?: ErrorDetails
}

export const BudgetExceededWarning = memo(({ errorDetails }: BudgetExceededWarningProps) => {
	const { activeProfile } = useExtensionState()
	return activeProfile?.is_internal ? (
		<BudgetExceededWarningInternal />
	) : (
		<BudgetExceededWarningPublic errorData={errorDetails?.data as StructuredApiError} />
	)
})

export default BudgetExceededWarning

