import React, { useEffect, useRef, useState } from "react"
import { BobIconDefaultBackground, BobIconDefaultHero } from "./bobIconSkins/Default"
import { useExtensionState } from "@/context/ExtensionStateContext"
import { BobIconChristmasFullBodyBackground, BobIconChristmasHeroFullBody } from "./bobIconSkins/Christmas2025"
import { SkinType } from "@roo/IBM/featureFlagsType"
import { useFeatureFlag } from "@/ibm/hooks/useFeatureFlag"

/** Component type for Bob icon parts */
export type BobIconComponent = React.FC<BobIconComponentProps>

/** Props for Bob icon component parts */
export interface BobIconComponentProps {
	rotation?: number
    darkMode?: boolean
	devMode?: boolean
    children?: React.ReactNode
}

/** Collection of components that make up a Bob icon skin */
export interface BobIconComponents {
	Background?: BobIconComponent
	Hero?: BobIconComponent
    ExtraComponents?: BobIconComponent[]
}

/**
 * For skinning Bob - a replacement component SVG or
 * a set of reusable components should be provided.
 */
export interface BobIconSkin {
    disableAnimation?: boolean
	components: BobIconComponents
}

/** Maps skin types to their component configurations */
export const SKIN_MAP : Record<SkinType, BobIconSkin> = {
    "default": {
        components: {
            Background: BobIconDefaultBackground,
            Hero: BobIconDefaultHero,
        }
    },
    "christmas2025": {
        disableAnimation: true,
        components: {
            Background: BobIconChristmasFullBodyBackground,
            Hero: BobIconChristmasHeroFullBody,
        }
    }
}

/**
 * Renders Bob icon with specified skin and mouse-tracking rotation animation.
 * Hero component slides up on mount unless animation is disabled.
 */
export const BobIcon : React.FC = () => {
    const skinType = (useFeatureFlag("bob-festive-skin") || "default") as SkinType
    const skipProps = SKIN_MAP[skinType]

    const componentsToRender : BobIconComponents = skipProps.components
    
    const { devMode } = useExtensionState()
	const [isVisible, setIsVisible] = useState(skipProps.disableAnimation)
    const [rotation, setRotation] = useState(0)
    const darkMode = document.body.classList.contains('vscode-dark') ||
        document.body.classList.contains('vscode-high-contrast');
    const containerRef = useRef<HTMLDivElement>(null)

    useEffect(() => {
        if (!skipProps.disableAnimation) {
            const timeoutId = setTimeout(() => setIsVisible(true), 10)
            return () => clearTimeout(timeoutId)
        }
    }, [skipProps.disableAnimation])

    useEffect(() => {
        const handleMouseMove = (e: MouseEvent) => {
            if (!containerRef.current) return

            const rect = containerRef.current.getBoundingClientRect()
            const centerX = rect.left + rect.width / 2
            const mouseX = e.clientX

            // Calculate rotation angle (-5 to 5 degrees) based on horizontal distance from center
            const maxRotation = 5
            const distanceFromCenterX = mouseX - centerX
            const normalizedDistance = distanceFromCenterX / (rect.width / 2)
            
            // Clamp normalized distance to [-1, 1] and apply rotation
            const clampedDistance = Math.max(Math.min(normalizedDistance, 1), -1)
            const rotationAngle = clampedDistance * maxRotation

            setRotation(rotationAngle)
        }

        window.addEventListener("mousemove", handleMouseMove)
        return () => window.removeEventListener("mousemove", handleMouseMove)
    }, [])

    return <div ref={containerRef} className={`flex flex-col items-center justify-center`}>
            <div className="relative">
                {componentsToRender.Background && <componentsToRender.Background devMode={devMode} rotation={rotation} darkMode={darkMode}/>}
                {componentsToRender.ExtraComponents &&
                <>
                    {componentsToRender.ExtraComponents.map((ExtraComp, index) => (
                        <ExtraComp key={index} devMode={devMode} rotation={rotation} darkMode={darkMode} />
                    ))}
                </>
            }
            <div className="absolute inset-0 overflow-hidden flex items-center justify-center">
                <div
                className={`transition-transform duration-700 ease-out ${
                    isVisible ? "translate-y-0" : "translate-y-full"
                }`}
                style={{
                    transformOrigin: "bottom",
                }}>
                    
                {componentsToRender.Hero && <componentsToRender.Hero devMode={devMode} rotation={rotation} darkMode={darkMode}/>}
                
                </div>
            </div>
        </div>
    </div>
}