import React, { useRef } from "react"
import { vscode } from "@src/utils/vscode"
import AiEffect, { AiEffectRef } from "../aiEffect/AiEffect"
import { Button } from "@/components/ui"


export interface RequestFeedbackProps {
	children?: React.ReactNode
	key?: number
}

/**
 * A reusable component for requesting user feedback that triggers the feedback form
 * and provides visual effects during submission.
 */
export const RequestFeedback: React.FC<RequestFeedbackProps> = ({ children, key }) => {
	const aiEffectRef = useRef<AiEffectRef>(null)

	const handleClick = () => {
		vscode.postMessage({
			type: "executeCommand",
			commands: ["bob-code.sendFeedback"],
		})
	}

	return (
		<AiEffect ref={aiEffectRef} onEffectEnd={handleClick}>
			<Button className="cursor-pointer w-full" key={key} onClick={() => aiEffectRef.current?.triggerEffect()}>
				{children}
			</Button>
		</AiEffect>
	)
}
export default RequestFeedback

