import { CommandExecution } from "@/components/chat/CommandExecution"
import { useAppTranslation } from "@/i18n/TranslationContext"
import { ProgressNotification } from "@/ibm/components/common/progressNotification/ProgressNotification"
import { StepLike, StepLikeStatus } from "@roo-code/types"
import * as React from "react"

import TodoListDisplay from "../../todoListDisplay/TodoListDisplay"
import { Todo, TodoStatus } from "../../todoListDisplay/types"
import FallbackButton from "../controlled-chat-flows/java-modernization/steps/fallbackButton"
import StepContainer from "./StepContainer"
import { getFailedSteps } from "./utils"

const STATUS_MAP = new Map<StepLikeStatus, TodoStatus>([
	[StepLikeStatus.PENDING, TodoStatus.NOT_STARTED],
	[StepLikeStatus.RUNNING, TodoStatus.IN_PROGRESS],
	[StepLikeStatus.SUCCESS, TodoStatus.COMPLETED],
	[StepLikeStatus.FAILURE, TodoStatus.ERROR],
	[StepLikeStatus.ERROR, TodoStatus.ERROR],
	[StepLikeStatus.SKIPPED, TodoStatus.SKIPPED],
	[StepLikeStatus.CANCELLED, TodoStatus.SKIPPED],
])

interface StepProgressComponentProps {
	subSteps: StepLike[]
}

export const StepProgressTodoList: React.FC<StepProgressComponentProps> = ({ subSteps }) => {
	const todos: Todo[] = subSteps.map((step) => {
		return {
			id: step.id,
			content: `${step.name} (${step.status})`,
			status: STATUS_MAP.get(step.status) ?? TodoStatus.SKIPPED,
		}
	})

	return <TodoListDisplay className="mx-0 shadow-none" todos={todos} options={{ initiallyCollapsed: false }} />
}

export const StepProgressNotifications: React.FC<StepProgressComponentProps> = ({ subSteps }) => {
	const { t } = useAppTranslation()
	const failedSteps = getFailedSteps(subSteps)

	return (
		<>
			{failedSteps.map((step) => {
				const hasCommand: boolean = step.result?.executionResult?.command !== undefined
				const titleMessage: string = t("ibm:javaModernization.error.subStep", {
					subStepName: step.name.toLowerCase(),
				})
				const errorText: string | undefined = step.result?.executionResult?.error?.message

				if (hasCommand) {
					// Use CommandExecution for steps with command execution
					return (
						<CommandExecution
							key={step.id}
							executionId={step.id}
							text={`${step.result?.executionResult?.command}\nOutput: ${step.result?.executionResult?.stdout || ""}`}
							title={
								<ProgressNotification
									mode="failure"
									message={titleMessage}
									rightComponent={step.fixable && <FallbackButton steps={subSteps} />}
								/>
							}
						/>
					)
				} else {
					// Use ErrorMessage for steps without command execution
					return (
						<>
							<div className="mb-1">
								<ProgressNotification
									mode="failure"
									message={titleMessage}
									rightComponent={step.fixable && <FallbackButton steps={subSteps} />}
								/>
							</div>
							{errorText && <StepContainer>{errorText}</StepContainer>}
						</>
					)
				}
			})}
		</>
	)
}
