import React from "react"
import ImageBlock from "@/components/common/ImageBlock"
import { safeJsonParse } from "@roo/safeJsonParse"
import { ClineMessage } from "@roo-code/types"

/**
 * Props for ImageMessage component
 */
export interface ImageMessageProps {
	message: ClineMessage
}

/**
 * Component for displaying image messages
 */
export const ImageMessage: React.FC<ImageMessageProps> = ({ message }) => {
	// If message.text is empty or missing, return null
	if (!message.text) {
		return null
	}

	// Parse the JSON to get imageUri and imagePath
	const imageInfo = safeJsonParse<{ imageUri: string; imagePath: string }>(message.text)

	if (!imageInfo || !imageInfo.imageUri || !imageInfo.imagePath) {
		return null
	}

	return (
		<div style={{ marginTop: "10px" }}>
			<ImageBlock imageUri={imageInfo.imageUri} imagePath={imageInfo.imagePath} />
		</div>
	)
}

export default ImageMessage

