import { useMemo, useRef, useEffect } from "react"
import { useTranslation } from "react-i18next"
import { cn } from "@/lib/utils"
import { Flag } from "lucide-react"

import { CheckpointMenu } from "./CheckpointMenu"
import { checkpointSchema } from "./schema"

type CheckpointSavedProps = {
	ts: number
	commitHash: string
	currentHash?: string
	checkpoint?: Record<string, unknown>
}

export const CheckpointSaved = ({ checkpoint, currentHash, ...props }: CheckpointSavedProps) => {
	const { t } = useTranslation()
	const isCurrent = currentHash === props.commitHash
	// const [isPopoverOpen, setIsPopoverOpen] = useState(false)
	// const [isClosing, setIsClosing] = useState(false)
	const closeTimer = useRef<number | null>(null)

	useEffect(() => {
		return () => {
			if (closeTimer.current) {
				window.clearTimeout(closeTimer.current)
				closeTimer.current = null
			}
		}
	}, [])

	// const handlePopoverOpenChange = (open: boolean) => {
	// 	setIsPopoverOpen(open)
	// 	if (open) {
	// 		setIsClosing(false)
	// 		if (closeTimer.current) {
	// 			window.clearTimeout(closeTimer.current)
	// 			closeTimer.current = null
	// 		}
	// 	} else {
	// 		setIsClosing(true)
	// 		closeTimer.current = window.setTimeout(() => {
	// 			setIsClosing(false)
	// 			closeTimer.current = null
	// 		}, 200) // keep menu visible briefly to avoid popover jump
	// 	}
	// }

	// const menuVisible = isPopoverOpen || isClosing // ibm_change

	const metadata = useMemo(() => {
		if (!checkpoint) {
			return undefined
		}

		const result = checkpointSchema.safeParse(checkpoint)

		if (!result.success) {
			return undefined
		}

		return result.data
	}, [checkpoint])

	if (!metadata) {
		return null
	}

	return (
		<div className="group flex items-center justify-between gap-2 pt-2 pb-3 ">
			<div className="flex gap-2">
				<Flag className="text-blue-400 w-4 h-4" />
				<span className="font-bold">{t("chat:checkpoint.regular")}</span>
				{isCurrent && <span className="text-muted text-sm">{t("chat:checkpoint.current")}</span>}
			</div>

			{/* Keep menu visible while popover is open or briefly after close to prevent jump */}
			<div
				data-testid="checkpoint-menu-container"
				className={cn("h-4 -mt-2")}>
				<CheckpointMenu
					ts={props.ts}
					commitHash={props.commitHash}
					checkpoint={metadata}
					// onOpenChange={handlePopoverOpenChange}
				/>
			</div>
		</div>
	)
}
