import React, { useMemo } from "react"
import { useTranslation } from "react-i18next"
import { Coins, Gauge, ExternalLink } from "lucide-react"
import { VSCodeBadge, VSCodeButton } from "@vscode/webview-ui-toolkit/react"

import "./BudgetIndicator.css"
import { RequestFeedback } from "../requestFeedback/RequestFeedback"
import { useBudget } from "@/ibm/hooks/useBudget"
import { useFeatureFlag } from "@/ibm/hooks/useFeatureFlag"
import { StandardTooltip } from "@/components/ui"
import { useExtensionState } from "@/context/ExtensionStateContext"
import {
	getTrialStatus,
	formatRefreshDate,
	isRefreshDateInPast,
	getPlanDisplayName,
	shouldShowTeamInfo,
} from "@roo/IBM/userProfileHelpers"
import { vscode } from "@/utils/vscode"
import { ENTERPRISE_PLAN_ID } from "@/ibm/constants"

interface BudgetDescriptionProps {
	budget: { percentage: number; email: string; limit: string | null }
	isInternal: boolean
}

/**
 * Component that renders the appropriate description content based on budget status and plan availability
 */
const BudgetDescription: React.FC<BudgetDescriptionProps> = ({ budget, isInternal }) => {
	const { t } = useTranslation("ibm")
	const maxMonthlyBudgetAllowance = useFeatureFlag("max-monthly-budget-allowance")

	// Case 1: User has maximum budget allowance (only check if no plan)
	if (isInternal && parseFloat(budget.limit || "0") >= (maxMonthlyBudgetAllowance ?? 2000)) {
		return <>{t("budget.descriptionMaxBudget")}</>
	}

	// Case 2: Budget is low (below 10%)
	if (budget.percentage < 10) {
		// If plan info exists, don't show request feedback or monthly reset message
		if (!isInternal) {
			return null
		}

		// Case 2b: No plan info - show request feedback
		return (
			<div className="flex flex-col gap-2">
				<span>{t("budget.descriptionLow")}</span>
				<RequestFeedback>
					<span className="text-sm">{t("budget.provideFeedback")}</span>
				</RequestFeedback>
			</div>
		)
	}

	// Default case: Normal budget state - only show if no plan info
	if (!isInternal) {
		return null
	}
	return <>{t("budget.description")}</>
}

/**
 * Determines the CSS class for the budget indicator based on percentage and trial status
 */
const getBudgetStatusClass = (percentage: number, isExpiringSoon: boolean, isExpired: boolean): string => {
	// Trial expiring soon or expired takes priority
	if (isExpired || isExpiringSoon) return "ibm--budget--critical"
	if (percentage < 3) return "ibm--budget--critical"
	if (percentage < 5) return "ibm--budget--warning"
	return ""
}

/**
 * Component that renders the tooltip content for the budget indicator
 */
export const BudgetTooltipContent = () => {
	const { budget } = useBudget()
	const { t, i18n } = useTranslation("ibm")
	const { t: tSettings } = useTranslation("ibmSettings")
	const { activeProfile, availableProfiles, featureFlags } = useExtensionState()

	// Calculate trial status
	const { isTrial, daysRemaining, isExpired, isExpiringSoon } = useMemo(() => {
		return getTrialStatus(activeProfile)
	}, [activeProfile])

	const manageSubscriptionUrl = useMemo(() => {
		return featureFlags?.["manage-subscription-url"]
	}, [featureFlags])

	const isEnterprisePlan = useMemo(() => {
		return activeProfile?.plan === ENTERPRISE_PLAN_ID
	}, [activeProfile?.plan])

	const isInternal = activeProfile?.is_internal ?? false

	// Calculate refresh/renew date info
	const refreshInfo = useMemo(() => {
		if (!activeProfile?.refresh_at) {
			return null
		}

		const isInPast = isRefreshDateInPast(activeProfile.refresh_at)
		const isTrialPlan = isTrial

		// Hide if trial has expired
		if (isTrialPlan && isInPast) {
			return null
		}

		const locale = i18n.language || "en"
		const formattedDate = formatRefreshDate(activeProfile.refresh_at, locale, isEnterprisePlan)

		return {
			label: isTrialPlan ? tSettings("general.trialEnds") : tSettings("general.planUpdates"),
			date: formattedDate,
		}
	}, [activeProfile, isTrial, i18n.language, tSettings, isEnterprisePlan])

	if (budget === null) {
		return t("budget.fetching")
	}

	return (
		<div className="p-1">
			<h4 className="m-0">{t("budget.remaining", { ...budget })}</h4>
			<h5 className="m-0 mb-1">
				<Coins size={12} className="inline-block m-1" />
				{t("budget.spend", { ...budget })}
			</h5>
			{budget.limit !== t("budget.unlimited") ? (
				<div>
					<BudgetDescription budget={budget} isInternal={isInternal} />
				</div>
			) : null}
			{!isInternal && (
				<div className="mt-1 pt-2 border-t border-vscode-panel-border">
					<div className="text-sm font-medium mb-1">
						<span>{tSettings("general.plan")}: </span>
						<span>{getPlanDisplayName(activeProfile)}</span>
					</div>
					{activeProfile?.team_name && shouldShowTeamInfo(availableProfiles) && (
						<div className="text-sm font-medium mb-1">
							<span>{tSettings("general.team")}: </span>
							<span>{activeProfile.team_name}</span>
						</div>
					)}
					{isExpired && (
						<div className="text-sm text-vscode-errorForeground mb-1">
							{tSettings("general.trialExpired")}
						</div>
					)}
					{refreshInfo && (
						<div className="text-sm mb-1">
							<span>{refreshInfo.label}: </span>
							<span>{refreshInfo.date}</span>
						</div>
					)}
					{isTrial && !isExpired && daysRemaining !== null && (
						<div className={`text-sm mb-1 ${isExpiringSoon ? "text-vscode-errorForeground" : ""}`}>
							{daysRemaining === 1
								? tSettings("general.trialDayRemaining")
								: tSettings("general.trialDaysRemaining", { days: daysRemaining })}
						</div>
					)}
					{manageSubscriptionUrl && !isEnterprisePlan && (
						<div className="flex items-start w-full mt-2">
							<div className="flex flex-1 items-center justify-center">
								<VSCodeButton
									onClick={() =>
										vscode.postMessage({ type: "openExternal", url: manageSubscriptionUrl })
									}
									className="w-full">
									<div className="flex flex-1 gap-1 items-center justify-center">
										<span className="text-[13px] font-medium text-center">
											{tSettings("general.manageSubscription")}
										</span>
										<div className="flex flex-col items-center justify-center size-5 shrink-0">
											<ExternalLink className="w-4 h-4" />
										</div>
									</div>
								</VSCodeButton>
							</div>
						</div>
					)}
				</div>
			)}
		</div>
	)
}

const BudgetIndicator: React.FC = () => {
	const { budget } = useBudget()
	const { activeProfile } = useExtensionState()

	// Calculate trial status
	const { isExpired, isExpiringSoon } = useMemo(() => {
		return getTrialStatus(activeProfile)
	}, [activeProfile])

	// Don't render anything if budget data is not available
	if (budget === null) {
		return null
	}

	const statusClass = getBudgetStatusClass(budget.percentage, isExpiringSoon, isExpired)

	return (
		<StandardTooltip content={<BudgetTooltipContent />} side="top">
			<VSCodeBadge
				className={`flex justify-end mr-2 items-center cursor-pointer w-24 vscode-badge-custom ${statusClass}`}>
				<Gauge className="w-4 h-4 mr-1" />
				{budget.percentage}%
			</VSCodeBadge>
		</StandardTooltip>
	)
}

export default BudgetIndicator

