import { memo, useEffect, useRef, useState } from "react"
import { useTranslation } from "react-i18next"

import { ChecklistIcon } from "./ChecklistIcon"
import { StatusIcon } from "./StatusIcon"
import { TodoItem } from "./TodoItem"
import { Todo, TodoStatus } from "./types"

export interface CollapsedViewProps {
	allCompleted: boolean
	currentFocusedTodo: {
		todo: Todo | undefined
		index: number
		isFirst: boolean
		isLast: boolean
	}
	completedCount: number
	totalCount: number
	onToggle: () => void
}

const CollapsedView = ({
	allCompleted,
	currentFocusedTodo,
	completedCount,
	totalCount,
	onToggle,
}: CollapsedViewProps) => {
	const { t } = useTranslation("ibm")
	// State to track animation
	const [showAnimation, setShowAnimation] = useState(false)
	// Ref to track currentFocusedTodo changes
	const previousFocusedTodo = useRef(currentFocusedTodo)
	// Extract the todo from currentFocusedTodo for easier access
	const focusedTodo = currentFocusedTodo.todo

	// Effect to trigger animation when the todo becomes focused, but not on initial render
	useEffect(() => {
		// Only animate when the currentFocusedTodo changes
		if (currentFocusedTodo?.todo?.id !== previousFocusedTodo?.current?.todo?.id && previousFocusedTodo) {
			setShowAnimation(true)
			// Reset animation after it completes
			const timer = setTimeout(() => {
				setShowAnimation(false)
			}, 600) // Match animation duration

			return () => clearTimeout(timer)
		}
	}, [currentFocusedTodo, previousFocusedTodo])
	// Determine what icon to show
	const getIcon = () => {
		if (allCompleted) {
			return <StatusIcon status={TodoStatus.ALL_COMPLETED} />
		}

		if (!focusedTodo) {
			return <ChecklistIcon />
		}

		return <StatusIcon status={focusedTodo.status} />
	}

	// Determine the text to show
	const getText = () => {
		if (allCompleted) {
			return t("todoList.display.allTasksCompleted")
		}

		return focusedTodo?.content || t("todoList.display.noPendingTasks")
	}

	return (
		<div
			className="flex items-center justify-between gap-0.5 cursor-pointer select-none pr-[8px]"
			onClick={onToggle}>
			{/* Left side with icon and content */}
			<div className="flex items-center flex-1 min-w-0">
				{focusedTodo ? (
					<div className={`flex-1 min-w-0 ${showAnimation ? "todo-focus-animation" : ""}`}>
						<TodoItem
							todo={focusedTodo}
							isHeaderItem={true}
							isCurrentTodo={true}
							isFirst={currentFocusedTodo.isFirst}
							isLast={currentFocusedTodo.isLast}
							className="flex-1 min-w-0"
						/>
					</div>
				) : (
					<div className="flex items-center flex-1 min-w-0 gap-1 text-[12px] pl-[8px] py-[8px]">
						{getIcon()}
						<span
							data-testid={allCompleted ? "all-tasks-completed" : "no-pending-tasks"}
							className="font-bold text-[12px] flex-1 overflow-hidden text-ellipsis whitespace-nowrap">
							{getText()}
						</span>
					</div>
				)}
			</div>

			{/* Right side with count */}
			<div className="flex items-center gap-1 flex-shrink-0">
				<ChecklistIcon />
				<span
					data-testid="todo-count"
					className="text-[var(--vscode-descriptionForeground)] text-[12px] font-medium">
					{completedCount}/{totalCount}
				</span>
			</div>
		</div>
	)
}

export default memo(CollapsedView)

