import { useAppTranslation } from "@/i18n/TranslationContext"
import ToggleButton from "@/ibm/components/common/toggleButton/ToggleButton"

export interface SettingToggleRowProps {
	title: string
	description: string
	checked: boolean
	disabled: boolean
	onChange: (checked: boolean) => void
}

export const SettingToggleRow: React.FC<SettingToggleRowProps> = ({
	title,
	description,
	checked,
	disabled,
	onChange,
}) => {
	const { t } = useAppTranslation()

	const PillLabel: React.FC<{ checked: boolean }> = ({ checked }: { checked: boolean }) => {
		return (
			<span
				className={`text-xs rounded-full px-2 py-0.5 text-[var(--vscode-button-foreground)]
                            ${checked ? "bg-[var(--vscode-button-background)]" : "bg-gray-500"}`}>
				{checked ? t(`ibm:state.on`).toLowerCase() : t(`ibm:state.off`).toLowerCase()}
			</span>
		)
	}

	return (
		<div className="flex items-center justify-between space-x-2">
			<div className="flex flex-col space-x-2">
				<div className="flex items-center space-x-2">
					<span>{`${title}`}</span>
					<PillLabel checked={checked} />
				</div>
				<div className="text-vscode-descriptionForeground text-sm mt-1">
					<span>{`${description}`}</span>
				</div>
			</div>
			<ToggleButton disabled={disabled} checked={checked} onChange={onChange} />
		</div>
	)
}
