import React, { useState, useRef, useEffect } from "react"
import { useTranslation } from "react-i18next"
import { TodoAddFormProps } from "./types"

/**
 * Component for adding new todo items
 */
export const TodoAddForm: React.FC<TodoAddFormProps> = ({ onAdd, onCancel }) => {
	const { t } = useTranslation("ibm")
	const [content, setContent] = useState("")
	const inputRef = useRef<HTMLInputElement>(null)

	// Focus input when component mounts
	useEffect(() => {
		if (inputRef.current) {
			inputRef.current.focus()
		}
	}, [])

	// Handle content change
	const handleContentChange = (e: React.ChangeEvent<HTMLInputElement>) => {
		setContent(e.target.value)
	}

	// Handle add button click
	const handleAdd = () => {
		if (content.trim()) {
			onAdd(content)
			setContent("")
		}
	}

	// Handle key down events
	const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
		if (e.key === "Enter") {
			handleAdd()
		} else if (e.key === "Escape") {
			handleCancelAdd()
		}
	}

	const handleCancelAdd = () => {
		setContent("")
		onCancel()
	}

	return (
		<li className="mt-0.5 flex items-center">
			<span className="w-3.5 mr-1.5" />
			<input
				ref={inputRef}
				type="text"
				value={content}
				placeholder={t("todoList.enterTodoWithEnter")}
				onChange={handleContentChange}
				onKeyDown={handleKeyDown}
				className="flex-1 min-w-0 font-medium text-vscode-foreground bg-transparent border-none outline-none text-sm mr-1.5 px-0.5 py-0.5 border-b border-gray-200"
			/>
			<button
				onClick={handleAdd}
				disabled={!content.trim()}
				className="border border-vscode-button-border bg-vscode-button-background text-vscode-button-foreground rounded px-1.5 py-0.5 text-xs mr-1 disabled:cursor-not-allowed disabled:opacity-50">
				{t("todoList.add")}
			</button>
			<button
				onClick={handleCancelAdd}
				className="border border-vscode-button-secondaryBorder bg-vscode-button-secondaryBackground text-vscode-button-secondaryForeground rounded px-1.5 py-0.5 text-xs cursor-pointer">
				{t("todoList.cancel")}
			</button>
		</li>
	)
}

