import * as React from "react"
import { memo } from "react"
import StepButton from "../../../common/StepButton"
import { useAppTranslation } from "@/i18n/TranslationContext"
import { vscode } from "@/utils/vscode"
import { WebviewMessage } from "@roo/WebviewMessage"

const PreviewChangesButton: React.FC<{ config: any }> = ({ config }) => {
	const { t } = useAppTranslation()
	const [modernizationType] = React.useState<string>(config.props?.modernizationType || "")
	const [codePreviewAvailableResult, setCodePreviewAvailableResult] = React.useState<boolean>(false)

	const skipPreview =
		config.props?.upgradeJavaSubSteps?.[0].result.data.finish ||
		config.props?.libertyReplatformingSubSteps?.[0].result.data.finish ||
		false
	const branchName = config.props?.["branchName"] || ""

	const handlePreviewClick = () => {
		const message: WebviewMessage = {
			type: "executeCommand",
			commands: ["bob-code.executePreviewChanges"],
			commandArgs: [true, branchName], // If clicked -> show
			eventId: `preview-changes-${Date.now()}`,
		}

		vscode.postMessage(message)
	}

	const handlePreviewResult = (message: any) => {
		if (message.requestId.startsWith("preview-changes-") && message.commandResult !== undefined) {
			setCodePreviewAvailableResult(message.commandResult.changesAvailable)
		}
	}

	React.useEffect(() => {
		const handleMessage = (event: MessageEvent) => {
			const message = event.data
			if (message.type === "commandResult" && message.requestId) {
				handlePreviewResult(message)
			}
		}

		window.addEventListener("message", handleMessage)

		vscode.postMessage({
			type: "executeCommand",
			commands: ["bob-code.executePreviewChanges"],
			commandArgs: [false, branchName], // On start -> don't display, only show availability
			eventId: `preview-changes-available-${Date.now()}`,
		})

		return () => {
			window.removeEventListener("message", handleMessage)
		}
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [modernizationType])

	if (skipPreview) return <></>
	else
		return (
			<>
				{codePreviewAvailableResult && (
					<StepButton onClick={handlePreviewClick} stepType="secondary">
						<span className="codicon codicon-diff-single" />
						{t("ibm:javaModernization.previewChanges.preview")}
					</StepButton>
				)}
			</>
		)
}

export default memo(PreviewChangesButton)
