import { useAppTranslation } from "@/i18n/TranslationContext"
import { vscode } from "@/utils/vscode"
import { StepLike, StepLikeStatus, UIModernizationAgentStepProps } from "@roo-code/types"
import { ExtensionMessage } from "@roo/ExtensionMessage"
import { WebviewMessage } from "@roo/WebviewMessage"
import * as React from "react"
import { memo } from "react"

import StepButton from "../../../common/StepButton"
import StepContainer from "../../../common/StepContainer"
import { StepProgressNotifications, StepProgressTodoList } from "../../../common/StepProgressComponents"

const EVENT_PREFIX = "uiModernize"

const UIModernize: React.FC<{ config: any }> = ({ config }) => {
	const { t } = useAppTranslation()

	const [stepCompleted, setStepCompleted] = React.useState<boolean>(
		config.props?.["uiModernize.isCompleted"] || false,
	)
	const [subSteps, setSubSteps] = React.useState<StepLike[]>(config.props?.uiModernizationSubSteps || [])
	const [isModernizing, setIsModernizing] = React.useState<boolean>(false)

	const handleProceed = () => {
		setSubSteps([])
		setIsModernizing(true)

		const props: UIModernizationAgentStepProps = {
			envInfo: config.props?.envInfo,
			projectPath: config.props?.projectPath,
			backendProjectPath: config.props?.backendProjectPath,
			backendFramework: config.props?.backendFramework,
			frontendProjectPath: config.props?.frontendProjectPath,
			frontendFramework: config.props?.frontendFramework,
			frontendDesignSystem: config.props?.frontendDesignSystem,
		}

		const message: WebviewMessage = {
			type: "executeCommand",
			commands: ["bob-code.java.executeUIModernizationAgentStep"],
			commandArgs: [props],
			eventId: `${EVENT_PREFIX}-${Date.now()}`,
		}
		vscode.postMessage(message)
	}

	const handleModernizationResult = (message: ExtensionMessage) => {
		if (message.commandResult.subSteps && message.requestId?.startsWith(EVENT_PREFIX)) {
			try {
				const steps: StepLike[] = message.commandResult.subSteps
				setSubSteps(steps)

				const isCompleted: boolean = isModernizationStepCompleted(steps)
				setStepCompleted(isCompleted)
				setIsModernizing(!isCompleted)
			} catch (_) {
				// Error parsing modernization results - reset to failed state
				setStepCompleted(false)
			}
		}
	}

	const isModernizationStepCompleted = (subSteps: StepLike[]): boolean => {
		if (subSteps.length === 0) {
			return false
		}

		return subSteps.every((s) => s.status === StepLikeStatus.SUCCESS || s.status === StepLikeStatus.SKIPPED)
	}

	React.useEffect(() => {
		const handleMessage = (event: MessageEvent) => {
			const message = event.data

			if (message.type === "commandResult" && message.requestId && message.requestId.startsWith(EVENT_PREFIX)) {
				handleModernizationResult(message)
			}
		}

		window.addEventListener("message", handleMessage)
		return () => {
			window.removeEventListener("message", handleMessage)
		}
	})

	return (
		<>
			<h3>{t("ibm:javaModernization.agenticChanges.title")}</h3>
			<p>{t("ibm:javaModernization.agenticChanges.subTitle")}</p>
			<StepContainer>
				<StepButton disabled={isModernizing || stepCompleted} onClick={handleProceed}>
					{t("ibm:javaModernization.proceed")}
				</StepButton>
				<StepProgressTodoList subSteps={subSteps} />
			</StepContainer>
			<StepProgressNotifications subSteps={subSteps} />
		</>
	)
}

export default memo(UIModernize)
