import { ErrorType } from "./errorTypeDetection"

interface ErrorOccurance {
	type: ErrorType
	count: number
	firstSeen: number
	lastSeen: number
}

interface ErrorThresholdConfig {
	threshold: number
	timeWindow: number //ms
	supressUntilThreshold: boolean
}

const ERROR_THRESHOLD_CONFIGS: Record<ErrorType, ErrorThresholdConfig> = {
	[ErrorType.CONTEXT_WINDOW_EXCEEDED]: {
		threshold: 3,
		timeWindow: 60000, // 1 min
		supressUntilThreshold: true,
	},
	[ErrorType.RATE_LIMIT]: {
		threshold: 5,
		timeWindow: 120000, // 2 min
		supressUntilThreshold: true,
	},
	[ErrorType.SERVICE_DISRUPTION]: {
		threshold: 3,
		timeWindow: 60000, // 1 min
		supressUntilThreshold: true,
	},
	// just fail right away
	[ErrorType.AUTHENTICATION]: {
		threshold: 1,
		timeWindow: Infinity,
		supressUntilThreshold: false,
	},
	[ErrorType.BUDGET_EXCEEDED]: {
		threshold: 1,
		timeWindow: Infinity,
		supressUntilThreshold: false,
	},
	[ErrorType.TOO_MANY_IMAGES_DOCUMENTS]: {
		threshold: 1,
		timeWindow: Infinity,
		supressUntilThreshold: false,
	},
	[ErrorType.INVALID_REQUEST]: {
		threshold: 3,
		timeWindow: 60000,
		supressUntilThreshold: true,
	},
	[ErrorType.UNKNOWN]: {
		threshold: Infinity,
		timeWindow: Infinity,
		supressUntilThreshold: true,
	},
}
const CLEANUP_CONFIG = {
	MAX_STALE_TIME: 600000, // 10 min

	CLEANUP_INTERVAL: 60000, // 1 min
}
export class ErrorThresholdTracker {
	private occurrences: Map<string, ErrorOccurance> = new Map()
	private cleanupIntervalId: number | null = null
	constructor() {
		this.startCleanup()
	}

	// returns whether the error should be shown
	recordError(errorType: ErrorType, taskId?: string): boolean {
		const config = ERROR_THRESHOLD_CONFIGS[errorType]
		const key = taskId ? `${taskId}-${errorType}` : errorType
		const timeNow = Date.now()
		let occurrence = this.occurrences.get(key)

		if (!occurrence) {
			occurrence = {
				type: errorType,
				count: 0,
				firstSeen: timeNow,
				lastSeen: timeNow,
			}
			this.occurrences.set(key, occurrence)
		}
		if (timeNow - occurrence.lastSeen > config.timeWindow) {
			occurrence.count = 0
			occurrence.firstSeen = timeNow
		}
		occurrence.count++
		occurrence.lastSeen = timeNow
		if (config.supressUntilThreshold) {
			return occurrence.count >= config.threshold
		}
		return true
	}

	resetError(errorType: ErrorType, taskId?: string) {
		const key = taskId ? `${taskId}-${errorType}` : errorType
		this.occurrences.delete(key)
	}

	resetAllErrorsForTask(taskId: string) {
		const keysToDelete: string[] = []
		this.occurrences.forEach((_, key) => {
			if (key.startsWith(`${taskId}-`)) {
				keysToDelete.push(key)
			}
		})
		keysToDelete.forEach((key) => this.occurrences.delete(key))
	}

	getThreshold(errorType: ErrorType): number {
		return ERROR_THRESHOLD_CONFIGS[errorType].threshold
	}
	shouldSupress(errorType: ErrorType): boolean {
		return ERROR_THRESHOLD_CONFIGS[errorType].supressUntilThreshold
	}
	private cleanup(): void {
		const now = Date.now()
		const keysToDelete: string[] = []

		this.occurrences.forEach((occurrence, key) => {
			const timeSinceLastSeen = now - occurrence.lastSeen

			if (timeSinceLastSeen > CLEANUP_CONFIG.MAX_STALE_TIME) {
				keysToDelete.push(key)
			}
		})

		keysToDelete.forEach((key) => this.occurrences.delete(key))
	}

	private startCleanup(): void {
		if (this.cleanupIntervalId !== null) {
			return
		}

		this.cleanupIntervalId = window.setInterval(() => {
			this.cleanup()
		}, CLEANUP_CONFIG.CLEANUP_INTERVAL)
	}

	private stopCleanup(): void {
		if (this.cleanupIntervalId !== null) {
			window.clearInterval(this.cleanupIntervalId)
			this.cleanupIntervalId = null
		}
	}

	dispose(): void {
		this.stopCleanup()
		this.occurrences.clear()
	}
}

let globalTracker: ErrorThresholdTracker | null = null

export function getErrorThresholdTracker(): ErrorThresholdTracker {
	if (!globalTracker) {
		globalTracker = new ErrorThresholdTracker()
	}
	return globalTracker
}
