import { useCallback, useState, memo, useMemo, useEffect } from "react" // ibm_change
import { useEvent } from "react-use"
import { t } from "i18next"
import { ChevronDown, OctagonX } from "lucide-react"
import { Warning, Information } from "@carbon/icons-react" // ibm_change

import { CommandExecutionStatus, commandExecutionStatusSchema } from "@roo-code/types"

import { ExtensionMessage } from "@roo/ExtensionMessage"
import { safeJsonParse } from "@roo/safeJsonParse"

import { COMMAND_OUTPUT_STRING } from "@roo/combineCommandSequences"

import { vscode } from "@src/utils/vscode"
import { useExtensionState } from "@src/context/ExtensionStateContext"
import { cn } from "@src/lib/utils"

import { Button, StandardTooltip } from "@src/components/ui"
import CodeBlock from "@src/components/common/CodeBlock"

import { CommandPatternSelector } from "./CommandPatternSelector"
import { logger } from "@/ibm/utils/logger"

interface CommandPattern {
	pattern: string
	description?: string
}

// ibm_change_start: Added security warning props
interface CommandExecutionProps {
	executionId: string
	text?: string
	icon?: JSX.Element | null
	title?: JSX.Element | null
	securityWarning?: { reason?: string }
	onSecurityAcknowledged?: (acknowledged: boolean) => void
}
// ibm_change_end

export const CommandExecution = ({
	executionId,
	text,
	icon,
	title,
	securityWarning,
	onSecurityAcknowledged,
}: CommandExecutionProps) => {
	// ibm_change: added securityWarning and onSecurityAcknowledged
	const {
		terminalShellIntegrationDisabled = false,
		allowedCommands = [],
		deniedCommands = [],
		setAllowedCommands,
		setDeniedCommands,
	} = useExtensionState()

	const { command, output: parsedOutput } = useMemo(() => parseCommandAndOutput(text), [text])

	// If we aren't opening the VSCode terminal for this command then we default
	// to expanding the command execution output.
	const [isExpanded, setIsExpanded] = useState(terminalShellIntegrationDisabled)
	const [streamingOutput, setStreamingOutput] = useState("")
	const [status, setStatus] = useState<CommandExecutionStatus | null>(null)
	const [securityAcknowledged, setSecurityAcknowledged] = useState(false) // ibm_change: track security acknowledgment

	// The command's output can either come from the text associated with the
	// task message (this is the case for completed commands) or from the
	// streaming output (this is the case for running commands).
	const output = streamingOutput || parsedOutput

	// ibm_change_start: Extract command patterns using async API
	const [commandPatterns, setCommandPatterns] = useState<CommandPattern[]>([])

	useEffect(() => {
		const fetchCommandPatterns = async () => {
			try {
				const allCommands = await vscode.postMessageAwaitResponse<string[]>({
					type: "commandPatterns",
					text: command,
				})

				const allPatterns = allCommands.map((cmd) => ({ pattern: cmd }))
				setCommandPatterns(allPatterns)
			} catch (error) {
				logger.error("Failed to parse command patterns:", error)
				setCommandPatterns([])
			}
		}

		if (command) {
			fetchCommandPatterns()
		}
	}, [command])
	// ibm_change_end

	// Handle pattern changes
	const handleAllowPatternChange = (pattern: string) => {
		const isAllowed = allowedCommands.includes(pattern)
		const newAllowed = isAllowed ? allowedCommands.filter((p) => p !== pattern) : [...allowedCommands, pattern]
		const newDenied = deniedCommands.filter((p) => p !== pattern)

		setAllowedCommands(newAllowed)
		setDeniedCommands(newDenied)

		vscode.postMessage({
			type: "updateSettings",
			updatedSettings: { allowedCommands: newAllowed, deniedCommands: newDenied },
		})
	}

	const handleDenyPatternChange = (pattern: string) => {
		const isDenied = deniedCommands.includes(pattern)
		const newDenied = isDenied ? deniedCommands.filter((p) => p !== pattern) : [...deniedCommands, pattern]
		const newAllowed = allowedCommands.filter((p) => p !== pattern)

		setAllowedCommands(newAllowed)
		setDeniedCommands(newDenied)

		vscode.postMessage({
			type: "updateSettings",
			updatedSettings: { allowedCommands: newAllowed, deniedCommands: newDenied },
		})
	}

	const onMessage = useCallback(
		(event: MessageEvent) => {
			const message: ExtensionMessage = event.data

			if (message.type === "commandExecutionStatus") {
				const result = commandExecutionStatusSchema.safeParse(safeJsonParse(message.text, {}))

				if (result.success) {
					const data = result.data

					if (data.executionId !== executionId) {
						return
					}

					switch (data.status) {
						case "started":
							setStatus(data)
							break
						case "output":
							setStreamingOutput(data.output)
							break
						case "fallback":
							setIsExpanded(true)
							break
						default:
							setStatus(data)
							break
					}
				}
			}
		},
		[executionId],
	)

	useEvent("message", onMessage)

	return (
		<>
			<div className="flex flex-row items-center justify-between gap-2 mb-1">
				<div className="flex flex-row items-center gap-2 flex-1 min-w-0">
					{icon}
					{title}
					{status?.status === "exited" && (
						<div className="flex flex-row items-center gap-2 font-mono text-xs">
							<StandardTooltip
								content={t("chat.commandExecution.exitStatus", { exitStatus: status.exitCode })}>
								<div
									className={cn(
										"rounded-full size-2",
										status.exitCode === 0 ? "bg-green-600" : "bg-red-600",
									)}
								/>
							</StandardTooltip>
						</div>
					)}
				</div>
				<div className="flex flex-row items-center justify-between gap-2 px-1 flex-shrink-0">
					<div className="flex flex-row items-center gap-1">
						{status?.status === "started" && (
							<div className="flex flex-row items-center gap-2 font-mono text-xs">
								{status.pid && <div className="whitespace-nowrap">(PID: {status.pid})</div>}
								<StandardTooltip content={t("chat:commandExecution.abort")}>
									<Button
										variant="ghost"
										size="icon"
										onClick={() =>
											vscode.postMessage({
												type: "terminalOperation",
												terminalOperation: "abort",
											})
										}>
										<OctagonX className="size-4" />
									</Button>
								</StandardTooltip>
							</div>
						)}
						{output.length > 0 && (
							<Button variant="ghost" size="icon" onClick={() => setIsExpanded(!isExpanded)}>
								<ChevronDown
									className={cn(
										"size-4 transition-transform duration-300",
										isExpanded && "rotate-180",
									)}
								/>
							</Button>
						)}
					</div>
				</div>
			</div>

			<div className="bg-vscode-editor-background border border-vscode-border rounded-xs mt-2">
				<div className="p-2">
					<CodeBlock source={command} language="shell" />
					<OutputContainer isExpanded={isExpanded} output={output} />
				</div>
				{/* ibm_change_start: Security warning line */}
				{securityWarning && (
					<div className="border-t border-vscode-panel-border/50 px-3 py-2 space-y-1">
						<div className="flex items-center justify-between gap-2 flex-wrap">
							<div className="flex items-center gap-2">
								<Warning className="text-vscode-editorWarning-foreground size-4 flex-shrink-0" />
								<span className="text-xs text-vscode-descriptionForeground">
									{t("ibm:chat.securityWarning.inlineTitle")}
								</span>
								<StandardTooltip
									content={securityWarning.reason || t("ibm:chat.securityWarning.defaultReason")}>
									<Information className="text-vscode-descriptionForeground size-3.5 cursor-help flex-shrink-0" />
								</StandardTooltip>
							</div>
							<label className="flex items-center gap-2 text-xs cursor-pointer -ml-1">
								<input
									type="checkbox"
									checked={securityAcknowledged}
									onChange={(e) => {
										setSecurityAcknowledged(e.target.checked)
										onSecurityAcknowledged?.(e.target.checked)
									}}
									className="accent-vscode-button-background size-4"
								/>
								<span className="text-vscode-descriptionForeground">
									{t("ibm:chat.securityWarning.acknowledge")}
								</span>
							</label>
						</div>
					</div>
				)}
				{/* ibm_change_end */}
				{command &&
					command.trim() &&
					commandPatterns.length > 0 && ( //ibm_change
						<CommandPatternSelector
							patterns={commandPatterns}
							allowedCommands={allowedCommands}
							deniedCommands={deniedCommands}
							onAllowPatternChange={handleAllowPatternChange}
							onDenyPatternChange={handleDenyPatternChange}
						/>
					)}
			</div>
		</>
	)
}

CommandExecution.displayName = "CommandExecution"

const OutputContainerInternal = ({ isExpanded, output }: { isExpanded: boolean; output: string }) => (
	<div
		className={cn("overflow-hidden", {
			"max-h-0": !isExpanded,
			"max-h-[100%] mt-1 pt-1 border-t border-border/25": isExpanded,
		})}>
		{output.length > 0 && <CodeBlock source={output} language="log" />}
	</div>
)

const OutputContainer = memo(OutputContainerInternal)

const parseCommandAndOutput = (text: string | undefined) => {
	if (!text) {
		return { command: "", output: "" }
	}

	const index = text.indexOf(COMMAND_OUTPUT_STRING)

	if (index === -1) {
		return { command: text, output: "" }
	}

	return {
		command: text.slice(0, index),
		output: text.slice(index + COMMAND_OUTPUT_STRING.length),
	}
}
