import React, { memo, useMemo, useState, useCallback, useEffect} from "react"
import { Mode } from "@roo/modes"
import { appendImages } from "@src/utils/imageUtils"
import { MAX_IMAGES_PER_MESSAGE } from "@/components/chat/ChatView"
import { vscode } from "@src/utils/vscode"
import { useExtensionState } from "@src/context/ExtensionStateContext"
import { useSelectedModel } from "@/components/ui/hooks/useSelectedModel"

import { parseTool } from "./utils"

// Import router components
import ToolRouter from "./ToolRouter"
import SayRouter from "./SayRouter"
import AskRouter from "./AskRouter"
import { ChatRowProps } from "@/components/chat/ChatRow"

/**
 * Props for the ChatRowContent component
 */
export type ChatRowContentProps = Omit<ChatRowProps, "onHeightChange">

/**
 * Main router component that determines which specific component to render based on the message type
 */
export const ChatRowContent: React.FC<ChatRowContentProps> = (props) => {
	const {
		message,
		lastModifiedMessage,
		isExpanded,
		isLast,
		isStreaming,
		onToggleExpand,
		onSuggestionClick,
		onFollowUpUnmount,
		onBatchFileResponse,
		isFollowUpAnswered,
		editable,
		taskId,
		onSecurityAcknowledged, // ibm_change: for command security warning acknowledgment
	} = props

	// ibm_change_start: Add edit functionality state and handlers
	const { mode, apiConfiguration } = useExtensionState()
	const { info: model } = useSelectedModel(apiConfiguration)
	const [isEditing, setIsEditing] = useState(false)
	const [editedContent, setEditedContent] = useState("")
	const [editMode, setEditMode] = useState<Mode>(mode || "code")
	const [editImages, setEditImages] = useState<string[]>([])

	// Handle message events for image selection during edit mode
	useEffect(() => {
		const handleMessage = (event: MessageEvent) => {
			const msg = event.data
			if (msg.type === "selectedImages" && msg.context === "edit" && msg.messageTs === message.ts && isEditing) {
				setEditImages((prevImages) => appendImages(prevImages, msg.images, MAX_IMAGES_PER_MESSAGE))
			}
		}

		window.addEventListener("message", handleMessage)
		return () => window.removeEventListener("message", handleMessage)
	}, [isEditing, message.ts])

	// Handle edit button click
	const handleEditClick = useCallback(() => {
		setIsEditing(true)
		setEditedContent(message.text || "")
		setEditImages(message.images || [])
		setEditMode(mode || "code")
		// Edit mode is now handled entirely in the frontend
		// No need to notify the backend
	}, [message.text, message.images, mode])

	// Handle cancel edit
	const handleCancelEdit = useCallback(() => {
		setIsEditing(false)
		setEditedContent(message.text || "")
		setEditImages(message.images || [])
		setEditMode(mode || "code")
	}, [message.text, message.images, mode])

	// Handle save edit
	const handleSaveEdit = useCallback(() => {
		setIsEditing(false)
		// Send edited message to backend
		vscode.postMessage({
			type: "submitEditedMessage",
			value: message.ts,
			editedMessageContent: editedContent,
			images: editImages,
		})
	}, [message.ts, editedContent, editImages])

	// Handle image selection for editing
	const handleSelectImages = useCallback(() => {
		vscode.postMessage({ type: "selectImages", context: "edit", messageTs: message.ts })
	}, [message.ts])
	// ibm_change_end: Add edit functionality state and handlers

	// Parse tool information
	const tool = useMemo(() => parseTool(message), [message])

	// Render tool messages
	if (tool) {
		return (
			<ToolRouter
				message={message}
				tool={tool}
				isExpanded={isExpanded}
				onToggleExpand={onToggleExpand}
				onBatchFileResponse={onBatchFileResponse}
				editable={editable}
			/>
		)
	}

	// Render say messages
	if (message.type === "say") {
		return (
			<SayRouter
				message={message}
				lastModifiedMessage={lastModifiedMessage}
				isExpanded={isExpanded}
				isLast={isLast}
				isStreaming={isStreaming}
				onToggleExpand={onToggleExpand}
				taskId={taskId}
				// ibm_change: Pass edit functionality props
				isEditing={isEditing}
				editedContent={editedContent}
				editMode={editMode}
				editImages={editImages}
				model={model}
				onEditClick={handleEditClick}
				onCancelEdit={handleCancelEdit}
				onSaveEdit={handleSaveEdit}
				onSelectImages={handleSelectImages}
				setEditedContent={setEditedContent}
				setEditImages={setEditImages}
				setEditMode={setEditMode}
			/>
		)
	}

	// Render ask messages
	if (message.type === "ask") {
		return (
			<AskRouter
				message={message}
				onSuggestionClick={onSuggestionClick}
				onFollowUpUnmount={onFollowUpUnmount}
				isFollowUpAnswered={isFollowUpAnswered}
				onSecurityAcknowledged={onSecurityAcknowledged}
			/>
		)
	}

	return null
}

export default memo(ChatRowContent)

