import React from "react"
import { CommandExecution } from "@/components/chat/CommandExecution"
import { useTranslation } from "react-i18next"
import { Terminal } from "@carbon/icons-react" // ibm_change
import { ClineMessage } from "@roo-code/types"

/**
 * Props for CommandMessage component
 */
export interface CommandMessageProps {
	message: ClineMessage
	securityWarning?: boolean // When ask === "command_security_warning"
	onSecurityAcknowledged?: (acknowledged: boolean) => void // Callback for security acknowledgment
}

/**
 * Component for handling command execution messages
 */
export const CommandMessage: React.FC<CommandMessageProps> = ({ message, securityWarning, onSecurityAcknowledged }) => {
	const { t } = useTranslation()
	const normalColor = "var(--vscode-foreground)"
	// Generate icon and title based on message
	const icon = <Terminal style={{ color: normalColor, marginBottom: "-1.5px" }} />

	const title = <span style={{ color: normalColor, fontWeight: "bold" }}>{t("chat:runCommand.title")}:</span>

	return (
		<CommandExecution
			executionId={message.ts.toString()}
			text={message.text}
			icon={icon}
			title={title}
			securityWarning={securityWarning ? { reason: t("ibm:chat.securityWarning.defaultReason") } : undefined}
			onSecurityAcknowledged={onSecurityAcknowledged}
		/>
	)
}

export default CommandMessage

