import { ActionIndicator, ActionIndicatorProps } from "@/ibm/components/common/actionIndicator/ActionIndicator"
import "./progressNotification.css"
import * as React from "react"

interface ProgressNotificationProps {
	mode: ActionIndicatorProps["mode"]
	message: string
	rightComponent?: React.ReactNode
}

export const ProgressNotification: React.FC<ProgressNotificationProps> = ({ mode, message, rightComponent }) => {
	return (
		<div className="ibm-progress-notification-container">
			<div className="ibm-progress-notification-main">
				<ActionIndicator mode={mode} />
				<p>{message}</p>
			</div>
			{rightComponent && (
				<div className="ibm-progress-notification-right">
					{rightComponent}
				</div>
			)}
		</div>
	)
}
