import { memo } from "react"

import { ToolUseBlock, ToolUseBlockHeader } from "../common/ToolUseBlock"
import { vscode } from "@src/utils/vscode"
import { formatPathTooltip } from "@src/utils/formatPathTooltip"
import { PathTooltip } from "../ui/PathTooltip"

interface FilePermissionItem {
	path: string
	lineSnippet?: string
	isOutsideWorkspace?: boolean
	key: string
	content?: string // full path
}

interface BatchFilePermissionProps {
	files: FilePermissionItem[]
	onPermissionResponse?: (response: { [key: string]: boolean }) => void
	ts: number
	style?: React.CSSProperties // ibm_change: add style prop
}

export const BatchFilePermission = memo(
	({ files = [], onPermissionResponse, ts, style = {} }: BatchFilePermissionProps) => {
		// Don't render if there are no files or no response handler
		if (!files?.length || !onPermissionResponse) {
			return null
		}

		return (
			<div style={style}>
				{/* Individual files */}
				<div className="flex flex-col gap-0 border border-border rounded-md">
					{files.map((file, index) => {
						return (
							<div
								key={`${file.path}-${ts}`}
								className={`flex items-center gap-2 ${index ? "border-t border-vscode-dropdown-border" : ""}`}>
								<ToolUseBlock className="flex-1" style={style}>
									<ToolUseBlockHeader
										onClick={() => vscode.postMessage({ type: "openFile", text: file.content })}>
										{file.path?.startsWith(".") && <span>.</span>}
										<PathTooltip
											content={formatPathTooltip(
												file.path,
												file.lineSnippet ? ` ${file.lineSnippet}` : undefined,
											)}>
											<span className="whitespace-nowrap overflow-hidden text-ellipsis text-left mr-2 rtl">
												{formatPathTooltip(
													file.path,
													file.lineSnippet ? ` ${file.lineSnippet}` : undefined,
												)}
											</span>
										</PathTooltip>
										<div className="flex-grow"></div>
										<span className="codicon codicon-link-external text-[13.5px] my-[1px]" />
									</ToolUseBlockHeader>
								</ToolUseBlock>
							</div>
						)
					})}
				</div>
			</div>
		)
	},
)

BatchFilePermission.displayName = "BatchFilePermission"
