import React, { memo, useState } from "react"
import CodeAccordian, { CodeAccordianProps } from "@/components/common/CodeAccordian"
import { vscode } from "@src/utils/vscode"

// Common file interface that covers both permission and diff files
interface BaseFileItem {
	path: string
	key: string
	content?: string
}

// Permission file specific properties
interface PermissionFileItem extends BaseFileItem {
	lineSnippet?: string
	isOutsideWorkspace?: boolean
	type: "permission"
}

// Diff file specific properties
interface DiffFileItem extends BaseFileItem {
	changeCount: number
	diffs?: Array<{
		content: string
		startLine?: number
	}>
	type: "diff"
}

// Union type for both file types
type FileItem = PermissionFileItem | DiffFileItem

interface BatchFileGroupProps {
	files: FileItem[]
	ts: number
	style?: React.CSSProperties
	onPermissionResponse?: (response: { [key: string]: boolean }) => void
}

export const BatchFileGroup = memo(({ files = [], ts, style = {}, onPermissionResponse }: BatchFileGroupProps) => {
	const [expandedFiles, setExpandedFiles] = useState<Record<string, boolean>>({})

	// Don't render if there are no files
	if (!files?.length) {
		return null
	}

	// For permission files, we need a response handler
	const hasPermissionFiles = files.some((file) => file.type === "permission")
	if (hasPermissionFiles && !onPermissionResponse) {
		return null
	}

	const handleToggleExpand = (filePath: string) => {
		setExpandedFiles((prev) => ({
			...prev,
			[filePath]: !prev[filePath],
		}))
	}

	return (
		<div className="pt-1.5 rounded-b" style={style}>
			<div className="flex flex-col gap-0">
				{files.map((file) => {
					const codeAccordianProps: CodeAccordianProps = {
						path: file.path,
						language: "diff",
						isExpanded: expandedFiles[file.path] || false,
						onToggleExpand: () => handleToggleExpand(file.path),
						style,
					}
					if (file.type === "diff") {
						// Handle diff files with CodeAccordian
						const diffFile = file as DiffFileItem
						const combinedDiff =
							diffFile.diffs?.map((diff) => diff.content).join("\n\n") || diffFile.content || ""

						codeAccordianProps.code = combinedDiff
					} else {
						codeAccordianProps.onJumpToFile = () =>
							vscode.postMessage({ type: "openFile", text: file.content })

						codeAccordianProps.reason = file.lineSnippet
					}
					return (
						<div key={`${file.path}-${ts}`}>
							<CodeAccordian {...codeAccordianProps} />
						</div>
					)
				})}
			</div>
		</div>
	)
})

BatchFileGroup.displayName = "BatchFileGroup"

