type AutoApproveToggleProps = AutoApproveToggles & {
	onToggle: (key: AutoApproveSetting, value: boolean) => void
	isVisible?: boolean /* ibm_change */
	hiddenKeys?: AutoApproveSetting[] // ibm_change
}

// ibm_change_start
export const AutoApproveToggle = ({ onToggle, isVisible = true, hiddenKeys, ...props }: AutoApproveToggleProps) => {
	const { t } = useAppTranslation()

	return (
		<div className={cn("flex flex-row flex-wrap gap-1 py-1")}>
			{Object.values(autoApproveSettingsConfig).filter(({ key }) => !hiddenKeys?.includes(key)).map( // ibm_change
				({ key, descriptionKey, labelKey, icon: IconComponent, testId }) => (
					<StandardTooltip
						key={key}
						content={t(descriptionKey || "")}
						delayDuration={500}
						disableHoverableContent={true}>
						<Button
							disabled={!isVisible} /* ibm_change */
							variant={props[key] ? "primary" : "secondary"}
							onClick={() => onToggle(key, !props[key])}
							aria-label={t(labelKey)}
							aria-pressed={!!props[key]}
							data-testid={testId}
							className={cn(
								"h-6 px-1 flex items-center gap-1.5 text-xs whitespace-nowrap",
								"focus:outline-none focus-visible:ring-1 focus-visible:ring-vscode-focusBorder",
								!props[key] && "opacity-50",
							)}>
							<IconComponent size={14} /> {/* ibm_change */}
							<span>{t(labelKey)}</span>
						</Button>
					</StandardTooltip>
				),
			)}
		</div>
	)
}
// ibm_change_end
