import React, { memo } from "react"
import { BudgetExceededWarning } from "./BudgetExceededWarning"
import ServiceDisruptionWarning from "./ServiceDisruptionWarning"
import ContextWindowExceededWarning from "./ContextWindowExceededWarning"
import TooManyImagesDocumentsWarning from "./TooManyImagesDocumentsWarning"
import { detectErrorType, ErrorType } from "./errorTypeDetection"
import { ClineMessage } from "@roo-code/types"
import { getErrorThresholdTracker } from "./errorThresholdTracker"
import AuthenticationWarning from "./AuthenticationWarning"
import RateLimitWarning from "./RateLimitWarning"
import InvalidRequestWarning from "./InvalidRequestWarning"

interface ApiErrorBoundaryProps {
	// Error state
	apiRequestFailedMessage?: string
	apiReqStreamingFailedMessage?: string
	cost?: number
	// Message data for error components
	message: ClineMessage
	// Children to render if no error
	children: React.ReactNode
	taskId?: string
}
function shouldProcessErrorDetection(
	message: ClineMessage,
	apiRequestFailedMessage?: string,
	apiReqStreamingFailedMessage?: string,
): boolean {
	const hasExplicitError = !!(apiRequestFailedMessage || apiReqStreamingFailedMessage)
	if (hasExplicitError) {
		return true
	}

	if (message.ask === "api_req_failed") {
		return true
	}

	if (message.say === "api_req_started") {
		return true
	}

	return false
}

function shouldShowError(message: ClineMessage, errorType: ErrorType, taskId?: string): boolean {
	const tracker = getErrorThresholdTracker()

	if (message.say === "api_req_retry_delayed") {
		return false
	}
	if (message.ask === "api_req_failed") {
		return true
	}
	return tracker.recordError(errorType, taskId)
}

/**
 * A component that acts as a boundary for API errors in the chat interface.
 * It detects the type of error and renders the appropriate error component.
 * If no specific error handler exists or no error is detected, it renders the original roo code children.
 */
export const ApiErrorBoundary = memo(
	({ apiRequestFailedMessage, apiReqStreamingFailedMessage, message, children, taskId }: ApiErrorBoundaryProps) => {
		if (!shouldProcessErrorDetection(message, apiRequestFailedMessage, apiReqStreamingFailedMessage)) {
			// This is a regular message, not an error context - render children normally
			return <>{children}</>
		}

		// Only process actual error messages, not normal message text
		// We explicitly do NOT fall back to message.text to avoid false positives
		const errorMessage =
			apiRequestFailedMessage ||
			apiReqStreamingFailedMessage ||
			(message.ask === "api_req_failed" ? message.text : "") ||
			""

		if (errorMessage) {
			// Detect error type
			const errorDetails = detectErrorType(errorMessage)

			if (!shouldShowError(message, errorDetails.type, taskId)) {
				return <>{children}</>
			}

			// Render the appropriate error component based on the error type
			switch (errorDetails.type) {
				case ErrorType.BUDGET_EXCEEDED:
					return <BudgetExceededWarning errorDetails={errorDetails} />
				case ErrorType.SERVICE_DISRUPTION:
					return (
						<ServiceDisruptionWarning
							retryAttempt={errorDetails.data?.retryAttempt}
							retryCountdown={errorDetails.data?.retryCountdown}
							messageKey={errorDetails.messageKey}
						/>
					)
				case ErrorType.CONTEXT_WINDOW_EXCEEDED:
					return <ContextWindowExceededWarning />
				case ErrorType.TOO_MANY_IMAGES_DOCUMENTS:
					return <TooManyImagesDocumentsWarning />
				case ErrorType.AUTHENTICATION:
					return <AuthenticationWarning />
				case ErrorType.RATE_LIMIT:
					return <RateLimitWarning />
				case ErrorType.INVALID_REQUEST:
					return <InvalidRequestWarning />
				default:
				// Render generic error message from the children component
			}
		}

		// If no error or error handling needed, render the children
		return <>{children}</>
	},
)

export default ApiErrorBoundary

