import React from "react"
import CodeAccordian from "@/components/common/CodeAccordian"
import { safeJsonParse } from "@roo/safeJsonParse"
import { ClineSayTool } from "@roo/ExtensionMessage"
import { ClineMessage } from "@roo-code/types"
import { feedbackBackgroundColor } from "./UserFeedbackMessage"

/**
 * Props for UserFeedbackDiffMessage component
 */
export interface UserFeedbackDiffMessageProps {
	message: ClineMessage
	isExpanded: boolean
	onToggleExpand: () => void
}

/**
 * Component for displaying user feedback diff messages
 */
export const UserFeedbackDiffMessage: React.FC<UserFeedbackDiffMessageProps> = ({
	message,
	isExpanded,
	onToggleExpand,
}) => {
	const tool = safeJsonParse<ClineSayTool>(message.text)

	return (
		<div style={{ marginTop: -10, width: "100%" }}>
			<CodeAccordian
				code={tool?.diff}
				language="diff"
				isFeedback={true}
				isExpanded={isExpanded}
				onToggleExpand={onToggleExpand}
				style={{
					backgroundColor: feedbackBackgroundColor,
				}}
			/>
		</div>
	)
}

export default UserFeedbackDiffMessage

