import { vscode } from "@/utils/vscode"

export async function callCommand<T>(command: string, ...args: any[]): Promise<T | undefined> {
	return new Promise((resolve) => {
		const messageId = `${Date.now()}-${Math.random()}`
		const handler = (event: MessageEvent) => {
			if (event.data?.type === "commandResult" && event.data.requestId === messageId) {
				window.removeEventListener("message", handler)
				resolve(event.data.commandResult)
			}
		}

		window.addEventListener("message", handler)

		vscode.postMessage({ type: "executeCommand", commands: [command], eventId: messageId, commandArgs: args })
	})
}
