import React, { useEffect, useState } from "react"
import { Zap } from "lucide-react"
import { Trans } from "react-i18next"

import { useAppTranslation } from "@/i18n/TranslationContext"
import { useExtensionState } from "@/context/ExtensionStateContext"
import { Button, Popover, PopoverContent, PopoverTrigger, StandardTooltip } from "@/components/ui"
import { useRooPortal } from "@/components/ui/hooks/useRooPortal"
import { cn } from "@/lib/utils"
import { vscode } from "@/utils/vscode"
import { useBuildDocLink } from "@/utils/docLinks" // ibm_change

import { SlashCommandsList } from "./SlashCommandsList"

interface SlashCommandsPopoverProps {
	className?: string
}

export const SlashCommandsPopover: React.FC<SlashCommandsPopoverProps> = ({ className }) => {
	const buildDocLink = useBuildDocLink() // ibm_change
	const { t } = useAppTranslation()
	const { commands } = useExtensionState()
	const [isOpen, setIsOpen] = useState(false)
	const portalContainer = useRooPortal("roo-portal")

	// Request commands when popover opens
	useEffect(() => {
		if (isOpen && (!commands || commands.length === 0)) {
			handleRefresh()
		}
	}, [isOpen, commands])

	const handleRefresh = () => {
		vscode.postMessage({ type: "requestCommands" })
	}

	const handleOpenChange = (open: boolean) => {
		setIsOpen(open)
		if (open) {
			// Always refresh when opening to get latest commands
			handleRefresh()
		}
	}

	return (
		<Popover open={isOpen} onOpenChange={handleOpenChange}>
			<StandardTooltip content={t("chat:slashCommands.tooltip")}>
				<PopoverTrigger asChild>
					<Button
						variant="ghost"
						size="sm"
						className={cn(
							"bg-transparent border-none",
							"cursor-pointer",
							"relative inline-flex items-center justify-center",
							"rounded-md",
							"text-vscode-foreground opacity-85",
							"transition-all duration-150",
							"w-[25px] h-[25px] p-0.5",
							"active:bg-[rgba(255,255,255,0.1)]",
							"hover:opacity-100 hover:bg-[rgba(255,255,255,0.03)] hover:border-[rgba(255,255,255,0.15)]",
							"focus:outline-none focus-visible:ring-1 focus-visible:ring-vscode-focusBorder",
							className,
						)}>
						<Zap className="w-4 h-4" />
					</Button>
				</PopoverTrigger>
			</StandardTooltip>

			<PopoverContent
				align="start"
				sideOffset={4}
				container={portalContainer}
				className="p-0 overflow-hidden min-w-80 max-w-9/10">
				<div className="flex flex-col w-full">
					{/* Header section */}
					<div className="p-3 border-b border-vscode-dropdown-border">
						<p className="m-0 text-xs text-vscode-descriptionForeground">
							<Trans
								i18nKey="chat:slashCommands.description"
								components={{
									DocsLink: (
										<a
											className="focus:outline-none focus-visible:ring-1 focus-visible:ring-vscode-focusBorder" //ibm_change
											href={buildDocLink("features/slash-commands")} //ibm_change
											target="_blank"
											rel="noopener noreferrer">
											Docs
										</a>
									),
								}}
							/>
						</p>
					</div>

					{/* Commands list */}
					<SlashCommandsList commands={commands || []} onRefresh={handleRefresh} />
				</div>
			</PopoverContent>
		</Popover>
	)
}
