import { AlertCircle, Loader2 } from "lucide-react"
import React, { memo } from "react"
import AnalyzeArchitectureStep from "./steps/analyzeArchitectureStep"
import AnalyzeJavaProjectStep from "./steps/analyzeJavaProjectStep"
import DeployAppStep from "./steps/deployAppStep"
import GenerateMermaidSummaryStep from "./steps/generateMermaidSummaryStep"
import ReplatformLibertyStep from "./steps/replatformLibertyStep"
import RunE2EStep from "./steps/runE2EStep"
import RunLibertyMod from "./steps/runLibertyMod"
import RunLibertyRecipesStep from "./steps/runLibertyRecipesStep"
import RunRecipesStep from "./steps/runRecipesStep"
import RunAndValidateStep from "./steps/runValidationStep"
import SelectModernizationTypeStep from "./steps/selectModernizationTypeStep"
import SetupProjectStep from "./steps/setupProjectStep"
import UIModernize from "./steps/uiModernize"
import UnitTestingStep from "./steps/unitTestingStep"
import UpgradeJavaVersionStep from "./steps/upgradeJavaVersionStep"
import { _StepId } from "./types"

// Type definitions
export type StepId = (typeof _StepId)[keyof typeof _StepId]

interface JavaModernizationConfig {
	stepId: StepId
	props?: {
		isLoading?: boolean
		error?: string | null
		[key: string]: any
	}
	[key: string]: any
}

// Mapping of step IDs to their components
const STEP_COMPONENTS: Record<StepId, React.ComponentType<{ config: JavaModernizationConfig }>> = {
	[_StepId.ANALYZE_PROJECT]: AnalyzeJavaProjectStep,
	[_StepId.SELECT_MODERNIZATION_TYPE]: SelectModernizationTypeStep,
	[_StepId.RUN_RECIPES]: RunRecipesStep,
	[_StepId.RUN_LIBERTY_RECIPES]: RunLibertyRecipesStep,
	[_StepId.UPGRADE_JAVA]: UpgradeJavaVersionStep,
	[_StepId.RUN_VALIDATION]: RunAndValidateStep,
	[_StepId.DEPLOY_APPLICATION]: DeployAppStep,
	[_StepId.UNIT_TESTING]: UnitTestingStep,
	[_StepId.E2E_VALIDATION]: RunE2EStep,
	[_StepId.SETUP_PROJECT]: SetupProjectStep,
	[_StepId.ANALYZE_ARCH]: AnalyzeArchitectureStep,
	[_StepId.UI_MODERNIZE]: UIModernize,
	[_StepId.ANALYZE_AMA]: RunLibertyMod,
	[_StepId.REPLATFORM_LIBERTY]: ReplatformLibertyStep,
	[_StepId.GENERATE_MERMAID_SUMMARY]: GenerateMermaidSummaryStep,
}

// Error display component
const ErrorDisplay: React.FC<{ message: string }> = ({ message }) => (
	<div className="flex items-center gap-3 p-4 rounded-lg bg-vscode-inputValidation-errorBackground border border-vscode-inputValidation-errorBorder">
		<AlertCircle className="w-5 h-5 text-vscode-errorForeground flex-shrink-0" />
		<div className="flex flex-col gap-1">
			<div className="text-sm font-medium text-vscode-errorForeground">Error</div>
			<div className="text-sm text-vscode-descriptionForeground">{message}</div>
		</div>
	</div>
)

// Loading display component
const LoadingDisplay: React.FC = () => (
	<div className="flex items-center justify-center gap-3 p-8">
		<Loader2 className="w-5 h-5 text-vscode-foreground animate-spin" />
		<div className="text-sm text-vscode-descriptionForeground">Loading modernization workflow...</div>
	</div>
)

const JavaModernizationChat: React.FC<{ config: JavaModernizationConfig | null }> = ({ config }) => {
	// Handle missing config
	if (!config) {
		return (
			<div className="flex flex-col gap-4 p-4">
				<ErrorDisplay message="Configuration is missing. Please try refreshing the page." />
			</div>
		)
	}

	// Handle loading state
	if (config.props?.isLoading) {
		return (
			<div className="flex flex-col gap-4 p-4">
				<LoadingDisplay />
			</div>
		)
	}

	// Handle error state
	if (config.props?.error) {
		return (
			<div className="flex flex-col gap-4 p-4">
				<ErrorDisplay message={config.props.error} />
			</div>
		)
	}

	// Get the component for the current step
	const StepComponent = STEP_COMPONENTS[config.stepId]
	return <StepComponent config={config} />
}

export default memo(JavaModernizationChat)
