import { createLogger } from "@/ibm/utils/logger"
import { deserializeStructuredError } from "@roo/apiError"

/**
 * Utility for detecting different types of errors in API responses
 */
export enum ErrorType {
	BUDGET_EXCEEDED = "BUDGET_EXCEEDED",
	SERVICE_DISRUPTION = "SERVICE_DISRUPTION",
	CONTEXT_WINDOW_EXCEEDED = "CONTEXT_WINDOW_EXCEEDED",
	TOO_MANY_IMAGES_DOCUMENTS = "TOO_MANY_IMAGES_DOCUMENTS",
	AUTHENTICATION = "AUTHENTICATION",
	RATE_LIMIT = "RATE_LIMIT",
	INVALID_REQUEST = "INVALID_REQUEST",
	UNKNOWN = "UNKNOWN",
}

export interface ErrorDetails {
	type: ErrorType
	data?: Record<string, any>
	messageKey?: string
}

const ERROR_PATTERNS = {
	// Pattern matches: "Budget has been exceeded! Current cost: 30.02637990000002, Max budget: 30.0"
	[ErrorType.BUDGET_EXCEEDED]: /Budget has been exceeded!\s*Current cost:\s*[\d.]+,\s*Max budget:\s*[\d.]+/i,

	// Pattern matches: litellm.ContextWindowExceededError with specific messages
	// - "input length and `max_tokens` exceed context limit"
	[ErrorType.CONTEXT_WINDOW_EXCEEDED]:
		/litellm\.ContextWindowExceededError|Input is too long for requested model|input length and [`']max_tokens[`'] exceed context limit/i,
	// Pattern matches: litellm.RateLimitError with rate_limit_reached_requests code
	// - RateLimitError with specific "rate_limit_reached_requests" code
	// - RouterRateLimitError
	[ErrorType.RATE_LIMIT]: /litellm\.RateLimitError|rate_limit_reached_requests/i,
	// Pattern matches: Image/document size errors and content policy violations
	// - BadRequestError with image size, text bytes, or content policy issues
	[ErrorType.TOO_MANY_IMAGES_DOCUMENTS]:
		/image exceeds \d+ MB maximum|too many total text bytes:\s*\d+\s*>\s*\d+|ContentPolicyViolationError|concurrency_limit:\s*Extra inputs are not permitted/i,
	// Pattern matches: litellm.AuthenticationError with authentication_token_expired
	// - AuthenticationError with "authentication_token_expired" code
	// - watsonxException with 401 status and expired token message

	[ErrorType.AUTHENTICATION]:
		/litellm\.AuthenticationError|authentication_token_expired|401.*(?:Unauthorized|Authentication)|status_code['"]\s*:\s*401|Invalid proxy server token|Malformed API Key|No api key passed in|api_key client option must be set/i,
	// Pattern matches: Invalid requests - model not found, invalid keys, unsupported params, validation errors
	// - AssertionError for invalid virtual keys
	// - BadRequestError with validation errors
	// - ProxyModelNotFoundError for invalid model names
	// - UnsupportedParamsError for invalid parameters
	[ErrorType.INVALID_REQUEST]:
		/LiteLLM Virtual Key expected.*expected to start with ['"]sk-['"]|Invalid model name|litellm\.UnsupportedParamsError|unsupported_deployment_api_error|validation error detected/i,
}

/**
 * Extracts error-specific data from the base error message
 */
function extractErrorData(errorMessage: string, errorType: ErrorType): Record<string, any> | undefined {
	if (errorType === ErrorType.BUDGET_EXCEEDED) {
		// For budget exceeded errors, extract the current cost and max budget values
		// from messages like: "Budget has been exceeded! Current cost: 30.02637990000002, Max budget: 30.0"
		const budgetMatch = /Current cost:\s*([\d.]+),\s*Max budget:\s*([\d.]+)/i.exec(errorMessage)
		if (budgetMatch) {
			return {
				currentCost: parseFloat(budgetMatch[1]),
				maxBudget: parseFloat(budgetMatch[2]),
			}
		}
	}
	return undefined
}

/**
 * Extracts retry information from service disruption errors
 */
function extractRetryData(errorMessage: string): Record<string, any> | undefined {
	// Extracts the retry attempt number (e.g., "Retry attempt 3" -> 3)
	const retryAttemptRegex = /Retry attempt (\d+)/i

	// Extracts the countdown seconds before retry (e.g., "Retrying in 5 seconds" -> 5)
	const retryCountdownRegex = /Retrying in (\d+) seconds/i

	// Detects if we're retrying immediately with no countdown (e.g., "Retrying now")
	const retryNowRegex = /Retrying now/i

	const retryAttemptMatch = errorMessage.match(retryAttemptRegex)
	const retryCountdownMatch = errorMessage.match(retryCountdownRegex)
	const isRetryingNow = retryNowRegex.test(errorMessage)

	const data: Record<string, any> = {}

	if (retryAttemptMatch) {
		data.retryAttempt = parseInt(retryAttemptMatch[1], 10)
	}

	if (retryCountdownMatch) {
		data.retryCountdown = parseInt(retryCountdownMatch[1], 10)
	} else if (isRetryingNow && retryAttemptMatch) {
		data.retryCountdown = 0
	}

	return Object.keys(data).length > 0 ? data : undefined
}

// Service disruption error patterns with their message keys
// Based on actual production errors from litellm_requests_failures_counts.csv
const SERVICE_DISRUPTION_PATTERNS = [
	// Matches: MidStreamFallbackError with RuntimeError: Connection closed during streaming
	// - MidStreamFallbackError with "RuntimeError: Connection closed"
	{
		pattern: /litellm\.MidStreamFallbackError.*(?:RuntimeError.*)?Connection closed/i,
		messageKey: "streaming",
	},

	// Matches: APIConnectionError with specific connection issues
	// - APIConnectionError with "Connection error", "Timeout on reading data", "Server disconnected"
	{
		pattern:
			/litellm\.APIConnectionError.*(?:Connection error|Timeout on reading data from socket|Server disconnected)/i,
		messageKey: "connection",
	},

	// Matches: APIError with specific network errors (502, connection refused, EOF, closed connection)
	// - APIError with "502 Bad Gateway", "connection refused", "EOF", "connection reset"
	{
		pattern:
			/litellm\.APIError.*(?:502 Bad Gateway|dial tcp.*connect: connection refused|EOF|connection reset by peer|use of closed network connection)/i,
		messageKey: "network",
	},

	// Matches: ServiceUnavailableError from Bedrock with specific messages
	// - ServiceUnavailableError with Bedrock-specific errors
	{
		pattern:
			/litellm\.ServiceUnavailableError.*(?:Too many connections|Bedrock is unable to process|Model is getting throttled|system encountered an unexpected error|no healthy upstream|MidStreamFallbackError)/i,
		messageKey: "serviceUnavailable",
	},

	// Matches: InternalServerError with specific error messages
	// - InternalServerError with "'Encoding' object", "EngineCore", "downstream_request_failed"
	// - generic "500 Internal Server Error" (this might be too broad)
	{
		pattern:
			/litellm\.InternalServerError|Error code: 500|['"]Encoding['"] object has no attribute ['"]items['"]|EngineCore encountered an issue|downstream_request_failed| Error building chunks for logging/i,
		messageKey: "internalServer",
	},

	// Matches: Timeout errors with specific timeout messages
	// - Timeout with "Request timed out", "504 Gateway Time-out", "408 Request Time-out"
	{
		pattern:
			/litellm\.Timeout.*(?:Request timed out|Connection timed out)|504 Gateway Time-out|408 Request Time-out/i,
		messageKey: "timeout",
	},

	// Matches: RouterRateLimitError when no deployments available with cooldown message
	// - RouterRateLimitError with "No deployments available"
	{
		pattern: /(?:RouterRateLimitError.*)?No deployments available.*Try again in \d+ seconds/i,
		messageKey: "routerCooldown",
	},
	{
		pattern: /litellm\.ServiceUnavailableError.*BedrockException.*(?:Try your request again|unable to process|{})/i,
		messageKey: "serviceUnavailable",
	},
]

const logger = createLogger("ErrorTypeDetection")

/**
 * Detects the type of error from an error message
 * @param errorMessage The error message to analyze
 * @returns ErrorDetails object with the detected error type and any extracted data
 */
export function detectErrorType(errorMessage: string): ErrorDetails {
	if (!errorMessage) {
		return { type: ErrorType.UNKNOWN }
	}

	// ibm_change_start: Try to parse structured error first
	const structuredError = deserializeStructuredError(errorMessage)
	if (structuredError) {
		logger.debug("Parsed structured error:", structuredError)

		// Use status code for faster detection
		if (structuredError.statusCode) {
			if (structuredError.statusCode === 401) {
				return { type: ErrorType.AUTHENTICATION, data: structuredError }
			}
			if (structuredError.statusCode === 429) {
				return { type: ErrorType.RATE_LIMIT, data: structuredError }
			}
			if (structuredError.statusCode === 413) {
				return { type: ErrorType.CONTEXT_WINDOW_EXCEEDED, data: structuredError }
			}
			if (structuredError.statusCode === 402) {
				return { type: ErrorType.BUDGET_EXCEEDED, data: structuredError }
			}
		}

		// Use error type/code for detection
		if (structuredError.errorType) {
			const errorTypeLower = structuredError.errorType.toLowerCase()
			if (errorTypeLower.includes("authentication") || errorTypeLower.includes("auth")) {
				return { type: ErrorType.AUTHENTICATION, data: structuredError }
			}
			if (errorTypeLower.includes("ratelimit") || errorTypeLower.includes("rate_limit")) {
				return { type: ErrorType.RATE_LIMIT, data: structuredError }
			}
			if (errorTypeLower.includes("contextwindow") || errorTypeLower.includes("context_window")) {
				return { type: ErrorType.CONTEXT_WINDOW_EXCEEDED, data: structuredError }
			}
			if (errorTypeLower.includes("model_request_error")) {
				return { type: ErrorType.SERVICE_DISRUPTION, data: structuredError }
			}
		}

		// Fall through to pattern matching on the message content
		errorMessage = structuredError.message
	}
	// ibm_change_end

	// Defines the priority order for checking error patterns
	// This ensures that more specific/important errors take precedence when multiple patterns match
	const ERROR_PRIORITY_ORDER: (keyof typeof ERROR_PATTERNS)[] = [
		ErrorType.BUDGET_EXCEEDED,
		ErrorType.AUTHENTICATION,
		ErrorType.RATE_LIMIT,
		ErrorType.CONTEXT_WINDOW_EXCEEDED,
		ErrorType.TOO_MANY_IMAGES_DOCUMENTS,
		ErrorType.INVALID_REQUEST,
	]

	for (const errorType of ERROR_PRIORITY_ORDER) {
		const pattern = ERROR_PATTERNS[errorType]
		if (pattern.test(errorMessage)) {
			logger.debug(`Matched ${errorType} pattern: ${pattern.source}`)
			logger.debug(
				`From error message: "${errorMessage.substring(0, 100)}${errorMessage.length > 100 ? "..." : ""}"`,
			)
			return {
				type: errorType as ErrorType,
				data: extractErrorData(errorMessage, errorType as ErrorType),
			}
		}
	}

	// Check service disruption patterns
	for (const { pattern, messageKey } of SERVICE_DISRUPTION_PATTERNS) {
		if (pattern.test(errorMessage)) {
			logger.debug(`Matched service disruption pattern (${messageKey}): ${pattern.source}`)
			logger.debug(
				`From error message: "${errorMessage.substring(0, 100)}${errorMessage.length > 100 ? "..." : ""}"`,
			)
			return {
				type: ErrorType.SERVICE_DISRUPTION,
				data: extractRetryData(errorMessage),
				messageKey,
			}
		}
	}

	// Check each specific error pattern
	// TODO: is this still needed?
	for (const [errorType, pattern] of Object.entries(ERROR_PATTERNS)) {
		if (pattern.test(errorMessage)) {
			logger.debug(`Matched pattern for ${errorType}: ${pattern.source}`)
			return {
				type: errorType as ErrorType,
				data: extractErrorData(errorMessage, errorType as ErrorType),
			}
		}
	}
	return {
		type: ErrorType.UNKNOWN,
	}
}
