import { callCommand } from "@/ibm/utils/callCommand"

export const EJ_REVEAL_COMMAND = "ejRulesWebview.reveal"
export const EJ_ANALYZE_JAVA_COMMAND = "wca4j.analyzeJava"
export const EJ_RUN_AUTOMATED_FIXES_COMMAND = "wca4j.runAutomatedFixes"
export const EJ_GET_PROMPTS_COMMAND = "ejRulesWebview.getLLMPrompts"
export const EJ_SET_AUTOMATION_FLAG_COMMAND = "ejRulesWebview.setAutomationModeFlag"
export const GIT_CHECK_COMMIT_CHANGES_COMMAND = "git.hasUncommittedChanges"
export const GIT_CHECKOUT_COMMAND = "git.checkoutBranch"
export const GIT_ADD_COMMAND = "git.add"
export const GIT_ADD_RECENT_MODIFIED_COMMAND = "git.addRecentlyModifiedFiles"
export const GIT_COMMIT_COMMAND = "git.commitFiles"

export interface VSCodeRange {
	/**
	 * The start position. It is before or equal to [end](#Range.end).
	 */
	start: VSCodePosition

	/**
	 * The end position. It is after or equal to [start](#Range.start).
	 */
	end: VSCodePosition
}

export interface VSCodePosition {
	line: number
	character: number
}

/**
 * Interface representing a prompt template with its associated information
 */
export interface EJPromptTemplateInfo {
	sourceFilePath: string
	lineNumber: number
	promptText: string
	processedPromptText: string
	targetName: string | undefined
	targetType: "function" | "class" | undefined
	codeBlockRange: VSCodeRange | null
	ruleName: string
	ruleId: string
	resultIndex: number
	detailIndex: number
}

export async function checkoutBranch(): Promise<boolean> {
	const hasUncommittedChanges = await callCommand(GIT_CHECK_COMMIT_CHANGES_COMMAND)
	if (hasUncommittedChanges) {
		return false
	}

	await callCommand(GIT_CHECKOUT_COMMAND)

	//Introduce artificial delay to ensure file updates are picked up
	await new Promise((resolve) => setTimeout(resolve, 100))
	return true
}
