import React, { Dispatch, SetStateAction } from "react"
import { useTranslation } from "react-i18next"
import { Edit, Trash2 } from "lucide-react"
import { cn } from "@/lib/utils"
import { Mode } from "@roo/modes"
import { ClineMessage, ModelInfo } from "@roo-code/types"

import { Mention } from "@/components/chat/Mention"
import Thumbnails from "@/components/common/Thumbnails"
import { ChatTextArea } from "@/components/chat/ChatTextArea"
import { vscode } from "@src/utils/vscode"
import { StandardTooltip } from "@/components/ui"

/**
 * Props for UserFeedbackMessage component
 */
export interface UserFeedbackMessageProps {
	message: ClineMessage
	isStreaming?: boolean
	// ibm_change_start: Add edit functionality props
	isEditing?: boolean
	editedContent?: string
	editMode?: Mode
	editImages?: string[]
	model?: ModelInfo
	onEditClick?: () => void
	onCancelEdit?: () => void
	onSaveEdit?: () => void
	onSelectImages?: () => void
	setEditedContent?: Dispatch<SetStateAction<string>>
	setEditImages?: Dispatch<SetStateAction<string[]>>
	setEditMode?: Dispatch<SetStateAction<Mode>>
	// ibm_change_end: Add edit functionality props
}

export const feedbackBackgroundColor = "#4589FF33"

/**
 * Component for displaying user feedback messages with edit functionality
 */
export const UserFeedbackMessage: React.FC<UserFeedbackMessageProps> = ({
	message,
	isStreaming,
	// ibm_change: Destructure edit props
	isEditing,
	editedContent,
	editMode,
	editImages,
	model,
	onEditClick,
	onCancelEdit,
	onSaveEdit,
	onSelectImages,
	setEditedContent,
	setEditImages,
	setEditMode,
}) => {
	const { t } = useTranslation()

	return (
		<div className="group">
			{/* ibm_change_start: Add edit mode UI while keeping original styling */}
			<div
				className={cn(
					"border rounded overflow-hidden whitespace-pre-wrap",
					isEditing ? "bg-vscode-editor-background text-vscode-editor-foreground p-1" : "p-1",
				)}
				style={isEditing ? undefined : { backgroundColor: feedbackBackgroundColor }}>
				{isEditing ? (
					<div className="flex flex-col gap-2">
						<ChatTextArea
							inputValue={editedContent || ""}
							setInputValue={setEditedContent || (() => {})}
							sendingDisabled={false}
							selectApiConfigDisabled={true}
							placeholderText={t("chat:editMessage.placeholder")}
							selectedImages={editImages || []}
							setSelectedImages={setEditImages || (() => {})}
							onSend={onSaveEdit || (() => {})}
							onSelectImages={onSelectImages || (() => {})}
							shouldDisableImages={!model?.supportsImages}
							mode={editMode || "code"}
							setMode={setEditMode || (() => {})}
							modeShortcutText=""
							isEditMode={true}
							onCancel={onCancelEdit || (() => {})}
						/>
					</div>
				) : (
					<>
						<div className="flex justify-between">
							<div
								className="flex-grow px-2 py-1 wrap-anywhere"
								onClick={(e) => {
									e.stopPropagation()
									if (!isStreaming && onEditClick) {
										onEditClick()
									}
								}}
								title={t("chat:queuedMessages.clickToEdit")}>
								<span className="codicon codicon-feedback mr-1.5" />
								<Mention text={message.text} withShadow />
							</div>
							<div className="flex gap-2 pr-1">
								<StandardTooltip content={t("chat:messageActions.edit")} side="top">
									<div
										className="cursor-pointer shrink-0 opacity-0 group-hover:opacity-100 transition-opacity"
										style={{ visibility: isStreaming ? "hidden" : "visible" }}
										onClick={(e) => {
											e.stopPropagation()
											if (onEditClick) {
												onEditClick()
											}
										}}>
										<Edit className="w-4 shrink-0" aria-label="Edit message icon" />
									</div>
								</StandardTooltip>
								<StandardTooltip content={t("chat:messageActions.delete")} side="top">
									<div
										className="cursor-pointer shrink-0 opacity-0 group-hover:opacity-100 transition-opacity"
										style={{ visibility: isStreaming ? "hidden" : "visible" }}
										onClick={(e) => {
											e.stopPropagation()
											vscode.postMessage({ type: "deleteMessage", value: message.ts })
										}}>
										<Trash2 className="w-4 shrink-0" aria-label="Delete message icon" />
									</div>
								</StandardTooltip>
							</div>
						</div>
						{message.images && message.images.length > 0 && (
							<Thumbnails images={message.images} style={{ marginTop: "8px" }} />
						)}
					</>
				)}
			</div>
			{/* ibm_change_end: Add edit mode UI while keeping original styling */}
		</div>
	)
}

export default UserFeedbackMessage

