import { useAppTranslation } from "@/i18n/TranslationContext"
import { vscode } from "@/utils/vscode"
import { StepLike, StepLikeStatus, SubStepId } from "@roo-code/types"
import { WebviewMessage } from "@roo/WebviewMessage"
import * as React from "react"
import { memo } from "react"

import StepButton from "../../../common/StepButton"
import StepContainer from "../../../common/StepContainer"
import { StepProgressNotifications, StepProgressTodoList } from "../../../common/StepProgressComponents"

const STEP_CONFIGS = {
	default: {
		steps: [],
		command: "bob-code.executeLibertyReplatforming",
		eventPrefix: "liberty-replatforming-",
	},
}

const ReplatformLibertyStep: React.FC<{ config: any }> = ({ config }) => {
	const { t } = useAppTranslation()
	const [stepCompleted, setStepCompleted] = React.useState<boolean>(
		config.props?.["replatformLiberty.isCompleted"] || false,
	)

	const [subSteps, setSubSteps] = React.useState<StepLike[]>(config.props?.libertyReplatformingSubSteps || [])
	const [isReplatforming, setIsReplatforming] = React.useState<boolean>(false)
	const projectPath = config.props?.projectPath
	const summary = config.props?.libertySummary
	const sourceAppServer = config.props?.sourceAppServer
	const targetAppServer = config.props?.targetAppServer
	const colorThemeKind = config.props?.["colorTheme.kind"]

	const handleProceed = () => {
		setSubSteps([])
		setIsReplatforming(true)
		const message: WebviewMessage = {
			type: "executeCommand",
			commands: [STEP_CONFIGS.default.command],
			commandArgs: [projectPath, summary, sourceAppServer, targetAppServer, colorThemeKind],
			eventId: `${STEP_CONFIGS.default.eventPrefix}${Date.now()}`,
		}
		vscode.postMessage(message)
	}

	const handleReplatformingResult = (message: any) => {
		if (message.commandResult.subSteps) {
			try {
				const steps: StepLike[] = message.commandResult.subSteps
				const isCompleted: boolean = isReplatformingStepCompleted(subSteps)
				setSubSteps(steps)
				setIsReplatforming(didEndOnAnalysisStep(steps) ? false : !isCompleted)
				setStepCompleted(isCompleted)
			} catch (_) {
				// Error parsing replatforming results - reset to failed state
				setStepCompleted(false)
			}
		}
	}

	const didEndOnAnalysisStep = (replatformingSubSteps: StepLike[]): boolean => {
		if (replatformingSubSteps.length !== 1) {
			return false
		}

		const analysisStep = replatformingSubSteps[0]
		return analysisStep.id === SubStepId.LIBERTY_MOD_ANALYZE_RECIPES && analysisStep.result?.data?.finish === true
	}

	const isReplatformingStepCompleted = (replatformingSubSteps: StepLike[]): boolean => {
		const lastSubStep = replatformingSubSteps.find((step) => step.id === SubStepId.MERMAID)
		return lastSubStep
			? lastSubStep.status === StepLikeStatus.SUCCESS || lastSubStep.status === StepLikeStatus.SKIPPED
			: false
	}

	React.useEffect(() => {
		const handleMessage = (event: MessageEvent) => {
			const message = event.data

			if (
				message.type === "commandResult" &&
				message.requestId &&
				message.requestId.startsWith(STEP_CONFIGS.default.eventPrefix)
			) {
				handleReplatformingResult(message)
			}
		}

		window.addEventListener("message", handleMessage)
		return () => {
			window.removeEventListener("message", handleMessage)
		}
	})

	return (
		<>
			<h3>{t("ibm:javaModernization.agenticChanges.title")}</h3>
			<p>{t("ibm:javaModernization.agenticChanges.subTitle")}</p>
			<StepContainer>
				<StepButton disabled={isReplatforming || stepCompleted} onClick={handleProceed}>
					{t("ibm:javaModernization.proceed")}
				</StepButton>
				<StepProgressTodoList subSteps={subSteps} />
			</StepContainer>
			<StepProgressNotifications subSteps={subSteps} />
		</>
	)
}

export default memo(ReplatformLibertyStep)
