import { vscode } from "@/utils/vscode"
import { WebviewMessage } from "@roo/WebviewMessage"

// Should be a serializable object duplicate of core version
export interface ControlledChatResponseObject {
	flowId: string
	stepId: string
	message: string
	data: any
}

export const sendChatResponse = (responseObject: ControlledChatResponseObject) => {
	const message: WebviewMessage = {
		type: "askResponse",
		askResponse: "controlled_chat_flow_response",
		text: JSON.stringify(responseObject),
	}
	vscode.postMessage(message)
	console.log("==> sendChatResponse Message sent", message)
}
