import { TodoStatus } from "./types"

interface StatusIconProps {
	status: TodoStatus
}

// StatusIcon component for reusability
export const StatusIcon = ({ status }: StatusIconProps) => {
	const getBackgroundStyle = () => {
		switch (status) {
			case TodoStatus.COMPLETED:
			case TodoStatus.ALL_COMPLETED:
				return { background: "var(--vscode-charts-green)" }
			case TodoStatus.IN_PROGRESS:
				return { background: "var(--vscode-charts-yellow)" }
			case TodoStatus.ERROR:
				return { background: "var(--vscode-charts-red)" }
			case TodoStatus.SKIPPED:
				return { background: "var(--vscode-descriptionForeground)" }
			default:
				return {
					background: "transparent",
					border: "1px solid var(--vscode-descriptionForeground)",
				}
		}
	}

	return (
		<span
			className={`w-2 h-2 rounded-full mr-2 inline-block ${status === TodoStatus.IN_PROGRESS ? "animate-pulse" : ""}`}
			style={{
				...getBackgroundStyle(),
			}}
		/>
	)
}
