import * as React from "react"
import { Button } from "@/components/ui"
import "../../../java-upgrade-setup-chat.css"
import { ControlledChatResponseObject, sendChatResponse } from "../../../sendChatResponse"
import { memo } from "react"
import { checkoutBranch } from "../ejCommands"
import { callCommand } from "@/ibm/utils/callCommand"
import { Version } from "../JavaUpgradeChat"
import Select from "@/ibm/components/common/select/Select"
import ToggleButton from "@/ibm/components/common/toggleButton/ToggleButton"
import { Help } from "@carbon/icons-react" // ibm_change

// Keep the response prop for compatibility but ignore it
const AnalyzeApplicationStep: React.FC<{ config: any }> = ({ config }) => {
	const [initTriggered, setInitTriggered] = React.useState<boolean>(false)
	const [initCompleted, setInitCompleted] = React.useState<boolean>(false)
	const [sourceVersion, setSourceVersion] = React.useState<string>("")
	const [targetVersion, setTargetVersion] = React.useState<string>("")
	const [originalOptions, setOriginalOptions] = React.useState<Version[]>([])
	const [sourceOptions, setSourceOptions] = React.useState<Version[]>([])
	const [targetOptions, setTargetOptions] = React.useState<Version[]>([])
	// const [projectName, setProjectName] = React.useState<string>('SAMPLE-APP-MOD');
	const [fullyAutoMode, setFullyAutoMode] = React.useState<boolean>(config.props.fullyAutomatedMode)
	const [stepCompleted, setStepCompleted] = React.useState<boolean>(config.props.isCompleted)
	const [showTooltip, setShowTooltip] = React.useState<boolean>(false)

	const setUp = async () => {
		if (initTriggered) {
			return
		}
		setInitTriggered(true)

		const sourceVersions: any[] | undefined = await callCommand("wca4j.getSourceJavaVersion")
		sourceVersions?.sort((a, b) => a.displayText.localeCompare(b.displayText))

		const originals: Version[] = []
		const sources: Version[] = []
		let recommendVersion: Version = {
			label: "",
			id: "",
			value: 0,
		}

		sourceVersions?.forEach((v) => {
			const match = v.id.match(/\d+/)
			const versionNumber = parseInt(match[0])

			if (v.recommended === true) {
				recommendVersion = {
					label: v.displayText + " (recommend)",
					id: v.id,
					value: versionNumber,
				}
				sources.push(recommendVersion)
			} else {
				sources.push({
					label: v.displayText,
					id: v.id,
					value: versionNumber,
				})
			}
			originals.push({
				label: v.displayText,
				id: v.id,
				value: versionNumber,
			})
		})

		setOriginalOptions(originals)

		setSourceOptions(sources)

		if (recommendVersion.value !== 0) {
			setSourceVersion(recommendVersion.id)
			const targets = sources.filter((v) => {
				const result: boolean = v.value > recommendVersion.value
				return result
			})
			setTargetOptions(targets)
		} else {
			setTargetOptions(sources)
		}
		setInitCompleted(true)
	}

	React.useEffect(() => {
		setUp()
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [])

	React.useEffect(() => {
		if (!initTriggered) {
			return
		}
		const selectVersion = originalOptions.find((version) => version.id === sourceVersion)
		if (selectVersion) {
			const targets = originalOptions.filter((v) => {
				const result: boolean = v.value > selectVersion.value
				return result
			})
			setTargetOptions(targets)
			if (targets.length === 0) {
				setTargetVersion("")
			}
		}
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [sourceVersion])

	return (
		<>
			<h3>Analyze application</h3>
			<p>
				Please select the source and target Java version to start analyzing your project and prepare an upgrade
				plan
			</p>
			<div className="ibm--analyze-step__container ibm--java-chat__content">
				{/* TODO: Add back when needed */}
				{/* <div className="ibm--analyze-step__select-container">
                    <div className="ibm--analyze-step__select-label">Project</div>
                    <Select
                        disabled={true}
                        options={[{ label: projectName, id: projectName}]}
                        selectedValue={projectName}
                        onChange={() => {
                            setProjectName(projectName);
                        }}
                    />
                </div> */}

				<div className="ibm--analyze-step__versions-container">
					<div className="ibm--analyze-step__version-select">
						<div className="ibm--analyze-step__select-label">Source Java version</div>
						<Select
							options={sourceOptions}
							selectedValue={sourceVersion}
							disabled={!initCompleted || stepCompleted}
							onChange={(value: string) => {
								setSourceVersion(value)
							}}
						/>
					</div>
					<div className="ibm--analyze-step__version-select">
						<div className="ibm--analyze-step__select-label">Target Java version</div>
						<Select
							options={targetOptions}
							selectedValue={targetVersion}
							disabled={!initCompleted || stepCompleted}
							onChange={(value: string) => {
								setTargetVersion(value)
							}}
						/>
					</div>
				</div>

				<div className="ibm--analyze-step__toggle-container">
					<div className="ibm--analyze-step__toggle-label-container">
						<p className="ibm--analyze-step__toggle-label">Enable fully auto</p>
						<div className="ibm--analyze-step__tooltip-container">
							<Help
								className="ibm--analyze-step__tooltip-icon"
								onMouseEnter={() => setShowTooltip(true)}
								onMouseLeave={() => setShowTooltip(false)}
							/>
							{showTooltip && (
								<div className="ibm--analyze-step__tooltip">
									<p>
										This will allow agent to run tools without asking for confirmation such as
										executing commands and writing to files. This will create another branch and
										auto commit the changes
									</p>
								</div>
							)}
						</div>
					</div>

					<ToggleButton
						checked={fullyAutoMode}
						onChange={() => {
							setFullyAutoMode(!fullyAutoMode)
						}}
						disabled={!initCompleted || stepCompleted}
					/>
				</div>

				<Button
					className="ibm--java-chat__button"
					disabled={!initCompleted || !sourceVersion || !targetVersion || stepCompleted}
					onClick={async () => {
						const responseObject: ControlledChatResponseObject = {
							flowId: config.flowId,
							stepId: config.stepId,
							message: "I clicked in analyze application STEP",
							data: {
								sourceJavaVersion: sourceVersion,
								targetJavaVersion: targetVersion,
								fullyAutomatedMode: fullyAutoMode,
								isCompleted: true,
							},
						}
						if (fullyAutoMode) {
							const success = await checkoutBranch()
							if (success) {
								sendChatResponse({
									...responseObject,
									message: "I clicked in analyze application STEP with fully auto mode",
								})
								setStepCompleted(true)
							}
						} else {
							sendChatResponse({ ...responseObject, message: "I clicked in analyze application STEP" })
							setStepCompleted(true)
						}
					}}>
					Proceed
				</Button>
			</div>
		</>
	)
}

export default memo(AnalyzeApplicationStep)
