import { Input } from "@/components/ui"
import { useAppTranslation } from "@/i18n/TranslationContext"
import { vscode } from "@/utils/vscode"
import { CheckIcon, Cross2Icon, QuestionMarkIcon } from "@radix-ui/react-icons"
import { StepLike, StepLikeStatus, SubStepId } from "@roo-code/types"
import { WebviewMessage } from "@roo/WebviewMessage"
import { TFunction } from "i18next"
import * as React from "react"
import { FC, memo } from "react"
import { Trans } from "react-i18next"

import StepButton from "../../../common/StepButton"
import StepContainer from "../../../common/StepContainer"
import { StepProgressNotifications, StepProgressTodoList } from "../../../common/StepProgressComponents"
import { isStepInProgress } from "../../../common/utils"
import { ControlledChatResponseObject, sendChatResponse } from "../../../sendChatResponse"
import JavaModReadme from "../javaModReadme"

// Constants for step configurations
const STEP_CONFIGS = {
	default: {
		steps: [SubStepId.ANALYSIS_CHECK_PREREQUISITES, SubStepId.ANALYSIS_METADATA, SubStepId.ANALYSIS_BUILD_APP],
		command: "bob-code.executeSequentialAppAnalysis",
		eventPrefix: "sequential-app-analysis-",
	},
}

const isAnalysisStepSuccessful = (analysisSubSteps: StepLike[]): boolean => {
	if (isStepInProgress(analysisSubSteps)) {
		return false
	}
	const buildStep = analysisSubSteps.find((step) => step.id === SubStepId.ANALYSIS_BUILD_APP)
	return buildStep ? buildStep.status === StepLikeStatus.SUCCESS : false
}

enum CheckStatus {
	UNCHECKED = "unchecked",
	CHECKED_FALSE = "false",
	CHECKED_TRUE = "true",
}

interface PrerequisiteElementProps {
	prerequisite: string
	status: CheckStatus
}

// SinglePrerequisiteSolutionWithLink is a text that can contain a solution.
// So far, it only uses link.
const SinglePrerequisiteSolutionWithLink: FC<{ translation: TFunction; i18nKey: string }> = ({
	translation,
	i18nKey,
}) => (
	<Trans
		t={translation}
		i18nKey={i18nKey}
		components={[<a style={{ color: "var(--vscode-textLink-foreground)" }} key={0} />]}
	/>
)

const PrerequisiteSolution: Record<string, FC<{ translation: TFunction }>> = {
	sdkmanInstalled: ({ translation }) => (
		<SinglePrerequisiteSolutionWithLink
			translation={translation}
			i18nKey={`ibm:javaModernization.analyzeProject.prerequisites.checksSolution.sdkmanInstalled`}
		/>
	),
	wingetInstalled: ({ translation }) => (
		<SinglePrerequisiteSolutionWithLink
			translation={translation}
			i18nKey={`ibm:javaModernization.analyzeProject.prerequisites.checksSolution.wingetInstalled`}
		/>
	),
	isJavaWorkspace: ({ translation }) => (
		<>{translation(`ibm:javaModernization.analyzeProject.prerequisites.checksSolution.isJavaWorkspace`)}</>
	),
}

// PrerequisiteElement:
// [ icon ] [text]
//          [solution]
const PrerequisiteElement: React.FC<PrerequisiteElementProps> = ({ prerequisite, status }) => {
	const { t } = useAppTranslation()

	const iconMap = {
		[CheckStatus.UNCHECKED]: <QuestionMarkIcon color="#888888" />,
		[CheckStatus.CHECKED_TRUE]: <CheckIcon color="var(--vscode-charts-green)" />,
		[CheckStatus.CHECKED_FALSE]: <Cross2Icon color="var(--vscode-charts-red)" />,
	}

	const text = t(`ibm:javaModernization.analyzeProject.prerequisites.checks.${prerequisite}`)

	return (
		<div className="ibm-progress-notification-container flex items-start gap-2">
			<div className="flex-shrink-0 self-start">{iconMap[status]}</div>
			<div className="flex flex-col">
				<span className="mb-1">{text}</span>
				{status === CheckStatus.CHECKED_FALSE && (
					<div className="text-xs text-vscode-descriptionForeground">
						{PrerequisiteSolution[prerequisite]({ translation: t as TFunction })}
					</div>
				)}
			</div>
		</div>
	)
}

const AnalyzeJavaProjectStep: React.FC<{ config: any }> = ({ config }) => {
	const { t } = useAppTranslation()
	const [projectPath, setProjectPath] = React.useState<string>(config.props?.projectPath || "")
	const [subSteps, setSubSteps] = React.useState<StepLike[]>(config.props?.subSteps || [])
	const [isAnalyzing, setIsAnalyzing] = React.useState<boolean>(false)
	const [stepCompleted, setStepCompleted] = React.useState<boolean>(
		config.props?.["analyzeJavaProject.isCompleted"] || false,
	)
	const [stepSuccessful, setStepSuccessful] = React.useState<boolean>(false)

	// Compute button states
	const canAnalyze = projectPath && !isAnalyzing && !stepSuccessful && !stepCompleted
	const canProceed = !isAnalyzing && stepSuccessful

	// Handle sequential analysis results (WAR/EAR)
	const handleSequentialAnalysisResult = (message: any) => {
		if (message.commandResult.subSteps) {
			try {
				const steps: StepLike[] = message.commandResult.subSteps
				setSubSteps(steps)
				setIsAnalyzing(isStepInProgress(steps))
				setStepSuccessful(isAnalysisStepSuccessful(steps))
			} catch (e) {
				console.error("Failed to parse analysis results:", e)
				setIsAnalyzing(false)
			}
		}
	}

	// Message handler effect
	React.useEffect(() => {
		const handleMessage = (event: MessageEvent) => {
			const message = event.data

			if (
				message.type === "commandResult" &&
				message.requestId &&
				message.requestId.startsWith(STEP_CONFIGS.default.eventPrefix)
			) {
				handleSequentialAnalysisResult(message)
			}
		}

		window.addEventListener("message", handleMessage)
		return () => {
			window.removeEventListener("message", handleMessage)
		}
	}, [])

	const handleAnalyze = () => {
		if (!projectPath) return

		setIsAnalyzing(true)
		setSubSteps([])

		const message: WebviewMessage = {
			type: "executeCommand",
			commands: [STEP_CONFIGS.default.command],
			commandArgs: [projectPath, STEP_CONFIGS.default.steps],
			eventId: `${STEP_CONFIGS.default.eventPrefix}${Date.now()}`,
		}
		vscode.postMessage(message)
	}

	React.useEffect(() => {
		if (canProceed) {
			const responseObject: ControlledChatResponseObject = {
				flowId: config.flowId,
				stepId: config.stepId,
				message: `Analyzed Java project at: ${projectPath}`,
				data: {
					projectPath,
					subSteps: subSteps,
					isCompleted: true,
				},
			}
			sendChatResponse(responseObject)
			setStepCompleted(true)
		}
	}, [subSteps, canProceed, config.flowId, config.stepId, projectPath])

	// Take prerequisites data from subSteps, and create list of JSX elements
	let prerequisiteElements: JSX.Element[] = []
	const prerequisitesData = subSteps.find((a) => a.id === SubStepId.ANALYSIS_CHECK_PREREQUISITES)?.result?.data

	if (prerequisitesData) {
		prerequisiteElements = Object.entries(prerequisitesData).map(([key, value]) => {
			const status =
				value === true
					? CheckStatus.CHECKED_TRUE
					: value === false
						? CheckStatus.CHECKED_FALSE
						: CheckStatus.UNCHECKED

			return <PrerequisiteElement key={key} prerequisite={key} status={status} />
		})
	}

	return (
		<>
			<JavaModReadme />
			<h3>{t("ibm:javaModernization.analyzeProject.title")}</h3>
			<p>{t("ibm:javaModernization.analyzeProject.subTitle")}</p>
			<StepContainer>
				<div className="mb-2">
					<div className="font-bold mb-1">{t("ibm:javaModernization.analyzeProject.projectPath")}</div>
					<Input
						placeholder={t("ibm:javaModernization.analyzeProject.projectPathPlaceholder")}
						value={projectPath}
						onChange={(e) => setProjectPath(e.target.value)}
						disabled={isAnalyzing || stepCompleted}
					/>
				</div>
				<StepButton
					disabled={!canAnalyze || isAnalyzing || (stepCompleted && stepSuccessful)}
					onClick={handleAnalyze}
					subSteps={subSteps}>
					{isAnalyzing
						? t("ibm:javaModernization.analyzeProject.analyzeButtonProcessing")
						: t("ibm:javaModernization.analyzeProject.analyzeButton")}
				</StepButton>
				<StepProgressTodoList subSteps={subSteps} />
			</StepContainer>
			{prerequisiteElements.length > 0 && (
				<StepContainer>
					<span className="font-bold mb-1">
						{t("ibm:javaModernization.analyzeProject.prerequisitesTitle")}
					</span>
					{prerequisiteElements}
				</StepContainer>
			)}
			<StepProgressNotifications subSteps={subSteps} />
		</>
	)
}

export default memo(AnalyzeJavaProjectStep)
