/**
 * Structured API error information that can be passed from backend to webview
 * for better error detection and handling
 */
export interface StructuredApiError {
	/** The original error message */
	message: string
	/** HTTP status code if available */
	statusCode?: number
	/** Request ID for tracking/debugging */
	requestId?: string
	/** Error code from the API provider */
	errorCode?: string
	/** Error type from the API provider (e.g., "AuthenticationError", "RateLimitError") */
	errorType?: string
	/** Instana trace ID for distributed tracing (from x-instana-t header) */
	traceId?: string
	/** Additional metadata from the error */
	metadata?: Record<string, any>
}

/**
 * Serializes a structured error to a JSON string for transmission
 */
export function serializeStructuredError(error: StructuredApiError): string {
	return JSON.stringify(error)
}

/**
 * Deserializes a JSON string back to a structured error
 * Returns null if the string is not a valid structured error
 */
export function deserializeStructuredError(errorString: string): StructuredApiError | null {
	try {
		const parsed = JSON.parse(errorString)
		// Check if it has the required 'message' field
		if (parsed && typeof parsed.message === "string") {
			return parsed as StructuredApiError
		}
	} catch {
		// Not a JSON string or invalid JSON
	}
	return null
}

/**
 * Helper function to extract header value from either Headers object (fetch API) or plain object
 * @param headers - Either a Headers object with .get() method or a plain object
 * @param headerName - The header name to extract
 * @returns The header value or undefined
 */
function getHeaderValue(headers: any, headerName: string): string | undefined {
	if (!headers) {
		return undefined
	}
	// Check if it's a Headers object (has .get method) - native fetch API
	if (typeof headers.get === "function") {
		return headers.get(headerName) || undefined
	}
	// Otherwise treat as plain object - axios, custom errors, etc.
	return headers[headerName]
}

/**
 * Extracts structured error information from various error types
 */
export function extractStructuredError(error: any): StructuredApiError {
	const structured: StructuredApiError = {
		message: error?.message || String(error),
	}

	// Extract status code from various error formats
	if (error?.status) {
		structured.statusCode = error.status
	} else if (error?.statusCode) {
		structured.statusCode = error.statusCode
	} else if (error?.response?.status) {
		structured.statusCode = error.response.status
	} else if (error?.error?.status_code) {
		structured.statusCode = error.error.status_code
	}

	// Extract request ID - supports both fetch Headers objects and plain objects
	if (error?.requestId) {
		structured.requestId = error.requestId
	} else if (error?.requestID) {
		structured.requestId = error.requestID
	} else if (error?.request_id) {
		structured.requestId = error.request_id
	} else {
		structured.requestId = getHeaderValue(error?.headers, "x-request-id") ||
			getHeaderValue(error?.response?.headers, "x-request-id")
	}

	// Extract Instana trace ID from x-instana-t header - supports both fetch Headers objects and plain objects
	if (error?.traceId) {
		structured.traceId = error.traceId
	} else {
		structured.traceId = getHeaderValue(error?.headers, "x-instana-t") ||
			getHeaderValue(error?.response?.headers, "x-instana-t")
	}

	// Extract error code
	if (error?.code) {
		structured.errorCode = error.code
	} else if (error?.error?.code) {
		structured.errorCode = error.error.code
	}

	// Extract error type (e.g., from litellm errors)
	if (error?.type) {
		structured.errorType = error.type
	} else if (error?.error?.type) {
		structured.errorType = error.error.type
	} else if (error?.constructor?.name && error.constructor.name !== "Error") {
		structured.errorType = error.constructor.name
	}

	// Extract additional metadata
	if (error?.error?.metadata) {
		structured.metadata = error.error.metadata
	} else if (error?.metadata) {
		structured.metadata = error.metadata
	}

	// Try to extract error info from error message if it contains JSON
	if (structured.message) {
		const jsonMatch = structured.message.match(/\{[\s\S]*\}/)
		if (jsonMatch) {
			try {
				const errorJson = JSON.parse(jsonMatch[0])
				if (errorJson.status_code && !structured.statusCode) {
					structured.statusCode = errorJson.status_code
				}
				if (errorJson.error?.code && !structured.errorCode) {
					structured.errorCode = errorJson.error.code
				}
				if (errorJson.error?.type && !structured.errorType) {
					structured.errorType = errorJson.error.type
				}
			} catch {
				// Ignore JSON parse errors
			}
		}
	}

	return structured
}

/**
 * Formats a structured error into a short, user-friendly message
 * containing just the status code, request ID, and trace ID for support/debugging
 *
 * @param error The structured error to format
 * @returns A concise error message like "Status 401 (Request ID: req-123, Trace ID: trace-456)" or empty string if no status code
 *
 * @example
 * const error = { message: "Auth failed", statusCode: 401, requestId: "req-123", traceId: "trace-456" }
 * formatShortErrorMessage(error) // "Status 401 (Request ID: req-123, Trace ID: trace-456)"
 *
 * @example
 * const error = { message: "Unknown error" }
 * formatShortErrorMessage(error) // ""
 */
export function formatShortErrorMessage(error: StructuredApiError): string {
	const parts: string[] = []

	// Add status code
	if (error.statusCode) {
		parts.push(`Status: ${error.statusCode}`)
	}

	if (error.errorCode) {
		parts.push(`Error Code: ${error.errorCode}`)
	}

	// Add request ID and trace ID if available
	const ids: string[] = []
	if (error.requestId) {
		ids.push(`Request ID: ${error.requestId}`)
	}
	if (error.traceId) {
		ids.push(`Trace ID: ${error.traceId}`)
	}
	if (ids.length > 0) {
		parts.push(`(${ids.join(", ")})`)
	}

	return parts.join(" ")
}

