import { cn } from "@/lib/utils"
import React, { useImperativeHandle, useRef, useState, forwardRef } from "react"
import "./aiEffect.css"

export interface AiEffectRef {
	triggerEffect: () => void
}

interface AiEffectProps {
	children: React.ReactNode
	onEffectEnd?: () => void
}

export const AiEffect = forwardRef<AiEffectRef, AiEffectProps>(({ children, onEffectEnd }, ref) => {
	const [isActivated, setIsActivated] = useState(false)
	const timeoutRef = useRef<NodeJS.Timeout>()

	useImperativeHandle(
		ref,
		() => ({
			triggerEffect: () => {
				// Clear any existing timeout
				if (timeoutRef.current) {
					clearTimeout(timeoutRef.current)
				}

				// Trigger the effect
				setIsActivated(true)

				// Reset after animation completes
				timeoutRef.current = setTimeout(() => {
					setIsActivated(false)
					onEffectEnd?.()
				}, 500) // Match the animation duration from CSS

				return () => {
					if (timeoutRef.current) {
						clearTimeout(timeoutRef.current)
					}
				}
			},
		}),
		[onEffectEnd],
	)

	return (
		<div className={cn("ibm--ai-effect-border-wrapper", isActivated && "activated")}>
			<div className="ibm--ai-effect-border">{children}</div>
		</div>
	)
})

AiEffect.displayName = "AiEffect"

export default AiEffect
