import React, { memo, useState } from "react"
import { useTranslation } from "react-i18next"
import { ClineMessage, SuggestionItem, FollowUpData } from "@roo-code/types"
import { safeJsonParse } from "@roo/safeJsonParse"

/**
 * Parse follow-up data from a message
 */
function parseFollowUpData(message: ClineMessage): FollowUpData | null {
	if (message.type === "ask" && message.ask === "followup" && !message.partial) {
		const result = safeJsonParse<FollowUpData>(message.text)
		return result || null
	}
	return null
}

// Import ask message components
import CommandMessage from "./ask/CommandMessage"
import FollowUpMessage from "./ask/FollowUpMessage"
import McpServerMessage from "./ask/McpServerMessage"
import CommandSecurityCheckingMessage from "./ask/CommandSecurityCheckingMessage"
import { AutoApprovedRequestLimitWarning } from "@/components/chat/AutoApprovedRequestLimitWarning"
import ControlledChat from "../controlled-chat/ControlledChat"
import CompletionResult from "../completionResult/CompletionResult"
import ErrorMessage from "./say/ErrorMessage"
import { BrowserRequest } from "./say/BrowserRequest";

/**
 * Props for the AskRouter component
 */
interface AskRouterProps {
	message: ClineMessage
	onSuggestionClick?: (suggestion: SuggestionItem, event?: React.MouseEvent) => void
	onFollowUpUnmount?: () => void
	isFollowUpAnswered?: boolean
	onSecurityAcknowledged?: (acknowledged: boolean) => void // ibm_change: for command security warning acknowledgment
}

/**
 * Router component for ask-related messages
 */
export const AskRouter: React.FC<AskRouterProps> = ({
	message,
	onSuggestionClick,
	onFollowUpUnmount,
	isFollowUpAnswered,
	onSecurityAcknowledged, // ibm_change: for command security warning acknowledgment
}) => {
	const { t } = useTranslation()
	// Parse follow-up data
	const followUpData = React.useMemo(() => parseFollowUpData(message), [message])
	const [isExpanded, setIsExpanded] = useState(false)

	if (message.type !== "ask") return null

	switch (message.ask) {
		case "browser_action_launch":
			return <BrowserRequest 
				message={message} 
				isExpanded={isExpanded}
				setIsExpanded={setIsExpanded}
				/>
			
		case "mistake_limit_reached":
			return (
				<ErrorMessage
					message={message}
					title={t("ibm:chat.troubleMessage")}
					isErrorExpanded={isExpanded}
					setIsErrorExpanded={setIsExpanded}
				/>
			)
		case "command":
			return <CommandMessage message={message} />
		case "use_mcp_server":
			return <McpServerMessage message={message} />
		case "completion_result":
			return <CompletionResult message={message} />
		case "followup":
			return (
				<FollowUpMessage
					message={message}
					followUpData={followUpData}
					onSuggestionClick={onSuggestionClick}
					onFollowUpUnmount={onFollowUpUnmount}
					isFollowUpAnswered={isFollowUpAnswered}
				/>
			)
		case "controlled_chat_flow":
			return <ControlledChat message={message} />
		case "auto_approval_max_req_reached":
			return <AutoApprovedRequestLimitWarning message={message} />
		case "command_security_checking":
			return <CommandSecurityCheckingMessage message={message} />
		case "command_security_warning":
			return <CommandMessage message={message} securityWarning={true} onSecurityAcknowledged={onSecurityAcknowledged} />
		default:
			// For ask messages we haven't extracted yet, return null
			console.warn(`Unhandled ask message type: ${message.ask}`)
			return null
	}
}

export default memo(AskRouter)

