import React, { useEffect, useRef } from "react"
import { Todo } from "./types"
import { ChecklistIcon } from "./ChecklistIcon"
import { TodoItem } from "./TodoItem"
import { useTranslation } from "react-i18next"

export interface ExpandedViewProps {
	todos: Todo[]
	completedCount: number
	totalCount: number
	currentFocusedTodo: {
		todo: Todo | undefined
		index: number
		isFirst: boolean
		isLast: boolean
	}
	onToggle: () => void
}

export const ExpandedView = ({
	todos,
	completedCount,
	totalCount,
	currentFocusedTodo,
	onToggle,
}: ExpandedViewProps) => {
	const { t } = useTranslation("ibm")
	const ulRef = useRef<HTMLUListElement>(null)
	const itemRefs = useRef<(HTMLLIElement | null)[]>([])
	// Scroll to the most important todo when expanded
	useEffect(() => {
		if (!ulRef.current || currentFocusedTodo.index === -1) return

		const target = itemRefs.current[currentFocusedTodo.index]
		if (!target) return

		const ul = ulRef.current
		const targetTop = target.offsetTop - ul.offsetTop
		const targetHeight = target.offsetHeight
		const ulHeight = ul.clientHeight

		// Center the target item in the viewport
		const scrollTo = targetTop - (ulHeight / 2 - targetHeight / 2)
		ul.scrollTop = Math.max(0, scrollTo)
	}, [todos, currentFocusedTodo.index])

	// Render a single todo item
	const renderTodoItem = (todo: Todo, idx: number) => {
		const isCurrentTodo = idx === currentFocusedTodo.index
		const isFirst = idx === 0
		const isLast = idx === todos.length - 1

		return (
			<TodoItem
				key={todo.id || todo.content}
				todo={todo}
				isCurrentTodo={isCurrentTodo}
				isFirst={isFirst}
				isLast={isLast}
				itemRef={(el) => (itemRefs.current[idx] = el)}
			/>
		)
	}

	return (
		<>
			{/* Header */}
			<div
				data-testid="todo-list-header"
				className="flex items-center justify-between gap-0.5 cursor-pointer select-none pl-[8px] py-[8px] pr-[8px]"
				onClick={onToggle}>
				{/* Left side with title and count */}
				<div className="flex items-center flex-1 min-w-0 gap-1 text-[12px]">
					<ChecklistIcon />
					<span data-testid="todo-list-title" className="font-bold">
						{t("todoList.display.todoListTitle")}
					</span>
					<span
						data-testid="todo-list-count"
						className="text-[var(--vscode-descriptionForeground)] font-medium">
						{completedCount}/{totalCount}
					</span>
				</div>

				{/* Right side with collapse button */}
				<span className="codicon codicon-chevron-up" />
			</div>

			{/* Todo list */}
			<ul data-testid="todo-list" ref={ulRef} className="m-0 pl-0 list-none max-h-[340px] overflow-y-auto">
				{todos.map(renderTodoItem)}
			</ul>
		</>
	)
}

