import React from "react"
import { ClineMessage } from "@roo-code/types"
import { useTranslation } from "react-i18next"
import { VSCodeBadge } from "@vscode/webview-ui-toolkit/react"
import { safeJsonParse } from "@roo/safeJsonParse"
import { ClineSayTool } from "@roo/ExtensionMessage"
import { ToolUseBlock, ToolUseBlockHeader } from "../common/ToolUseBlock"
import { headerStyle } from "../common/HeaderStyles"

interface ToolMessageProps {
	message: ClineMessage
}

/**
 * Component for displaying tool messages
 */
const ToolMessage: React.FC<ToolMessageProps> = ({ message }) => {
	const { t } = useTranslation()

	// Parse the tool data from the message
	const sayTool = safeJsonParse<ClineSayTool>(message.text)
	if (!sayTool) return null

	switch (sayTool.tool) {
		case "runSlashCommand": {
			const slashCommandInfo = sayTool
			return (
				<>
					<div style={headerStyle}>
						<span
							className="codicon codicon-terminal-cmd"
							style={{
								color: "var(--vscode-foreground)",
								marginBottom: "-1.5px",
							}}></span>
						<span style={{ fontWeight: "bold" }}>{t("chat:slashCommand.didRun")}</span>
					</div>
					<ToolUseBlock>
						<ToolUseBlockHeader
							style={{
								display: "flex",
								flexDirection: "column",
								alignItems: "flex-start",
								gap: "4px",
								padding: "10px 12px",
							}}>
							<div
								style={{
									display: "flex",
									alignItems: "center",
									gap: "8px",
									width: "100%",
								}}>
								<span style={{ fontWeight: "500", fontSize: "var(--vscode-font-size)" }}>
									/{slashCommandInfo.command}
								</span>
								{slashCommandInfo.args && (
									<span
										style={{
											color: "var(--vscode-descriptionForeground)",
											fontSize: "var(--vscode-font-size)",
										}}>
										{slashCommandInfo.args}
									</span>
								)}
							</div>
							{slashCommandInfo.description && (
								<div
									style={{
										color: "var(--vscode-descriptionForeground)",
										fontSize: "calc(var(--vscode-font-size) - 1px)",
									}}>
									{slashCommandInfo.description}
								</div>
							)}
							{slashCommandInfo.source && (
								<div style={{ display: "flex", alignItems: "center", gap: "4px" }}>
									<VSCodeBadge style={{ fontSize: "calc(var(--vscode-font-size) - 2px)" }}>
										{slashCommandInfo.source}
									</VSCodeBadge>
								</div>
							)}
						</ToolUseBlockHeader>
					</ToolUseBlock>
				</>
			)
		}
		default:
			return null
	}
}

export default ToolMessage

