import { useCallback, useMemo, useState, useRef, useEffect } from "react"
import { Trans } from "react-i18next"
import { VSCodeLink } from "@vscode/webview-ui-toolkit/react"
import ToggleButton from "@src/ibm/components/common/toggleButton/ToggleButton"

import { vscode } from "@src/utils/vscode"
import { useExtensionState } from "@src/context/ExtensionStateContext"
import { useAppTranslation } from "@src/i18n/TranslationContext"
import { useAutoApprovalState } from "@src/hooks/useAutoApprovalState"
import { useAutoApprovalToggles } from "@src/hooks/useAutoApprovalToggles"
import {
	type AutoApproveSetting,
	autoApproveSettingsConfig,
	AutoApproveToggle,
} from "@/components/settings/AutoApproveToggle"
import { StandardTooltip } from "@/components/ui"
import { CheckCheck } from "lucide-react"

interface AutoApproveMenuProps {
	style?: React.CSSProperties
}

const HOVER__DELAY = 700 // Delay used for expanding and collapsing the actions

/**
 * AutoApproveMenu component with enhanced icon-based UI
 *
 * Features:
 * - Icon bar showing enabled permissions
 * - Hover expansion after short delay
 * - Full detailed view via chevron
 */
const AutoApproveMenu = ({ style }: AutoApproveMenuProps) => {
	const [isHovering, setIsHovering] = useState(false)
	const hoverTimerRef = useRef<NodeJS.Timeout | null>(null)

	const {
		autoApprovalEnabled,
		setAutoApprovalEnabled,
		alwaysApproveResubmit,
		setAlwaysAllowReadOnly,
		setAlwaysAllowWrite,
		setAlwaysAllowExecute,
		setAlwaysAllowBrowser,
		setAlwaysAllowMcp,
		setAlwaysAllowModeSwitch,
		setAlwaysAllowSubtasks,
		setAlwaysApproveResubmit,
		setAlwaysAllowFollowupQuestions,
		setAlwaysAllowUpdateTodoList,
		activeProfile,
	} = useExtensionState()

	const isExternal = activeProfile != null && !activeProfile.is_internal
	const hiddenKeys: AutoApproveSetting[] | undefined = isExternal
		? ["alwaysAllowBrowser", "alwaysApproveResubmit"]
		: undefined

	const { t } = useAppTranslation()

	// Get base toggles from the hook
	const baseToggles = useAutoApprovalToggles()

	// AutoApproveMenu needs alwaysApproveResubmit in addition to the base toggles
	const toggles = useMemo(
		() => ({
			...baseToggles,
			alwaysApproveResubmit: alwaysApproveResubmit,
		}),
		[baseToggles, alwaysApproveResubmit],
	)

	// Use the hook to determine effective auto approval state
	const { hasEnabledOptions, effectiveAutoApprovalEnabled } = useAutoApprovalState(toggles, autoApprovalEnabled)

	const onAutoApproveToggle = useCallback(
		(key: AutoApproveSetting, value: boolean) => {
			vscode.postMessage({ type: "updateSettings", updatedSettings: { [key]: value } })

			// Update the specific toggle state
			switch (key) {
				case "alwaysAllowReadOnly":
					setAlwaysAllowReadOnly(value)
					break
				case "alwaysAllowWrite":
					setAlwaysAllowWrite(value)
					break
				case "alwaysAllowExecute":
					setAlwaysAllowExecute(value)
					break
				case "alwaysAllowBrowser":
					setAlwaysAllowBrowser(value)
					break
				case "alwaysAllowMcp":
					setAlwaysAllowMcp(value)
					break
				case "alwaysAllowModeSwitch":
					setAlwaysAllowModeSwitch(value)
					break
				case "alwaysAllowSubtasks":
					setAlwaysAllowSubtasks(value)
					break
				case "alwaysApproveResubmit":
					setAlwaysApproveResubmit(value)
					break
				case "alwaysAllowFollowupQuestions":
					setAlwaysAllowFollowupQuestions(value)
					break
				case "alwaysAllowUpdateTodoList":
					setAlwaysAllowUpdateTodoList(value)
					break
			}

			// Check if we need to update the master auto-approval state
			// Create a new toggles state with the updated value
			const updatedToggles = {
				...toggles,
				[key]: value,
			}

			const willHaveEnabledOptions = Object.values(updatedToggles).some((v) => !!v)

			// If enabling the first option, enable master auto-approval
			if (value && !hasEnabledOptions && willHaveEnabledOptions) {
				setAutoApprovalEnabled(true)
				vscode.postMessage({ type: "autoApprovalEnabled", bool: true })
			}
			// If disabling the last option, disable master auto-approval
			else if (!value && hasEnabledOptions && !willHaveEnabledOptions) {
				setAutoApprovalEnabled(false)
				vscode.postMessage({ type: "autoApprovalEnabled", bool: false })
			}
		},
		[
			toggles,
			hasEnabledOptions,
			setAlwaysAllowReadOnly,
			setAlwaysAllowWrite,
			setAlwaysAllowExecute,
			setAlwaysAllowBrowser,
			setAlwaysAllowMcp,
			setAlwaysAllowModeSwitch,
			setAlwaysAllowSubtasks,
			setAlwaysApproveResubmit,
			setAlwaysAllowFollowupQuestions,
			setAlwaysAllowUpdateTodoList,
			setAutoApprovalEnabled,
		],
	)

	// ============================================================
	//   Hover handling for icon expansion
	// ============================================================
	const handleMouseEnter = useCallback(() => {
		if (hoverTimerRef.current) {
			clearTimeout(hoverTimerRef.current)
			hoverTimerRef.current = null
		}
		hoverTimerRef.current = setTimeout(() => {
			setIsHovering(true)
		}, HOVER__DELAY) // delay before showing expanded icons
	}, [])

	const handleMouseLeave = useCallback(() => {
		if (hoverTimerRef.current) {
			clearTimeout(hoverTimerRef.current)
			hoverTimerRef.current = null
		}
		hoverTimerRef.current = setTimeout(() => {
			setIsHovering(false)
		}, HOVER__DELAY / 2) // delay before hiding expanded icons
	}, [])

	// Cleanup timer on unmount
	useEffect(() => {
		return () => {
			if (hoverTimerRef.current) {
				clearTimeout(hoverTimerRef.current)
			}
		}
	}, [])
	// ============================================================

	const handleOpenSettings = useCallback(
		() =>
			vscode.postMessage({
				type: "executeCommand",
				commands: ["bob-code.settingsButtonClicked"],
				commandArgs: ["chat"],
			}),
		[],
	)

	// Get only enabled icons for collapsed view
	const enabledIcons = Object.entries(toggles)
		.filter(([key, value]) => !!value && !hiddenKeys?.includes(key as AutoApproveSetting))
		.map(([key]) => {
			const config = autoApproveSettingsConfig[key as AutoApproveSetting]
			const IconComponent = config.icon
			return (
				<span
					key={key}
					className="inline-flex mx-1"
					title={t(config.descriptionKey)}
					aria-label={t(config.labelKey)}>
					<IconComponent size={14} />
				</span>
			)
		})

	const handleCheckboxClick = () => {
		if (!hasEnabledOptions) {
			// If no actions enabled, enable read-only action
			onAutoApproveToggle("alwaysAllowReadOnly", true)
			return
		}
		const newValue = !(autoApprovalEnabled ?? false)
		setAutoApprovalEnabled(newValue)
		vscode.postMessage({ type: "autoApprovalEnabled", bool: newValue })
	}

	return (
		<div
			onBlur={(e) => !e.currentTarget.contains(e.relatedTarget) && setIsHovering(false)}
			onFocus={() => setIsHovering(true)}
			onKeyDown={(e) => e.key === "Escape" && setIsHovering(false)}
			onMouseEnter={handleMouseEnter}
			onMouseLeave={handleMouseLeave}
			className="border-t pb-1 mt-2 border-t-vscode-input-border">
			<div
				className="overflow-hidden"
				style={{
					maxHeight: isHovering ? "500px" : "0px",
					opacity: isHovering ? 1 : 0,
					transition:
						"max-height 300ms cubic-bezier(0.4, 0, 0.2, 1), opacity 300ms cubic-bezier(0.4, 0, 0.2, 1)",
				}}>
				<div className="flex flex-col gap-2 p-3 pb-0 pt-2">
					<div className="flex gap-1">
						<CheckCheck size={16} />
						{t("chat:autoApprove.title")}
					</div>
					<div className="text-vscode-descriptionForeground text-xs">
						<Trans
							i18nKey="chat:autoApprove.description"
							components={{
								settingsLink: <VSCodeLink href="#" onClick={handleOpenSettings} />,
							}}
						/>
					</div>

					<AutoApproveToggle {...toggles} onToggle={onAutoApproveToggle} isVisible={isHovering} hiddenKeys={hiddenKeys} />
				</div>
			</div>
			<div
				style={{
					padding: "0 15px",
					userSelect: "none",
					overflowY: "auto",
					...style,
				}}>
				<div
					style={{
						display: "flex",
						alignItems: "end",
						padding: "0",
						cursor: "pointer",
						width: "100%",
						paddingTop: "0.5rem",
					}}>
					<StandardTooltip
						side="bottom"
						content={
							!hasEnabledOptions
								? t("settings:autoApprove.checkboxTitleReadOnlyDefault")
								: autoApprovalEnabled
									? t("settings:autoApprove.checkboxTitleEnabled")
									: t("settings:autoApprove.checkboxTitleDisabled")
						}>
						<div className="flex items-center gap-2">
							<ToggleButton
								checked={effectiveAutoApprovalEnabled}
								onChange={() => handleCheckboxClick()}
								noContainer
								icon={<CheckCheck />}
							/>
							{!effectiveAutoApprovalEnabled || !hasEnabledOptions ? (
								<span
									onClick={handleCheckboxClick}
									style={{
										color: "var(--vscode-foreground)",
										flexShrink: 0,
									}}>
									{t("chat:autoApprove.disabled")}
								</span>
							) : null}
						</div>
					</StandardTooltip>
					<div className="flex ml-1 overflow-hidden" data-testid="auto-approve-icon-bar">
						<div className="truncate">{effectiveAutoApprovalEnabled ? enabledIcons : null}</div>
					</div>
				</div>
			</div>
		</div>
	)
}

export default AutoApproveMenu
