import React from "react"
import MarkdownBlock from "@/components/common/MarkdownBlock"
import ToolIcon from "../common/ToolIcon"
import { ClineMessage } from "@roo-code/types"
import { headerStyle } from "../common/HeaderStyles"
import { useAppTranslation } from "@/i18n/TranslationContext"

interface CreatePullRequestToolProps {
	message: ClineMessage
	tool: {
		tool: string
		content?: string
		query?: string // PR title
		reason?: string
	}
}

/**
 * Component for displaying pull request creation preview
 */
export const CreatePullRequestTool: React.FC<CreatePullRequestToolProps> = ({ message, tool }) => {
	const { t } = useAppTranslation()

	const parseBranchInfo = (reason?: string): { head?: string; base?: string; remote?: string } => {
		if (!reason) return {}
		const match = reason.match(/from (\S+) to (\S+) in (\S+)/)
		if (match) {
			return {
				head: match[1],
				base: match[2],
				remote: match[3],
			}
		}
		return {}
	}

	const branchInfo = parseBranchInfo(tool.reason)
	const hasTitle = !!tool.query
	const hasBranches = !!(branchInfo.head || branchInfo.base)
	// Filter out reason text when used as fallback content
	const descriptionContent = tool.content && tool.content !== tool.reason ? tool.content : undefined
	const hasDescription = !!descriptionContent && descriptionContent.trim().length > 0
	const hasAnyContent = hasTitle || hasBranches || hasDescription

	const labelClassName = "mb-1 text-[calc(var(--vscode-font-size)-1px)] text-vscode-descriptionForeground"

	const headerText =
		message.type === "ask" ? t("ibm:pullRequest.wantsToCreate") : t("ibm:pullRequest.didCreate")

	if (!hasAnyContent) {
		return (
			<div style={headerStyle}>
				<ToolIcon name="git-pull-request" />
				<span className="font-bold">{headerText}</span>
			</div>
		)
	}

	return (
		<>
			<div style={headerStyle}>
				<ToolIcon name="git-pull-request" />
				<span className="font-bold">{headerText}</span>
			</div>
			<div className="mt-1 bg-vscode-editor-background border border-vscode-editorGroup-border rounded overflow-hidden">
				<div className="bg-vscode-badge-background">
					{tool.query && (
						<div
							className={`px-4 py-3 bg-vscode-editor-background ${
								hasBranches || hasDescription
									? "border-b border-vscode-editorGroup-border"
									: "rounded-b"
							}`}>
							<div className={labelClassName}>{t("ibm:pullRequest.title")}</div>
							<div className="font-medium text-[var(--vscode-foreground)] break-words">{tool.query}</div>
						</div>
					)}

					{(branchInfo.head || branchInfo.base) && (
						<div
							className={`px-4 py-3 bg-vscode-editor-background ${
								hasDescription ? "border-b border-vscode-editorGroup-border" : "rounded-b"
							}`}>
							{branchInfo.head && (
								<div className="flex gap-1 mb-2">
									<div className={labelClassName}>{t("ibm:pullRequest.headBranch")}:</div>
									<div className="font-medium text-[var(--vscode-foreground)] break-all">
										{branchInfo.head}
									</div>
								</div>
							)}
							{branchInfo.base && (
								<div className="flex gap-1 mb-2">
									<div className={labelClassName}>{t("ibm:pullRequest.baseBranch")}:</div>
									<div className="font-medium text-[var(--vscode-foreground)] break-all">
										{branchInfo.base}
									</div>
								</div>
							)}
							{branchInfo.remote && (
								<div className="flex gap-1">
									<div className={labelClassName}>{t("ibm:pullRequest.remote")}:</div>
									<div className="font-medium text-[var(--vscode-foreground)] break-all">
										{branchInfo.remote}
									</div>
								</div>
							)}
							</div>
						)}

						{hasDescription && (
							<div className="px-4 py-3 bg-vscode-editor-background rounded-b">
								<div className={`${labelClassName} mb-[30px] font-medium`}>
									{t("ibm:pullRequest.description")}
								</div>
								<div className="-mt-8 break-words [overflow-wrap:anywhere]">
									<MarkdownBlock markdown={descriptionContent} />
								</div>
							</div>
						)}
				</div>
			</div>
		</>
	)
}

export default CreatePullRequestTool

