import React from "react"
import { useTranslation } from "react-i18next"
import { ClineMessage } from "@roo-code/types"
import FileOperation from "../common/FileOperation"
import { vscode } from "@src/utils/vscode"

interface ReadFileToolProps {
	message: ClineMessage
	isExpanded: boolean
	onToggleExpand: () => void
	tool: {
		tool: string
		path?: string
		content: string
		reason?: string
		isOutsideWorkspace?: boolean
		additionalFileCount?: number
		batchFiles?: any[]
	}
	onBatchFileResponse?: (response: { [key: string]: boolean }) => void
}

/**
 * Component for handling file reading operations
 */
export const ReadFileTool: React.FC<ReadFileToolProps> = ({
	message,
	tool,
	onBatchFileResponse,
	isExpanded,
	onToggleExpand,
}) => {
	const { t } = useTranslation()

	// Check if this is a batch file permission request
	const isBatchRequest = message.type === "ask" && tool.batchFiles && Array.isArray(tool.batchFiles)

	// Determine the title based on the message type and tool properties
	const title =
		message.type === "ask"
			? tool.isOutsideWorkspace
				? t("chat:fileOperations.wantsToReadOutsideWorkspace")
				: tool.additionalFileCount && tool.additionalFileCount > 0
					? t("chat:fileOperations.wantsToReadAndXMore", {
							count: tool.additionalFileCount,
						})
					: isBatchRequest
						? t("chat:fileOperations.wantsToReadMultiple")
						: t("chat:fileOperations.wantsToRead")
			: t("chat:fileOperations.didRead")

	// Use the FileOperation component for both single and batch file operations
	return (
		<FileOperation
			message={message}
			isExpanded={isExpanded}
			onToggleExpand={onToggleExpand}
			icon={isBatchRequest ? "files" : "file-code"}
			title={title}
			path={tool.path || ""}
			content={tool.content}
			language="plaintext"
			isProtected={false}
			isOutsideWorkspace={tool.isOutsideWorkspace}
			onJumpToFile={() => {
				if (tool.content) {
					vscode.postMessage({ type: "openFile", text: tool.content })
				}
			}}
			batchPermissionFiles={isBatchRequest ? tool.batchFiles : undefined}
			onBatchFileResponse={onBatchFileResponse}
			reason={tool.reason}
		/>
	)
}

export default ReadFileTool

