import React from "react"
import { useTranslation } from "react-i18next"
import { ClineMessage } from "@roo-code/types"
import FileOperation from "../common/FileOperation"

interface InsertContentToolProps {
	message: ClineMessage
	isExpanded: boolean
	onToggleExpand: () => void
	tool: {
		tool: string
		path: string
		diff: string
		lineNumber: number
		isProtected?: boolean
		isOutsideWorkspace?: boolean
	}
}

/**
 * Component for handling content insertion operations
 */
export const InsertContentTool: React.FC<InsertContentToolProps> = ({ message, tool, isExpanded, onToggleExpand }) => {
	const { t } = useTranslation()

	// Determine the title based on the context
	const title = tool.isProtected
		? t("chat:fileOperations.wantsToEditProtected")
		: tool.isOutsideWorkspace
			? t("chat:fileOperations.wantsToEditOutsideWorkspace")
			: tool.lineNumber === 0
				? t("chat:fileOperations.wantsToInsertAtEnd")
				: t("chat:fileOperations.wantsToInsertWithLineNumber", {
						lineNumber: tool.lineNumber,
					})

	return (
		<FileOperation
			message={message}
			icon="insert"
			title={title}
			path={tool.path}
			content={tool.diff}
			language="diff"
			isExpanded={isExpanded}
			onToggleExpand={onToggleExpand}
			isProtected={tool.isProtected}
			isOutsideWorkspace={tool.isOutsideWorkspace}
		/>
	)
}

export default InsertContentTool

