import * as React from "react"
import { Button } from "@/components/ui"
import { memo } from "react"
import { sendChatResponse } from "../../../sendChatResponse"
import { useAppTranslation } from "@/i18n/TranslationContext"
import {
	EJPromptTemplateInfo,
	EJ_GET_PROMPTS_COMMAND,
	EJ_SET_AUTOMATION_FLAG_COMMAND,
	GIT_ADD_COMMAND,
	GIT_COMMIT_COMMAND,
} from "../ejCommands"
import { callCommand } from "@/ibm/utils/callCommand"
import { constructMapOfPromptsByRule, structurePromptsMapFromResult, structurePromptFromResult } from "../utils"
import { ProgressNotification } from "@/ibm/components/common/progressNotification/ProgressNotification"

const ApplyAssistedFixesStep: React.FC<{ config: any }> = ({ config }) => {
	// console.log('==> ApplyAssistedFixesStep', config)
	const { t } = useAppTranslation()
	const actionHasBeenTriggered = React.useRef(config.props.isCompleted)
	const [fixesApplied, setFixesApplied] = React.useState(config.props.isCompleted)
	const [isApplying, setIsApplying] = React.useState(config.props.isCompleted)
	const [pendingMessage, setPendingMessage] = React.useState<string>(t("ibm:javaUpgrade.applyAssistedFixes.applyingMessage"))

	const handleApplyAssistedFixes = async () => {
		if (actionHasBeenTriggered.current) {
			return
		}
		actionHasBeenTriggered.current = true
		if (config.props.isCompleted || fixesApplied) {
			setFixesApplied(true)
			return
		}
		setIsApplying(true)

		await callCommand(EJ_SET_AUTOMATION_FLAG_COMMAND, true)

		const llmPrompts: Map<string, any[]> = structurePromptsMapFromResult(await callCommand(EJ_GET_PROMPTS_COMMAND))

		// Code range has some problem, need to manually cast it

		const rulePrompts = constructMapOfPromptsByRule(llmPrompts)

		let index = 0
		const fixLength = Array.from(rulePrompts.values()).flat().length
		setPendingMessage(`Applying assisted fixes(${index}/${fixLength})...`)
		// wait 3 seconds to simulate the vscode api call

		// Second pass - apply fixes rule by rule
		for (const [_, prompts] of rulePrompts) {
			if (prompts.length === 0) {
				continue
			}

			for (const originalPrompt of prompts) {
				index++
				setPendingMessage(`Applying assisted fixes(${index}/${fixLength})...`)

				// update status about this prompt to upgrade webview panel
				await callCommand(
					"wca4j.setPromptStatus",
					originalPrompt.ruleId,
					originalPrompt.resultIndex,
					originalPrompt.detailIndex,
					"pending",
				)

				const prompt: EJPromptTemplateInfo | undefined = await callCommand(
					"ejRulesWebview.recalculateCodeRange",
					originalPrompt,
				)

				// If there is no prompt object that means the function was renamed or deleted
				// and we can skip this prompt.
				if (!prompt) {
					continue
				}
				const structuredPrompt: EJPromptTemplateInfo = structurePromptFromResult(prompt)

				const response = await callCommand("ibm.theia.wca.llm-edit", structuredPrompt)

				if (response) {
					if (config.props.fullyAutomatedMode) {
						//only add to git if in yolo mode
						await callCommand(GIT_ADD_COMMAND, prompt.sourceFilePath)
					}

					// update status about this prompt to upgrade webview panel
					await callCommand(
						"wca4j.setPromptStatus",
						originalPrompt.ruleId,
						originalPrompt.resultIndex,
						originalPrompt.detailIndex,
						"applied",
					)
				}
			}

			if (config.props.fullyAutomatedMode) {
				//only add to git if in yolo mode
				await callCommand(GIT_COMMIT_COMMAND, `fix: ${prompts[0].ruleName}`)
			}
		}

		if (config.props.fullyAutomatedMode === false) {
			await callCommand(EJ_SET_AUTOMATION_FLAG_COMMAND, false)
		}

		setFixesApplied(true)
		setIsApplying(false)
		sendChatResponse({
			flowId: config.flowId,
			stepId: config.stepId,
			message: t("ibm:javaUpgrade.applyAssistedFixes.appliedMessage"),
			data: {
				isCompleted: true,
			},
		})

		return true
	}

	React.useEffect(() => {
		if (config.props.fullyAutomatedMode) {
			handleApplyAssistedFixes()
		}
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [])

	let progress = null
	let buttonText = ""
	if (fixesApplied) {
		buttonText = t("ibm:javaUpgrade.applyAssistedFixes.buttonApplied")
		progress = <ProgressNotification mode="completed" message={t("ibm:javaUpgrade.applyAssistedFixes.appliedMessage")} />
	} else if (isApplying) {
		buttonText = t("ibm:javaUpgrade.applyAssistedFixes.buttonRunning")
		progress = <ProgressNotification mode="thinking" message={pendingMessage} />
	} else {
		buttonText = t("ibm:javaUpgrade.applyAssistedFixes.buttonApply")
		progress = <ProgressNotification mode="loading" message={t("ibm:javaUpgrade.applyAssistedFixes.awaitingConfirmation")} />
	}

	return (
		<div>
			<h3>{t("ibm:javaUpgrade.applyAssistedFixes.title")}</h3>
			{config.props.fullyAutomatedMode && (
				<p>
					{t("ibm:javaUpgrade.applyAssistedFixes.descriptionAuto")}
				</p>
			)}
			{!config.props.fullyAutomatedMode && (
				<div>
					<p>
						{t("ibm:javaUpgrade.applyAssistedFixes.description")}
					</p>
					<div className="ibm--java-chat__content">
						<Button
							className="ibm--java-chat__button"
							disabled={actionHasBeenTriggered.current}
							onClick={handleApplyAssistedFixes}>
							{buttonText}
						</Button>
					</div>
				</div>
			)}
			{progress}
		</div>
	)
}

export default memo(ApplyAssistedFixesStep)
