import { StepLike, StepLikeStatus } from "@roo-code/types"

export const isStepRunning = (subSteps: StepLike[]): boolean => {
	return subSteps.length > 0 && subSteps.some((subStep) => subStep.status === StepLikeStatus.RUNNING)
}

export const isStepInProgress = (subSteps: StepLike[]): boolean => {
	return (
		subSteps.length > 0 &&
		subSteps.some(
			(subStep) => subStep.status === StepLikeStatus.PENDING || subStep.status === StepLikeStatus.RUNNING,
		)
	)
}

export const getFailedSteps = (steps: StepLike[]): StepLike[] => {
	return steps.filter((step) => step.status === StepLikeStatus.FAILURE || step.status === StepLikeStatus.ERROR)
}
