import React from "react"
import { Fzf } from "fzf"
import { ChevronUp, Check, X } from "lucide-react"

import { type ModeConfig, type CustomModePrompts, TelemetryEventName } from "@roo-code/types"

import { type Mode, getAllModes } from "@roo/modes"

import { vscode } from "@/utils/vscode"
import { telemetryClient } from "@/utils/TelemetryClient"
import { cn } from "@/lib/utils"
import { useExtensionState } from "@/context/ExtensionStateContext"
import { useAppTranslation } from "@/i18n/TranslationContext"
import { useRooPortal } from "@/components/ui/hooks/useRooPortal"
import { Popover, PopoverContent, PopoverTrigger, StandardTooltip } from "@/components/ui"
import { IconButton } from "@/components/chat/IconButton"

const SEARCH_THRESHOLD = 6

interface ModeSelectorProps {
	value: Mode
	onChange: (value: Mode) => void
	disabled?: boolean
	title: string
	triggerClassName?: string
	modeShortcutText: string
	customModes?: ModeConfig[]
	customModePrompts?: CustomModePrompts
	disableSearch?: boolean
	focusChatTextArea?: () => void
}

export const ModeSelector = ({
	value,
	onChange,
	disabled = false,
	title,
	triggerClassName = "",
	modeShortcutText,
	customModes,
	customModePrompts,
	disableSearch = false,
	focusChatTextArea,
}: ModeSelectorProps) => {
	const [open, setOpen] = React.useState(false)
	const [searchValue, setSearchValue] = React.useState("")
	const [focusedIndex, setFocusedIndex] = React.useState(-1)
	const searchInputRef = React.useRef<HTMLInputElement>(null)
	const modeItemRefs = React.useRef<Map<number, HTMLDivElement>>(new Map())
	const popoverContentRef = React.useRef<HTMLDivElement>(null)
	const isPointerInteraction = React.useRef(false)
	const portalContainer = useRooPortal("roo-portal")
	const { hasOpenedModeSelector, setHasOpenedModeSelector } = useExtensionState()
	const { t } = useAppTranslation()

	const trackModeSelectorOpened = React.useCallback(() => {
		// Track telemetry every time the mode selector is opened.
		telemetryClient.capture(TelemetryEventName.MODE_SELECTOR_OPENED)

		// Track first-time usage for UI purposes.
		if (!hasOpenedModeSelector) {
			setHasOpenedModeSelector(true)
			vscode.postMessage({ type: "hasOpenedModeSelector", bool: true })
		}
	}, [hasOpenedModeSelector, setHasOpenedModeSelector])

	// Get all modes including custom modes and merge custom prompt descriptions.
	const modes = React.useMemo(() => {
		const allModes = getAllModes(customModes)

		return allModes.map((mode) => ({
			...mode,
			description: customModePrompts?.[mode.slug]?.description ?? mode.description,
		}))
	}, [customModes, customModePrompts])

	// Find the selected mode.
	const selectedMode = React.useMemo(() => modes.find((mode) => mode.slug === value), [modes, value])

	// Memoize searchable items for fuzzy search with separate name and
	// description search.
	const nameSearchItems = React.useMemo(() => {
		return modes.map((mode) => ({
			original: mode,
			searchStr: [mode.name, mode.slug].filter(Boolean).join(" "),
		}))
	}, [modes])

	const descriptionSearchItems = React.useMemo(() => {
		return modes.map((mode) => ({
			original: mode,
			searchStr: mode.description || "",
		}))
	}, [modes])

	// Create memoized Fzf instances for name and description searches.
	const nameFzfInstance = React.useMemo(
		() => new Fzf(nameSearchItems, { selector: (item) => item.searchStr }),
		[nameSearchItems],
	)

	const descriptionFzfInstance = React.useMemo(
		() => new Fzf(descriptionSearchItems, { selector: (item) => item.searchStr }),
		[descriptionSearchItems],
	)

	// Filter modes based on search value using fuzzy search with priority.
	const filteredModes = React.useMemo(() => {
		if (!searchValue) return modes

		// First search in names/slugs.
		const nameMatches = nameFzfInstance.find(searchValue)
		const nameMatchedModes = new Set(nameMatches.map((result) => result.item.original.slug))

		// Then search in descriptions.
		const descriptionMatches = descriptionFzfInstance.find(searchValue)

		// Combine results: name matches first, then description matches.
		const combinedResults = [
			...nameMatches.map((result) => result.item.original),
			...descriptionMatches
				.filter((result) => !nameMatchedModes.has(result.item.original.slug))
				.map((result) => result.item.original),
		]

		return combinedResults
	}, [modes, searchValue, nameFzfInstance, descriptionFzfInstance])

	const onClearSearch = React.useCallback(() => {
		setSearchValue("")
		searchInputRef.current?.focus()
	}, [])

	const handleSelect = React.useCallback(
		(modeSlug: string, isKeyboardSelection = false) => {
			onChange(modeSlug as Mode)
			setOpen(false)
			setSearchValue("")
			setFocusedIndex(-1)
			if (isKeyboardSelection && focusChatTextArea) {
				focusChatTextArea()
			}
		},
		[onChange, focusChatTextArea],
	)

	const onOpenChange = React.useCallback(
		(isOpen: boolean) => {
			if (isOpen) trackModeSelectorOpened()
			setOpen(isOpen)

			// Clear search when closing.
			if (!isOpen) {
				setSearchValue("")
				setFocusedIndex(-1)
			}
		},
		[trackModeSelectorOpened],
	)

	// Handle focus changes via useEffect
	React.useEffect(() => {
		if (open && focusedIndex >= 0) {
			modeItemRefs.current.get(focusedIndex)?.focus()
		}
	}, [focusedIndex, open])

	// Reset focused index when filtered modes change
	React.useEffect(() => {
		setFocusedIndex(-1)
	}, [searchValue])

	// Determine if search should be shown.
	const showSearch = !disableSearch && modes.length > SEARCH_THRESHOLD

	// Combine instruction text for tooltip.
	const instructionText = `${t("chat:modeSelector.description")} ${modeShortcutText}`

	return (
		<Popover open={open} onOpenChange={onOpenChange} data-testid="mode-selector-root">
			<StandardTooltip content={title}>
				<PopoverTrigger
					disabled={disabled}
					data-testid="mode-selector-trigger"
					className={cn(
						"inline-flex items-center gap-1.5 relative whitespace-nowrap px-1.5 py-1 text-xs",
						"bg-transparent border border-[rgba(255,255,255,0.08)] rounded-md text-vscode-foreground",
						"transition-all duration-150 focus:outline-none focus-visible:ring-1 focus-visible:ring-vscode-focusBorder focus-visible:ring-inset",
						disabled
							? "opacity-50 cursor-not-allowed"
							: "opacity-90 hover:opacity-100 hover:bg-[rgba(255,255,255,0.03)] hover:border-[rgba(255,255,255,0.15)] cursor-pointer",
						triggerClassName,
						!disabled && !hasOpenedModeSelector
							? "bg-primary opacity-90 hover:bg-primary-hover text-vscode-button-foreground"
							: null,
					)}>
					<span className="truncate">{selectedMode?.name || ""}</span>
					<ChevronUp
						className={cn(
							"pointer-events-none opacity-80 flex-shrink-0 size-3 transition-transform duration-200",
							open && "rotate-180",
						)}
					/>
				</PopoverTrigger>
			</StandardTooltip>
			<PopoverContent
				onPointerDownCapture={() => {
					isPointerInteraction.current = true
				}}
				// Conditionally prevent focus return based on user interaction
				onCloseAutoFocus={(event) => {
					if (isPointerInteraction.current) {
						event.preventDefault()
					}
					isPointerInteraction.current = false
				}}
				ref={popoverContentRef}
				align="start"
				sideOffset={4}
				container={portalContainer}
				className="p-0 overflow-hidden min-w-60 max-w-9/10">
				<div
					className="flex flex-col w-full focus:outline-0"
					role="dialog"
					aria-label={t("chat:modeSelector.title")}
					tabIndex={0}
					onKeyDown={(e) => {
						if (e.key === "ArrowDown" && focusedIndex === -1 && filteredModes.length > 0) {
							e.preventDefault()
							setFocusedIndex(0)
						} else if (e.key === "ArrowUp" && focusedIndex === -1 && filteredModes.length > 0) {
							e.preventDefault()
							setFocusedIndex(filteredModes.length - 1)
						}
					}}>
					<div className="flex flex-row items-center justify-between py-0.5 pl-2 pr-1 border-t border-vscode-dropdown-border">
						<span>{t("chat:modeSelector.title")}</span>
						<div>
							<IconButton
								title={instructionText}
								iconClass="codicon-info hover:unset"
								className="cursor-help hover:bg-transparent active:bg-transparent"
							/>
							<IconButton
								iconClass="codicon-settings-gear"
								title={t("chat:modeSelector.settings")}
								onClick={() => {
									vscode.postMessage({
										type: "executeCommand",
										commands: ["bob-code.settingsButtonClicked"],
										commandArgs: ["modes"],
									})
									setOpen(false)
								}}
							/>
						</div>
					</div>

					{/* Mode List */}
					<div className="max-h-[300px] overflow-y-auto" role="listbox">
						{filteredModes.length === 0 && searchValue ? (
							<div className="py-2 px-3 text-sm text-vscode-foreground/70">
								{t("chat:modeSelector.noResults")}
							</div>
						) : (
							<div className="py-1">
								{filteredModes.map((mode, index) => {
									const isSelected = mode.slug === value
									const isFocused = index === focusedIndex
									return (
										<StandardTooltip
											key={mode.slug}
											content={
												<div>
													<div className="font-bold">{mode.name}</div>
													<div>{mode.description}</div>
												</div>
											}
											disableHoverableContent={true}
											delayDuration={500}>
											<div
												ref={(el) => {
													if (el) {
														modeItemRefs.current.set(index, el)
													} else {
														modeItemRefs.current.delete(index)
													}
												}}
												role="option"
												aria-selected={isSelected}
												tabIndex={0}
												onClick={() => {
													handleSelect(mode.slug, false)
												}}
												onKeyDown={(e) => {
													if (e.key === "Enter" || e.key === " ") {
														e.preventDefault()
														handleSelect(mode.slug, true)
													} else if (e.key === "ArrowDown") {
														e.preventDefault()
														const nextIndex = Math.min(index + 1, filteredModes.length - 1)
														setFocusedIndex(nextIndex)
													} else if (e.key === "ArrowUp") {
														e.preventDefault()
														const prevIndex = Math.max(index - 1, 0)
														setFocusedIndex(prevIndex)
													}
												}}
												className={cn(
													"px-3 py-1.5 text-sm cursor-pointer flex items-center",
													"hover:bg-vscode-list-hoverBackground",
													"focus:outline-none focus-visible:ring-1 focus-visible:ring-vscode-focusBorder focus-visible:ring-inset",
													isSelected
														? "bg-vscode-list-activeSelectionBackground text-vscode-list-activeSelectionForeground"
														: "",
													isFocused ? "bg-vscode-list-hoverBackground" : "",
												)}
												data-testid="mode-selector-item">
												<div className="flex-1 min-w-0">
													<div className="font-bold truncate">{mode.name}</div>
												</div>
												{isSelected && <Check className="ml-auto size-4 p-0.5" />}
											</div>
										</StandardTooltip>
									)
								})}
							</div>
						)}
					</div>
					{showSearch && (
						<div className="relative border-t border-vscode-dropdown-border rounded-b">
							<input
								aria-label={t("ibm:accessibility.searchModes")}
								ref={searchInputRef}
								value={searchValue}
								onChange={(e) => setSearchValue(e.target.value)}
								placeholder={t("chat:modeSelector.searchPlaceholder")}
								className="w-full h-8 px-2 py-1 text-xs bg-vscode-input-background text-vscode-input-foreground border border-vscode-input-border focus:outline-0"
								data-testid="mode-search-input"
							/>
							{searchValue.length > 0 && (
								<div className="absolute right-4 top-0 bottom-0 flex items-center justify-center">
									<X
										className="text-vscode-input-background opacity-50 hover:opacity-100 size-4 p-0.5 cursor-pointer"
										onClick={onClearSearch}
									/>
								</div>
							)}
						</div>
					)}
				</div>
			</PopoverContent>
		</Popover>
	)
}
