import React from "react"
import { useTranslation } from "react-i18next"
import { TodoStatus } from "../todoListDisplay"
import { TodoStatusMarker } from "../todoListDisplay/TodoItem"
import { StatusOption, TodoItemProps } from "./types"

/**
 * Component for rendering a single todo item
 */
export const TodoItem: React.FC<TodoItemProps> = ({
	todo,
	isEditing,
	isFirst,
	isLast,
	onContentChange,
	onStatusChange,
	onDelete,
}) => {
	const { t } = useTranslation("ibm")

	// Status options for the dropdown
	const statusOptions: StatusOption[] = [
		{
			value: "",
			label: t("todoList.status.notStarted"),
			border: "#bbb",
			bg: "transparent",
		},
		{
			value: "in_progress",
			label: t("todoList.status.inProgress"),
			border: "var(--vscode-charts-yellow)",
			bg: "rgba(255, 221, 51, 0.15)",
		},
		{
			value: "completed",
			label: t("todoList.status.completed"),
			border: "var(--vscode-charts-green)",
			bg: "var(--vscode-charts-green)",
		},
	]

	// Handle content change
	const handleContentChange = (e: React.ChangeEvent<HTMLInputElement>) => {
		onContentChange(todo.id!, e.target.value)
	}

	// Handle status change
	const handleStatusChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
		onStatusChange(todo.id!, e.target.value)
	}

	// Handle delete
	const handleDelete = () => {
		onDelete(todo.id!)
	}

	// Handle blur on empty content
	const handleBlur = (e: React.FocusEvent<HTMLInputElement>) => {
		if (!e.target.value.trim()) {
			onDelete(todo.id!)
		}
	}

	return (
		<li className="flex items-center min-h-5">
			<TodoStatusMarker
				status={
					todo.status === TodoStatus.COMPLETED || todo.status === TodoStatus.IN_PROGRESS
						? todo.status
						: TodoStatus.NOT_STARTED
				}
				showLineUp={!isFirst}
				showLineDown={!isLast}
			/>

			{isEditing ? (
				<>
					<input
						type="text"
						value={todo.content}
						placeholder={t("todoList.enterTodo")}
						onChange={handleContentChange}
						onBlur={handleBlur}
						className="flex-1 min-w-0 font-medium text-vscode-input-foreground bg-vscode-input-background border-none outline-none text-sm mr-1.5 px-0.5 py-0.5 border-b border-vscode-input-border"
					/>

					<select
						value={todo.status || ""}
						onChange={handleStatusChange}
						className="mr-1.5 rounded border border-vscode-input-border bg-vscode-input-background text-vscode-input-foreground text-xs px-1 py-0.5">
						{statusOptions.map((opt) => (
							<option key={opt.value} value={opt.value}>
								{opt.label}
							</option>
						))}
					</select>

					<button
						onClick={handleDelete}
						className="border-none bg-transparent text-red-500 cursor-pointer text-sm ml-0.5 p-0 leading-none"
						title={t("todoList.remove")}>
						×
					</button>
				</>
			) : (
				<span
					title={todo.content}
					className="flex-1 min-w-0 font-medium text-sm mr-1.5 px-0.5 py-0.5 leading-tight truncate overflow-hidden whitespace-nowrap">
					{todo.content}
				</span>
			)}
		</li>
	)
}

