import React from "react"

interface ToolIconProps {
	name: string
	color?: string
	isProtected?: boolean
}

/**
 * Shared tool icon component used across message components
 */
export const ToolIcon: React.FC<ToolIconProps> = ({ name, color, isProtected }) => {
	const normalColor = color || "var(--vscode-foreground)"
	const warningColor = "var(--vscode-editorWarning-foreground)"

	if (isProtected) {
		return <span className="codicon codicon-lock" style={{ color: warningColor, marginBottom: "-1.5px" }} />
	}

	return <span className={`codicon codicon-${name}`} style={{ color: normalColor, marginBottom: "-1.5px" }} />
}

export default ToolIcon

