import React from "react"
import { Trans } from "react-i18next"
import { ClineMessage } from "@roo-code/types"
import FileOperation from "../common/FileOperation"

interface SearchFilesToolProps {
	message: ClineMessage
	isExpanded: boolean
	onToggleExpand: () => void
	tool: {
		tool: string
		path?: string
		regex?: string
		filePattern?: string
		content?: string
		isOutsideWorkspace?: boolean
	}
}

/**
 * Component for displaying search files results
 */
export const SearchFilesTool: React.FC<SearchFilesToolProps> = ({ message, tool, isExpanded, onToggleExpand }) => {
	const title =
		message.type === "ask" ? (
			<Trans
				i18nKey={
					tool.isOutsideWorkspace
						? "chat:directoryOperations.wantsToSearchOutsideWorkspace"
						: "chat:directoryOperations.wantsToSearch"
				}
				components={{ code: <code>{tool.regex}</code> }}
				values={{ regex: tool.regex }}
			/>
		) : (
			<Trans
				i18nKey={
					tool.isOutsideWorkspace
						? "chat:directoryOperations.didSearchOutsideWorkspace"
						: "chat:directoryOperations.didSearch"
				}
				components={{ code: <code>{tool.regex}</code> }}
				values={{ regex: tool.regex }}
			/>
		)

	return (
		<FileOperation
			message={message}
			icon="search"
			title={title}
			path={tool.path! + (tool.filePattern ? `/(${tool.filePattern})` : "")}
			content={tool.content}
			language="shellsession"
			isExpanded={isExpanded}
			onToggleExpand={onToggleExpand}
			isOutsideWorkspace={tool.isOutsideWorkspace}
		/>
	)
}

export default SearchFilesTool

