export enum TodoStatus {
	COMPLETED = "completed",
	ALL_COMPLETED = "all_completed",
	IN_PROGRESS = "in_progress",
	NOT_STARTED = "not_started",
	ERROR = "error",
	SKIPPED = "skipped",
}

export interface Todo {
	id?: string
	content: string
	status: TodoStatus
}
