import { ClineApiReqInfo, ClineSayTool } from "@roo/ExtensionMessage"
import { safeJsonParse } from "@roo/safeJsonParse"
import { ClineMessage } from "@roo-code/types"

/**
 * Parse API request information from a message
 */
export function parseApiRequestInfo(
	message: ClineMessage,
): [cost?: number, cancelReason?: string, streamingFailedMessage?: string] {
	if (message.text !== null && message.text !== undefined && message.say === "api_req_started") {
		const info = safeJsonParse<ClineApiReqInfo>(message.text)
		return [info?.cost, info?.cancelReason, info?.streamingFailedMessage]
	}
	return [undefined, undefined, undefined]
}

/**
 * Parse tool information from a message
 */
export function parseTool(message: ClineMessage): ClineSayTool | null {
	if (message.ask === "tool") {
		const result = safeJsonParse<ClineSayTool>(message.text)
		return result || null
	}
	return null
}

