import React from "react"
import { useTranslation } from "react-i18next"
import { useTaskSearch } from "@/components/history/useTaskSearch"
import { vscode } from "@/utils/vscode"
import TaskItem from "@/components/history/TaskItem"

/**
 * RecentTasks component displays a collapsible section showing recent task history
 */
const RecentTasks: React.FC = () => {
	const { tasks } = useTaskSearch()
	const { t } = useTranslation("history")

	const handleViewAllHistory = () => {
		vscode.postMessage({ type: "switchTab", tab: "history" })
	}

	if (tasks.length === 0) {
		return null
	}

	return (
		<div className={`w-full px-2 mt-auto`}>
			{/* Show the task history preview if expanded and tasks exist */}
			<div className="flex justify-between mb-2 px-1">
				<div className="flex items-center gap-1 text-sm text-vscode-descriptionForeground font-medium">
					<span>{t("recentTasks")}</span>
				</div>
				<button
					onClick={handleViewAllHistory}
					className="text-sm text-vscode-descriptionForeground hover:text-vscode-textLink-foreground transition-colors font-medium cursor-pointer text-center"
					aria-label={t("ibm:welcome.seeAll")}>
					{t("ibm:welcome.seeAll")}
				</button>
			</div>
			<div className="flex flex-col gap-1">
				{tasks.slice(0, 3).map((item) => (
					<TaskItem key={item.id} item={item} variant="compact" />
				))}
			</div>
		</div>
	)
}

export default RecentTasks

