import * as React from "react"
import { Button } from "@/components/ui"
import { sendChatResponse } from "../../../sendChatResponse"
import { memo } from "react"
import { EJ_ANALYZE_JAVA_COMMAND, EJ_REVEAL_COMMAND, EJ_SET_AUTOMATION_FLAG_COMMAND } from "../ejCommands"
import { ProgressNotification } from "@/ibm/components/common/progressNotification/ProgressNotification"
import { callCommand } from "@/ibm/utils/callCommand"
import { useAppTranslation } from "@/i18n/TranslationContext"

const GenerateUpgradePlanStep: React.FC<{ config: any }> = ({ config }) => {
	// console.log('==> GenerateUpgradePlanStep', config)
	const { t } = useAppTranslation()
	const actionHasBeenTriggered = React.useRef(config.props.isCompleted)
	const [planGenerated, setPlanGenerated] = React.useState(config.props.isCompleted)

	const handleGeneratePlan = async () => {
		if (actionHasBeenTriggered.current) {
			return
		}
		actionHasBeenTriggered.current = true
		if (config.props.isCompleted || planGenerated) {
			// Plan has already been generated so we can skip the generation
			// this is to prevent the generation on the chat restarting
			setPlanGenerated(true)
			return
		}

		await callCommand(EJ_SET_AUTOMATION_FLAG_COMMAND, true)
		const analyzeJavaCommandArgs = {
			startOver: true,
			sourceJavaVersion: config.props.sourceJavaVersion,
			targetJavaVersion: config.props.targetJavaVersion,
		}

		const success = await callCommand(EJ_ANALYZE_JAVA_COMMAND, analyzeJavaCommandArgs)
		console.log("==> GenerateUpgradePlanStep generatePlan success", success)
		// TODO: Handle the non success case
		if (config.props.fullyAutomatedMode) {
			await callCommand(EJ_REVEAL_COMMAND)
		} else {
			await callCommand(EJ_SET_AUTOMATION_FLAG_COMMAND, false)
		}

		sendChatResponse({
			flowId: config.flowId,
			stepId: config.stepId,
			message: t("ibm:javaUpgrade.generateUpgradePlan.planGeneratedMessage"),
			data: {
				isCompleted: true,
				planGenerated: true,
			},
		})

		setPlanGenerated(true)
	}

	React.useEffect(() => {
		// Generate plan only on mount of the component
		console.log("==> GenerateUpgradePlanStep useEffect should only run once", config)
		handleGeneratePlan()
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [])

	let progress = null
	if (planGenerated) {
		progress = <ProgressNotification mode="completed" message={t("ibm:javaUpgrade.generateUpgradePlan.generatedMessage")} />
	} else {
		progress = <ProgressNotification mode="planning" message={t("ibm:javaUpgrade.generateUpgradePlan.generatingMessage")} />
	}

	return (
		<div>
			<h3>{t("ibm:javaUpgrade.generateUpgradePlan.title")}</h3>
			<p>
				{t("ibm:javaUpgrade.generateUpgradePlan.description")}
			</p>
			{planGenerated && !config.props.fullyAutomatedMode && (
				<div className="ibm--java-chat__content">
					<Button
						className="ibm--java-chat__button"
						onClick={async () => {
							await callCommand("ejRulesWebview.reveal")
						}}>
						{t("ibm:javaUpgrade.generateUpgradePlan.openPlanButton")}
					</Button>
				</div>
			)}
			{progress}
		</div>
	)
}

export default memo(GenerateUpgradePlanStep)
