import { memo } from "react"
import { useTranslation } from "react-i18next"
import { ErrorWarning } from "./ErrorWarning"

interface RateLimitWarningProps {
	retryAfter?: number
}

export const RateLimitWarning = memo(({ retryAfter }: RateLimitWarningProps) => {
	const { t } = useTranslation("ibm")

	const description = (
		<>
			{t("apiRequest.rateLimit.description")}
			{retryAfter !== undefined && retryAfter > 0 && (
				<div className="mt-2">{t("apiRequest.rateLimit.retryAfter", { seconds: retryAfter })}</div>
			)}
		</>
	)

	return <ErrorWarning title={t("apiRequest.rateLimit.title")} description={description} />
})

export default RateLimitWarning
