import { callCommand } from "@/ibm/utils/callCommand"
import { EJPromptTemplateInfo, GIT_CHECKOUT_COMMAND, GIT_CHECK_COMMIT_CHANGES_COMMAND } from "./ejCommands"

export function constructMapOfPromptsByRule(
	llmPrompts: Map<string, EJPromptTemplateInfo[]>,
): Map<string, EJPromptTemplateInfo[]> {
	const rulePrompts = new Map<string, EJPromptTemplateInfo[]>()

	// First pass - get all LLM responses and group by rule
	for (const [_, promptTemplates] of llmPrompts.entries()) {
		for (const promptTemplate of promptTemplates) {
			if (!promptTemplate.codeBlockRange) {
				continue
			}
			const ruleId = promptTemplate.ruleId || "default"
			if (!rulePrompts.has(ruleId)) {
				rulePrompts.set(ruleId, [])
			}
			rulePrompts.get(ruleId)?.push(promptTemplate)
		}
	}

	return rulePrompts
}

export function structurePromptsMapFromResult(
	llmPrompts: Map<string, any[]> | undefined,
): Map<string, EJPromptTemplateInfo[]> {
	const newLLMPromptMap: Map<string, EJPromptTemplateInfo[]> = new Map<string, EJPromptTemplateInfo[]>()
	if (!llmPrompts) {
		return newLLMPromptMap
	}
	llmPrompts.entries().forEach((entry) => {
		const promptList: EJPromptTemplateInfo[] = entry[1].map((prompt) => {
			const newPrompt: EJPromptTemplateInfo = structurePromptFromResult(prompt)
			return newPrompt
		})

		newLLMPromptMap.set(entry[0], promptList)
	})

	return newLLMPromptMap
}

export function structurePromptFromResult(prompt: any): EJPromptTemplateInfo {
	const newPrompt: EJPromptTemplateInfo = {
		sourceFilePath: prompt.sourceFilePath,
		lineNumber: prompt.lineNumber,
		promptText: prompt.promptText,
		processedPromptText: prompt.processedPromptText,
		targetName: prompt.targetName,
		targetType: prompt.targetType,
		codeBlockRange: {
			start: {
				line: prompt.codeBlockRange._start._line,
				character: prompt.codeBlockRange._start._character,
			},
			end: {
				line: prompt.codeBlockRange._end._line,
				character: prompt.codeBlockRange._end._character,
			},
		},
		ruleName: prompt.ruleName,
		ruleId: prompt.ruleId,
		resultIndex: prompt.resultIndex,
		detailIndex: prompt.detailIndex,
	}
	return newPrompt
}

export async function checkoutBranch(): Promise<boolean> {
	const hasUncommittedChanges = await callCommand(GIT_CHECK_COMMIT_CHANGES_COMMAND)
	if (hasUncommittedChanges) {
		return false
	}

	await callCommand(GIT_CHECKOUT_COMMAND)

	//Introduce aritifical delay to ensure file updates are picked up
	await new Promise((resolve) => setTimeout(resolve, 100))
	return true
}
