import React from "react"
import CodebaseSearchResultsDisplay from "@/components/chat/CodebaseSearchResultsDisplay"
import { ClineMessage } from "@roo-code/types"

/**
 * Props for CodebaseSearchResultMessage component
 */
export interface CodebaseSearchResultMessageProps {
	message: ClineMessage
}

interface CodebaseSearchResult {
	content: {
		query: string
		results: Array<{
			filePath: string
			score: number
			startLine: number
			endLine: number
			codeChunk: string
		}>
	}
}

/**
 * Component for displaying codebase search results
 */
export const CodebaseSearchResultMessage: React.FC<CodebaseSearchResultMessageProps> = ({ message }) => {
	let parsed: CodebaseSearchResult | null = null

	try {
		if (message.text) {
			parsed = JSON.parse(message.text)
		}
	} catch (error) {
		console.error("Failed to parse codebaseSearch content:", error)
	}

	if (parsed && !parsed?.content) {
		console.error("Invalid codebaseSearch content structure:", parsed.content)
		return <div>Error displaying search results.</div>
	}

	const { results = [] } = parsed?.content || {}

	return <CodebaseSearchResultsDisplay results={results} />
}

export default CodebaseSearchResultMessage

