import { memo } from "react"
import { useTranslation } from "react-i18next"
import { ErrorWarning } from "./ErrorWarning"

interface ServiceDisruptionWarningProps {
	retryAttempt?: number
	retryCountdown?: number
	messageKey?: string
}

/**
 * Component to display a warning when Bob services are experiencing disruption
 * Shows retry information if available
 */
export const ServiceDisruptionWarning = memo(
	({ retryAttempt, retryCountdown, messageKey }: ServiceDisruptionWarningProps) => {
		const { t } = useTranslation("ibm")

		const userMessage = messageKey
			? t(`apiRequest.serviceDisruption.${retryAttempt ? "messageRetry" : "messages"}.${messageKey}`)
			: t("apiRequest.serviceDisruption.baseMessage")

		const description = (
			<>
				{userMessage}
				{retryAttempt !== undefined && (
					<div className="mt-2">
						<div>{t("apiRequest.serviceDisruption.retryAttempt", { attempt: retryAttempt })}</div>
						{retryCountdown !== undefined &&
							retryCountdown > 0 &&
							` ${t("apiRequest.serviceDisruption.retryCountdown", { seconds: retryCountdown })}`}
						{retryCountdown !== undefined &&
							retryCountdown === 0 &&
							` ${t("apiRequest.serviceDisruption.retryingNow")}`}
					</div>
				)}
			</>
		)

		return <ErrorWarning title={t("apiRequest.serviceDisruption.retryMessage")} description={description} />
	},
)

export default ServiceDisruptionWarning

