import React from "react"
import { useTranslation } from "react-i18next"
import { ClineMessage } from "@roo-code/types"
import FileOperation from "../common/FileOperation"

interface ListCodeDefinitionNamesToolProps {
	message: ClineMessage
	isExpanded: boolean
	onToggleExpand: () => void
	tool: {
		tool: string
		path?: string
		content?: string
		isOutsideWorkspace?: boolean
	}
}

/**
 * Component for displaying code definition names
 */
export const ListCodeDefinitionNamesTool: React.FC<ListCodeDefinitionNamesToolProps> = ({
	message,
	tool,
	isExpanded,
	onToggleExpand,
}) => {
	const { t } = useTranslation()

	const title =
		message.type === "ask"
			? tool.isOutsideWorkspace
				? t("chat:directoryOperations.wantsToViewDefinitionsOutsideWorkspace")
				: t("chat:directoryOperations.wantsToViewDefinitions")
			: tool.isOutsideWorkspace
				? t("chat:directoryOperations.didViewDefinitionsOutsideWorkspace")
				: t("chat:directoryOperations.didViewDefinitions")

	return (
		<FileOperation
			message={message}
			icon="file-code"
			title={title}
			path={tool.path || ""}
			content={tool.content}
			language="markdown"
			isExpanded={isExpanded}
			onToggleExpand={onToggleExpand}
			isOutsideWorkspace={tool.isOutsideWorkspace}
		/>
	)
}

export default ListCodeDefinitionNamesTool

