import * as React from "react"
import { ControlledChatResponseObject, sendChatResponse } from "../../../sendChatResponse"
import { memo } from "react"
import StepContainer from "../../../common/StepContainer"
import StepButton from "../../../common/StepButton"
import { useAppTranslation } from "@/i18n/TranslationContext"

const AnalyzeArchitectureStep: React.FC<{ config: any }> = ({ config }) => {
	const { t } = useAppTranslation()
	const [stepCompleted, setStepCompleted] = React.useState<boolean>(
		config.props?.["analyzeArchitecture.isCompleted"] || false,
	)

	const handleProceed = () => {
		const responseObject: ControlledChatResponseObject = {
			flowId: config.flowId,
			stepId: config.stepId,
			message: "Ready to analyze architecture",
			data: {
				isCompleted: true,
			},
		}
		sendChatResponse(responseObject)
		setStepCompleted(true)
	}

	return (
		<>
			<h3>{t("ibm:javaModernization.analyzeArchitecture.title")}</h3>
			<p>{t("ibm:javaModernization.analyzeArchitecture.subTitle")}</p>
			<StepContainer>
				<StepButton disabled={stepCompleted} onClick={handleProceed}>
					{t("ibm:javaModernization.proceed")}
				</StepButton>
			</StepContainer>
		</>
	)
}

export default memo(AnalyzeArchitectureStep)

