import React from "react"
import { CheckCircle2, Circle } from "lucide-react"
import { useAppTranslation } from "@/i18n/TranslationContext"
import { _StepId } from "./types"

interface ModernizationProgressProps {
	config: { flowId: string; stepId: string } | undefined
}

const JavaModernizationProgress: React.FC<ModernizationProgressProps> = ({ config }) => {
	const { t } = useAppTranslation()

	const planSteps = [
		{
			planId: "analyze",
			stepIds: [_StepId.ANALYZE_PROJECT, _StepId.SELECT_MODERNIZATION_TYPE],
			label: t("ibm:javaModernization.analyze"),
		},
		{
			planId: "upgrade",
			stepIds: [
				_StepId.RUN_RECIPES,
				_StepId.UPGRADE_JAVA,
				_StepId.ANALYZE_AMA,
				_StepId.RUN_LIBERTY_RECIPES,
				_StepId.ANALYZE_ARCH,
				_StepId.SETUP_PROJECT,
			], // _StepId.RUN_LIBERTY_MOD,
			label: t("ibm:javaModernization.upgrade"),
		},
		{
			planId: "validate",
			stepIds: [_StepId.RUN_VALIDATION, _StepId.DEPLOY_APPLICATION, _StepId.E2E_VALIDATION],
			label: t("ibm:javaModernization.validate"),
		},
	]

	const currentStepPlanIndex = planSteps.findIndex((planStep) => {
		if (config?.stepId && planStep.stepIds?.includes(config.stepId as _StepId)) {
			return true
		}
		return false
	})

	return (
		<div className="mb-2">
			<div className="text-[0.9rem] font-semibold mb-3 mt-3 text-[var(--vscode-foreground)] text-center">
				{t("ibm:javaModernization.plan.title")}
			</div>
			<div className="flex items-center justify-between">
				{planSteps.map((planStep, index) => {
					return (
						<StepComponent
							key={planStep.planId}
							label={planStep.label}
							isCompleted={currentStepPlanIndex > index}
							isActive={currentStepPlanIndex === index}
							isLastStep={index === planSteps.length - 1}
						/>
					)
				})}
			</div>
		</div>
	)
}

export default JavaModernizationProgress

const StepComponent: React.FC<{ label: string; isCompleted: boolean; isActive: boolean; isLastStep?: boolean }> = ({
	label,
	isCompleted,
	isActive,
	isLastStep,
}) => {
	return (
		<>
			<div
				className={`flex flex-col items-center relative flex-1 ${
					isCompleted ? "" : ""
				} ${isActive ? "relative z-[1]" : ""}`}>
				<div
					className={`flex items-center justify-center mb-2 ${isActive ? "drop-shadow-[0_0_4px_rgba(59,130,246,0.5)]" : ""}`}>
					{isCompleted ? (
						<CheckCircle2 className="w-4 h-4 text-[var(--vscode-charts-green)] stroke-[2.5] fill-none" />
					) : (
						<Circle
							className={`w-4 h-4 ${
								isActive
									? "text-[#3b82f6] ibm--ai-effect-brightness-pulse"
									: "text-[var(--vscode-descriptionForeground)]"
							}`}
							strokeWidth={isActive ? 2.5 : 1.5}
						/>
					)}
				</div>
				<div
					className={`text-center text-xs ${
						isCompleted
							? "text-[var(--vscode-foreground)] font-semibold"
							: isActive
								? "font-semibold bg-gradient-to-r from-[#3b82f6] to-[#8b5cf6] bg-clip-text text-transparent"
								: "text-[var(--vscode-descriptionForeground)]"
					}`}>
					{label}
				</div>
			</div>
			{!isLastStep && (
				<div
					className={`h-0.5 flex-grow mx-2 mb-6 ${
						isCompleted ? "bg-[var(--vscode-charts-green)]" : "bg-[var(--vscode-panel-border)]"
					}`}></div>
			)}
		</>
	)
}
