import { useAppTranslation } from "@/i18n/TranslationContext"
import { vscode } from "@/utils/vscode"
import { StepLike, StepLikeStatus, SubStepId } from "@roo-code/types"
import { WebviewMessage } from "@roo/WebviewMessage"
import * as React from "react"
import { memo, useEffect, useState } from "react"
import { Trans } from "react-i18next"

import FilePathInput from "../../../common/FilePathInput"
import StepButton from "../../../common/StepButton"
import StepContainer from "../../../common/StepContainer"
import { StepProgressNotifications, StepProgressTodoList } from "../../../common/StepProgressComponents"
import { isStepInProgress } from "../../../common/utils"
import { ControlledChatResponseObject, sendChatResponse } from "../../../sendChatResponse"

const STEP_CONFIGS = {
	default: {
		steps: [
			SubStepId.LIBERTY_MOD_IMPORT,
			SubStepId.LIBERTY_MOD_ADD_SERVER_CFG,
			SubStepId.LIBERTY_MOD_ADD_CONTAINERFILE,
			SubStepId.LIBERTY_MOD_ANALYZE_RECIPES,
		],
		command: "bob-code.executeLibertyAMAAnalysis",
		eventPrefix: "liberty-analysis-",
	},
}

const RunLibertyMod: React.FC<{ config: any }> = ({ config }) => {
	const { t } = useAppTranslation()
	const [zipPath, setZipPath] = useState<string>(config.props?.zipPath || "")
	const [subSteps, setSubSteps] = useState<StepLike[]>([])
	const [isProcessing, setIsProcessing] = useState<boolean>(false)
	const [stepCompleted, setStepCompleted] = useState<boolean>(config.props?.["runLibertyMod.isCompleted"] || false)
	const projectPath = config.props?.projectPath || ""
	const [stepSuccessful, setStepSuccessful] = React.useState<boolean>(false)

	const canProcess = zipPath && !isProcessing && !stepCompleted
	const canProceed = !isProcessing && !stepCompleted && stepSuccessful

	// Handle Liberty modernization results
	const handleLibertyModernizationResult = (message: any) => {
		if (message.commandResult && message.commandResult.subSteps) {
			try {
				const subSteps: StepLike[] = message.commandResult.subSteps

				setSubSteps(subSteps)
				setStepSuccessful(subSteps.every((s) => s.status === StepLikeStatus.SUCCESS))
				setIsProcessing(isStepInProgress(subSteps))
			} catch (e) {
				console.error("Failed to parse Liberty modernization results:", e)
				setIsProcessing(false)
			}
		}
	}

	// Message handler effect
	useEffect(() => {
		const handleMessage = (event: MessageEvent) => {
			const message = event.data

			if (message.type === "commandResult" && message.requestId) {
				if (message.requestId.startsWith(STEP_CONFIGS.default.eventPrefix)) {
					handleLibertyModernizationResult(message)
				}
			}
		}

		window.addEventListener("message", handleMessage)
		return () => {
			window.removeEventListener("message", handleMessage)
		}
	}, [])

	const handleRunLibertyMod = () => {
		if (!zipPath) return

		setIsProcessing(true)
		setSubSteps([])

		const message: WebviewMessage = {
			type: "executeCommand",
			commands: [STEP_CONFIGS.default.command],
			commandArgs: [zipPath, projectPath],
			eventId: `${STEP_CONFIGS.default.eventPrefix}${Date.now()}`,
		}
		vscode.postMessage(message)
	}

	useEffect(() => {
		if (canProceed) {
			const responseObject: ControlledChatResponseObject = {
				flowId: config.flowId,
				stepId: config.stepId,
				message: t("ibm:javaModernization.libertyMod.completed", { zipPath }),
				data: {
					zipPath,
					subSteps: subSteps,
					isCompleted: true,
				},
			}
			sendChatResponse(responseObject)
			setStepCompleted(true)
		}
	}, [subSteps, canProceed, config.flowId, config.stepId, zipPath, t])

	return (
		<>
			<h3>{t("ibm:javaModernization.libertyMod.title")}</h3>
			<p>
				<Trans
					i18nKey="ibm:javaModernization.libertyMod.subTitle"
					components={[
						<a
							className="text-[var(--vscode-textLink-foreground)]"
							key="0"
							href="https://www.ibm.com/docs/en/ear?topic=tools-application-modernization-accelerator"
							target="_blank"
							rel="noopener noreferrer"
						/>,
					]}
				/>
			</p>
			<StepContainer>
				<div className="font-bold mb-1">{t("ibm:javaModernization.libertyMod.zipPath")}</div>
				<FilePathInput
					value={zipPath}
					onValueChange={setZipPath}
					placeholder={t("ibm:javaModernization.libertyMod.zipPathPlaceholder")}
					disabled={isProcessing || stepCompleted}
					suggestionFilter={(v) => v.endsWith(".zip")}
					showBrowseButton={true}
					browseFileFilters={{ "ZIP files": ["zip"] }}
					className="mb-2"
				/>
				<StepButton
					disabled={!canProcess || isProcessing || (stepCompleted && stepSuccessful)}
					onClick={handleRunLibertyMod}
					subSteps={subSteps}>
					{isProcessing
						? t("ibm:javaModernization.libertyMod.analyzeButtonProcessing")
						: t("ibm:javaModernization.libertyMod.analyzeButton")}
				</StepButton>
				<StepProgressTodoList subSteps={subSteps} />
			</StepContainer>
			<StepProgressNotifications subSteps={subSteps} />
		</>
	)
}

export default memo(RunLibertyMod)
