import React, { useMemo } from "react"
import { useExtensionState } from "@src/context/ExtensionStateContext"
import { safeJsonParse } from "@roo/safeJsonParse"
import { findMatchingResourceOrTemplate } from "@src/utils/mcp"
import McpResourceRow from "@/components/mcp/McpResourceRow"
import { McpExecution } from "@/components/chat/McpExecution"
import { ClineMessage } from "@roo-code/types"
import { headerStyle } from "../common/HeaderStyles"

/**
 * Props for McpServerMessage component
 */
export interface McpServerMessageProps {
	message: ClineMessage
}
import { ClineAskUseMcpServer } from "@roo/ExtensionMessage"
import { useTranslation } from "react-i18next"
import { ProgressIndicator } from "@/components/chat/ProgressIndicator"

/**
 * Check if an MCP server is currently responding
 */
function isMcpServerResponding(isLast: boolean, lastModifiedMessage?: ClineMessage): boolean {
	return isLast && lastModifiedMessage?.say === "mcp_server_request_started"
}

/**
 * Component for displaying MCP server messages
 */
export const McpServerMessage: React.FC<McpServerMessageProps> = ({ message }) => {
	const { t } = useTranslation()
	const { mcpServers, alwaysAllowMcp, bobSourcesConfig } = useExtensionState()
	const normalColor = "var(--vscode-foreground)"

	// Check if an MCP server is currently responding
	const mcpServerResponding = useMemo(() => isMcpServerResponding(true, message), [message])

	// Parse the message text to get the MCP server request
	const messageJson = safeJsonParse<any>(message.text, {})

	// Extract the response field if it exists
	const { response, ...mcpServerRequest } = messageJson

	// Create the useMcpServer object with the response field
	const useMcpServer: ClineAskUseMcpServer = {
		...mcpServerRequest,
		response,
	}

	if (!useMcpServer) {
		return null
	}

	const server = mcpServers.find((server) => server.name === useMcpServer.serverName)
	const source = bobSourcesConfig ? bobSourcesConfig.find(source => source.id === useMcpServer.serverName) : undefined;

	// Generate icon and title based on message
	const icon = mcpServerResponding ? (
		<ProgressIndicator mode="thinking" />
	) : (
		<span className="codicon codicon-server" style={{ color: normalColor, marginBottom: "-1.5px" }}></span>
	)

	let label = useMcpServer.type === "use_mcp_tool"
		? t("chat:mcp.wantsToUseTool", { serverName: useMcpServer.serverName })
		: t("chat:mcp.wantsToAccessResource", { serverName: useMcpServer.serverName })

	if (useMcpServer.bobTool) {
		if (useMcpServer.toolName === "use_skill") {
			useMcpServer.bobTool.sourceLabel = t("chat:sources.skills")
		}
		label = t("chat:sources.wantsToUseTool", { sourceLabel: useMcpServer.bobTool.sourceLabel })
	}

	const title = (
		<span key={`title-${message.ts}`} style={{ color: normalColor, fontWeight: "bold" }}>
			{label}
		</span>
	)

	return (
		<>
			<div style={headerStyle}>
				{icon}
				{title}
			</div>
			<div className="w-full bg-vscode-editor-background border border-vscode-border rounded-xs p-2 mt-2">
				{useMcpServer.type === "access_mcp_resource" && (
					<McpResourceRow
						item={{
							// Use the matched resource/template details, with fallbacks
							...(findMatchingResourceOrTemplate(
								useMcpServer.uri || "",
								server?.resources,
								server?.resourceTemplates,
							) || {
								name: "",
								mimeType: "",
								description: "",
							}),
							// Always use the actual URI from the request
							uri: useMcpServer.uri || "",
						}}
					/>
				)}
				{useMcpServer.type === "use_mcp_tool" && (
					<McpExecution
						executionId={message.ts.toString()}
						text={useMcpServer.arguments !== "{}" ? useMcpServer.arguments : undefined}
						serverName={useMcpServer.serverName}
						toolName={useMcpServer.toolName}
						isArguments={true}
						server={server}
						source={source}
						useMcpServer={useMcpServer}
						alwaysAllowMcp={alwaysAllowMcp}
					/>
				)}
			</div>
		</>
	)
}

export default McpServerMessage

