import React from "react"
import { useTranslation } from "react-i18next"
import { VSCodeBadge } from "@vscode/webview-ui-toolkit/react"
import ToolIcon from "../common/ToolIcon"
import { ClineMessage } from "@roo-code/types"
import { headerStyle } from "../common/HeaderStyles"

interface RunSlashCommandToolProps {
	message: ClineMessage
	isExpanded: boolean
	onToggleExpand: () => void
	tool: {
		tool: string
		command?: string
		args?: string
		description?: string
		source?: string
	}
}

/**
 * Component for displaying slash command execution
 */
export const RunSlashCommandTool: React.FC<RunSlashCommandToolProps> = ({
	message,
	tool,
	isExpanded,
	onToggleExpand,
}) => {
	const { t } = useTranslation()

	return (
		<>
			<div style={headerStyle}>
				<ToolIcon name="play" />
				<span style={{ fontWeight: "bold" }}>
					{message.type === "ask" ? t("chat:slashCommand.wantsToRun") : t("chat:slashCommand.didRun")}
				</span>
			</div>
			<div
				style={{
					marginTop: "4px",
					backgroundColor: "var(--vscode-editor-background)",
					border: "1px solid var(--vscode-editorGroup-border)",
					borderRadius: "4px",
					overflow: "hidden",
					cursor: "pointer",
				}}
				onClick={onToggleExpand}>
				<div
					style={{
						display: "flex",
						alignItems: "center",
						justifyContent: "space-between",
						padding: "10px 12px",
					}}>
					<div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
						<span style={{ fontWeight: "500", fontSize: "var(--vscode-font-size)" }}>/{tool.command}</span>
						{tool.source && (
							<VSCodeBadge style={{ fontSize: "calc(var(--vscode-font-size) - 2px)" }}>
								{tool.source}
							</VSCodeBadge>
						)}
					</div>
					<span className={`codicon codicon-chevron-${isExpanded ? "up" : "down"}`}></span>
				</div>
				{isExpanded && (tool.args || tool.description) && (
					<div
						style={{
							padding: "12px 16px",
							borderTop: "1px solid var(--vscode-editorGroup-border)",
							display: "flex",
							flexDirection: "column",
							gap: "8px",
						}}>
						{tool.args && (
							<div>
								<span style={{ fontWeight: "500" }}>Arguments: </span>
								<span style={{ color: "var(--vscode-descriptionForeground)" }}>{tool.args}</span>
							</div>
						)}
						{tool.description && (
							<div style={{ color: "var(--vscode-descriptionForeground)" }}>{tool.description}</div>
						)}
					</div>
				)}
			</div>
		</>
	)
}

export default RunSlashCommandTool

