import React from "react"
import { useTranslation } from "react-i18next"
import { ClineMessage } from "@roo-code/types"
import FileOperation from "../common/FileOperation"

interface ListFilesTopLevelToolProps {
	message: ClineMessage
	isExpanded: boolean
	onToggleExpand: () => void
	tool: {
		tool: string
		path?: string
		content?: string
		isOutsideWorkspace?: boolean
	}
}

/**
 * Component for displaying top-level file listings
 */
export const ListFilesTopLevelTool: React.FC<ListFilesTopLevelToolProps> = ({
	message,
	tool,
	isExpanded,
	onToggleExpand,
}) => {
	const { t } = useTranslation()

	const title =
		message.type === "ask"
			? tool.isOutsideWorkspace
				? t("chat:directoryOperations.wantsToViewTopLevelOutsideWorkspace")
				: t("chat:directoryOperations.wantsToViewTopLevel")
			: tool.isOutsideWorkspace
				? t("chat:directoryOperations.didViewTopLevelOutsideWorkspace")
				: t("chat:directoryOperations.didViewTopLevel")

	return (
		<FileOperation
			message={message}
			icon="folder-opened"
			title={title}
			path={tool.path || ""}
			content={tool.content}
			language="shell-session"
			isExpanded={isExpanded}
			onToggleExpand={onToggleExpand}
			isOutsideWorkspace={tool.isOutsideWorkspace}
		/>
	)
}

export default ListFilesTopLevelTool

