import { cn } from "@/lib/utils"
import { useEffect, useMemo, useRef, useState } from "react"

import { feedbackBackgroundColor } from "../chatRow/say/UserFeedbackMessage"
import CollapsedView from "./CollapsedView"
import { ExpandedView } from "./ExpandedView"
import "./todoListAnimation.css"
import { Todo, TodoStatus } from "./types"

interface TodoListDisplayOptions {
	initiallyCollapsed?: boolean
}

interface TodoListDisplayProps {
	todos: Todo[]
	options?: TodoListDisplayOptions
	className?: string
}

const debounceTimeMs = 500

export default function TodoListDisplay({ todos, options, className }: TodoListDisplayProps) {
	const [isCollapsed, setIsCollapsed] = useState(options?.initiallyCollapsed ?? true)
	// State to hold todos with debouncing
	const [stableTodos, setStableTodos] = useState<Todo[]>([])

	// Debounce timer ref
	const debounceTimerRef = useRef<NodeJS.Timeout | null>(null)

	// Update stable todos when prop todos change, with debouncing
	// the todos gets rebuilt time and time again so we need to wait until the list has settled
	useEffect(() => {
		// Clear any existing timer
		if (debounceTimerRef.current) {
			clearTimeout(debounceTimerRef.current)
		}
		// Set a new timer to update the state after a delay
		debounceTimerRef.current = setTimeout(() => {
			if (Array.isArray(todos)) {
				setStableTodos(todos)
			}
		}, debounceTimeMs)

		// Cleanup on unmount
		return () => {
			if (debounceTimerRef.current) {
				clearTimeout(debounceTimerRef.current)
			}
		}
	}, [todos])

	// Calculate important metrics
	const totalCount = useMemo(() => {
		if (!Array.isArray(stableTodos) || stableTodos.length === 0) return 0
		return stableTodos.length
	}, [stableTodos])

	const completedCount = useMemo(() => {
		if (!Array.isArray(stableTodos) || stableTodos.length === 0) return 0
		return stableTodos.filter((todo) => todo.status === TodoStatus.COMPLETED).length
	}, [stableTodos])

	const allCompleted = useMemo(() => {
		return completedCount === totalCount && totalCount > 0
	}, [completedCount, totalCount])

	// Find the current focused todo with its metadata
	const currentFocusedTodo = useMemo(() => {
		if (!Array.isArray(stableTodos) || stableTodos.length === 0) {
			return {
				todo: undefined,
				index: -1,
				isFirst: false,
				isLast: false,
			}
		}

		// First try to find an in-progress todo
		const inProgressIdx = stableTodos.findIndex((todo) => todo.status === TodoStatus.IN_PROGRESS)
		if (inProgressIdx !== -1) {
			return {
				todo: stableTodos[inProgressIdx],
				index: inProgressIdx,
				isFirst: inProgressIdx === 0,
				isLast: inProgressIdx === stableTodos.length - 1,
			}
		}

		// Otherwise find the first pending todo
		const pendingIdx = stableTodos.findIndex((todo) => todo.status === TodoStatus.NOT_STARTED)
		if (pendingIdx !== -1) {
			return {
				todo: stableTodos[pendingIdx],
				index: pendingIdx,
				isFirst: pendingIdx === 0,
				isLast: pendingIdx === stableTodos.length - 1,
			}
		}

		// If all todos are completed, return undefined
		return {
			todo: undefined,
			index: -1,
			isFirst: false,
			isLast: false,
		}
	}, [stableTodos])

	// Toggle collapsed state
	const toggleCollapsed = () => setIsCollapsed((prev) => !prev)

	// Early return if no todos - placed in render section after all hooks
	if (!Array.isArray(stableTodos) || stableTodos.length === 0) {
		return null
	}

	// Determine container class based on collapsed state
	const containerClass = isCollapsed ? "todo-list-collapsed" : "todo-list-expanded"

	return (
		<div
			className={cn(
				"rounded-[5px] relative mx-3 mb-2 pl-0 bg-[var(--vscode-editor-background,transparent)] text-[12px] shadow-[0_2px_4px_0_rgba(0,0,0,0.25)]",
				className,
			)}
			style={{ backgroundColor: isCollapsed && currentFocusedTodo.todo ? feedbackBackgroundColor : "" }}>
			<div className={`todo-list-container todo-list-content ${containerClass}`}>
				{isCollapsed ? (
					<CollapsedView
						allCompleted={allCompleted}
						currentFocusedTodo={currentFocusedTodo}
						completedCount={completedCount}
						totalCount={totalCount}
						onToggle={toggleCollapsed}
					/>
				) : (
					<div className="expanded-content">
						<ExpandedView
							todos={stableTodos}
							completedCount={completedCount}
							totalCount={totalCount}
							currentFocusedTodo={currentFocusedTodo}
							onToggle={toggleCollapsed}
						/>
					</div>
				)}
			</div>
		</div>
	)
}

