import { useAppTranslation } from "@/i18n/TranslationContext"
import { ProgressNotification } from "@/ibm/components/common/progressNotification/ProgressNotification"
import Select from "@/ibm/components/common/select/Select"
import { logger } from "@/ibm/utils/logger"
import { vscode } from "@/utils/vscode"
import { BACKEND_FRAMEWORKS, FRONTEND_DESIGN_SYSTEMS, FRONTEND_FRAMEWORKS } from "@roo-code/types"
import { WebviewMessage } from "@roo/WebviewMessage"
import * as React from "react"
import { memo } from "react"

import FilePathInput from "../../../common/FilePathInput"
import StepButton from "../../../common/StepButton"
import StepContainer from "../../../common/StepContainer"
import { ControlledChatResponseObject, sendChatResponse } from "../../../sendChatResponse"
import MermaidDiagram, { MermaidErrorBlock } from "../Mermaid"

const devLogger = logger.child({ ctx: "SetupProjectStep" })

const SetupProjectStep: React.FC<{ config: any }> = ({ config }) => {
	const { t } = useAppTranslation()
	const [projectPath] = React.useState<string>(config.props?.projectPath || "")
	const [mermaidPath] = React.useState<string>(config.props?.archMermaidPath || "")
	const [modernizationType] = React.useState<string>(config.props?.modernizationType || "")
	const [frontendProjectPath, setFrontendProjectPath] = React.useState<string>(
		config.props?.frontendProjectPath || "",
	)
	const [backendProjectPath, setBackendProjectPath] = React.useState<string>(config.props?.backendProjectPath || "")
	const [frontendFramework, setFrontendFramework] = React.useState<string>(
		config.props?.frontendFramework || FRONTEND_FRAMEWORKS.REACT,
	)
	const [frontendDesignSystem, setFrontendDesignSystem] = React.useState<string>(
		config.props?.frontendDesignSystem || FRONTEND_DESIGN_SYSTEMS.MATERIAL_UI,
	)
	const [backendFramework, setBackendFramework] = React.useState<string>(
		config.props?.backendFramework || BACKEND_FRAMEWORKS.JAKARTA_EE,
	)
	const [isSettingUp, setIsSettingUp] = React.useState<boolean>(false)
	const [setupResults, setSetupResults] = React.useState<{
		stdout?: string
		details?: { exitCode: number }
	} | null>(null)
	const [error, setError] = React.useState<string>("")
	const [stepCompleted, setStepCompleted] = React.useState<boolean>(
		config.props?.["setupProject.isCompleted"] || false,
	)
	const [mermaidDiagram, setMermaidDiagram] = React.useState<string | undefined>(undefined)
	const colorThemeKind = config.props?.["colorTheme.kind"]

	// Frontend framework options
	const frontendFrameworkOptions = [
		{
			label: t("ibm:javaModernization.setupProject.frontendFrameworkOptions.react"),
			id: FRONTEND_FRAMEWORKS.REACT,
		},
		{ label: t("ibm:javaModernization.setupProject.frontendFrameworkOptions.vue"), id: FRONTEND_FRAMEWORKS.VUE },
		{
			label: t("ibm:javaModernization.setupProject.frontendFrameworkOptions.angular"),
			id: FRONTEND_FRAMEWORKS.ANGULAR,
		},
	]

	// Frontend design system options
	const frontendDesignSystemOptions = [
		{
			label: t("ibm:javaModernization.setupProject.frontendDesignSystemOptions.materialUI"),
			id: FRONTEND_DESIGN_SYSTEMS.MATERIAL_UI,
		},
		{
			label: t("ibm:javaModernization.setupProject.frontendDesignSystemOptions.shadcn"),
			id: FRONTEND_DESIGN_SYSTEMS.SHADCN,
		},
		{
			label: t("ibm:javaModernization.setupProject.frontendDesignSystemOptions.carbon"),
			id: FRONTEND_DESIGN_SYSTEMS.CARBON,
		},
	]

	// Backend framework options
	const backendFrameworkOptions = [
		{
			label: t("ibm:javaModernization.setupProject.backendFrameworkOptions.quarkus"),
			id: BACKEND_FRAMEWORKS.QUARKUS,
		},
		{
			label: t("ibm:javaModernization.setupProject.backendFrameworkOptions.jakartaEE"),
			id: BACKEND_FRAMEWORKS.JAKARTA_EE,
		},
	]

	// Compute button states
	const canSetup =
		frontendProjectPath &&
		backendProjectPath &&
		frontendFramework &&
		frontendDesignSystem &&
		backendFramework &&
		!isSettingUp &&
		!stepCompleted

	const handleMermaid = (message: any) => {
		if (!message.commandResult) {
			return
		}

		if (message.requestId.startsWith("mermaid-diagram-")) {
			try {
				setMermaidDiagram(message.commandResult)
			} catch (e) {
				devLogger.error("Failed to read mermaid diagram:", e)
			}
		}
	}

	// Function to handle setup project results from the extension
	React.useEffect(() => {
		const handleMessage = (event: MessageEvent) => {
			const message = event.data
			if (message.type === "commandResult" && message.requestId) {
				if (message.requestId.startsWith("setup-project-")) {
					// The command result contains the setup output
					if (message.commandResult) {
						// Store the command result directly as an object
						setSetupResults(message.commandResult)
						setIsSettingUp(false)

						// Check for exitCode in the command result
						const exitCode = message.commandResult.details?.exitCode

						// Non-zero exit code indicates failure
						if (exitCode !== undefined && exitCode !== 0) {
							const errorMessage =
								message.commandResult.stdout || `Setup failed with exit code ${exitCode}`
							setError(errorMessage)
						}
					}
				} else {
					// Handle mermaid diagram messages
					handleMermaid(message)
				}
			}
		}

		// Add event listener for messages from the extension
		window.addEventListener("message", handleMessage)

		// Request the mermaid diagram
		vscode.postMessage({
			type: "executeCommand",
			commands: ["bob-code.readMermaidDiagram"],
			commandArgs: [modernizationType, mermaidPath],
			eventId: `mermaid-diagram-${Date.now()}`,
		})

		// Clean up the event listener when the component unmounts
		return () => {
			window.removeEventListener("message", handleMessage)
		}
	}, [modernizationType, mermaidPath])

	// Send response when setup is complete
	React.useEffect(() => {
		if (setupResults && !stepCompleted && !error) {
			// Setup complete, move to next stage
			const responseObject: ControlledChatResponseObject = {
				flowId: config.flowId,
				stepId: config.stepId,
				message: `Setting up UI modernization project with ${frontendFramework} (${frontendDesignSystem}): ${frontendProjectPath} and ${backendFramework}: ${backendProjectPath}`,
				data: {
					projectPath,
					frontendProjectPath,
					backendProjectPath,
					frontendFramework,
					frontendDesignSystem,
					backendFramework,
					modernizationType,
					setupResults: setupResults.stdout || JSON.stringify(setupResults),
					isCompleted: true,
				},
			}

			sendChatResponse(responseObject)
			setStepCompleted(true)
		}
	}, [
		config.flowId,
		config.stepId,
		setupResults,
		stepCompleted,
		frontendProjectPath,
		backendProjectPath,
		frontendFramework,
		frontendDesignSystem,
		backendFramework,
		error,
		projectPath,
		modernizationType,
	])

	const handleSetupProject = () => {
		if (!frontendProjectPath || !backendProjectPath) return

		setIsSettingUp(true)
		setSetupResults(null)
		setError("")

		try {
			// Call the VSCode command to set up the project
			const message: WebviewMessage = {
				type: "executeCommand",
				commands: ["bob-code.setupProject"],
				commandArgs: [
					projectPath,
					frontendProjectPath,
					backendProjectPath,
					frontendFramework,
					frontendDesignSystem,
					backendFramework,
				],
				eventId: `setup-project-${Date.now()}`,
			}
			vscode.postMessage(message)
		} catch (error) {
			devLogger.error("Error setting up project:", error instanceof Error ? error : new Error(String(error)))
			setError("Error setting up project: " + error)
			setIsSettingUp(false)
		}
	}

	const SetupProgress: React.FC<{
		isSettingUp: boolean
		isCompleted: boolean
		setupResults: {
			stdout?: string
			details?: { exitCode: number }
		} | null
		frontendProjectPath: string
		backendProjectPath: string
		error: string
	}> = ({ isSettingUp, isCompleted, setupResults, frontendProjectPath, backendProjectPath, error }) => {
		const { t } = useAppTranslation()

		if (!isSettingUp && setupResults === null && !isCompleted && !error) {
			return null
		}

		if (error) {
			return <ProgressNotification mode="failure" message={error} />
		}

		if (setupResults || isCompleted) {
			// Check exitCode directly from the object
			const exitCode = setupResults?.details?.exitCode

			// Non-zero exit code indicates failure
			if (exitCode !== undefined && exitCode !== 0) {
				return (
					<ProgressNotification
						mode="failure"
						message={t("ibm:javaModernization.setupProject.setupFailed", {
							frontendProjectPath: frontendProjectPath,
							backendProjectPath: backendProjectPath,
							defaultValue: `Setup failed for frontend project: ${frontendProjectPath} and backend project: ${backendProjectPath}`,
						})}
					/>
				)
			}

			return <ProgressNotification mode="completed" message={t("ibm:javaModernization.setupProject.completed")} />
		}

		if (isSettingUp) {
			return <ProgressNotification mode="building" message={t("ibm:javaModernization.setupProject.inProgress")} />
		}

		return null
	}

	return (
		<>
			<h3>{t("ibm:javaModernization.mermaid.title")}</h3>
			{mermaidDiagram ? (
				<>
					<p>{t("ibm:javaModernization.mermaid.subTitle")}</p>
					<MermaidDiagram code={mermaidDiagram} colorThemeKind={colorThemeKind} />
				</>
			) : (
				<MermaidErrorBlock error={t("ibm:javaModernization.mermaid.error.fileMissing")} />
			)}
			<h3>{t("ibm:javaModernization.setupProject.title")}</h3>
			<p>{t("ibm:javaModernization.setupProject.subTitle")}</p>
			<StepContainer>
				<div className="flex gap-2 mb-2">
					<div className="w-full">
						<div className="mb-2 text-sm">{t("ibm:javaModernization.setupProject.frontendFramework")}</div>
						<Select
							className="w-full"
							options={frontendFrameworkOptions}
							selectedValue={frontendFramework}
							disabled={isSettingUp || stepCompleted}
							onChange={(value: string) => {
								setFrontendFramework(value)
							}}
						/>
					</div>
					<div className="w-full">
						<div className="mb-2 text-sm">
							{t("ibm:javaModernization.setupProject.frontendDesignSystem")}
						</div>
						<Select
							className="w-full"
							options={frontendDesignSystemOptions}
							selectedValue={frontendDesignSystem}
							disabled={isSettingUp || stepCompleted}
							onChange={(value: string) => {
								setFrontendDesignSystem(value)
							}}
						/>
					</div>
				</div>
				<div className="flex gap-2 mb-2">
					<div className="w-full">
						<div className="mb-2 text-sm">{t("ibm:javaModernization.setupProject.backendFramework")}</div>
						<Select
							className="w-full"
							options={backendFrameworkOptions}
							selectedValue={backendFramework}
							disabled={isSettingUp || stepCompleted}
							onChange={(value: string) => {
								setBackendFramework(value)
							}}
						/>
					</div>
				</div>

				<div className="mb-2">
					<div className="font-bold mb-1">{t("ibm:javaModernization.setupProject.frontendProject")}</div>
					<FilePathInput
						value={frontendProjectPath}
						onValueChange={setFrontendProjectPath}
						placeholder={t("ibm:javaModernization.setupProject.frontendProjectPlaceholder")}
						disabled={isSettingUp || stepCompleted}
						showBrowseButton={true}
						browseMode="folder"
						browseTitle="Select frontend project folder"
						className="mb-0"
					/>
				</div>

				<div className="mb-4">
					<div className="font-bold mb-1">{t("ibm:javaModernization.setupProject.backendProject")}</div>
					<FilePathInput
						value={backendProjectPath}
						onValueChange={setBackendProjectPath}
						placeholder={t("ibm:javaModernization.setupProject.backendProjectPlaceholder")}
						disabled={isSettingUp || stepCompleted}
						showBrowseButton={true}
						browseMode="folder"
						browseTitle="Select backend project folder"
						className="mb-0"
					/>
				</div>

				<StepButton disabled={!canSetup || isSettingUp || stepCompleted} onClick={handleSetupProject}>
					{isSettingUp
						? t("ibm:javaModernization.setupProject.setupButtonProcessing")
						: t("ibm:javaModernization.setupProject.setupButton")}
				</StepButton>
			</StepContainer>
			<SetupProgress
				isSettingUp={isSettingUp}
				isCompleted={stepCompleted}
				setupResults={setupResults}
				frontendProjectPath={frontendProjectPath}
				backendProjectPath={backendProjectPath}
				error={error}
			/>
		</>
	)
}

export default memo(SetupProjectStep)

