import React from "react"
import CodeAccordian from "@/components/common/CodeAccordian"
import { BatchFileGroup } from "./BatchFileGroup"
import ToolIcon from "./ToolIcon"
import { ClineMessage } from "@roo-code/types"

interface FileOperationProps {
	message: ClineMessage
	isExpanded: boolean
	onToggleExpand: () => void
	icon: string
	title: string | React.ReactNode
	path: string
	content?: string
	language?: string
	isProtected?: boolean
	isOutsideWorkspace?: boolean
	reason?: string
	onJumpToFile?: () => void
	batchFiles?: Array<{
		path: string
		changeCount: number
		key: string
		content: string
		diffs?: Array<{
			content: string
			startLine?: number
		}>
	}>
	batchPermissionFiles?: Array<{
		path: string
		lineSnippet?: string
		isOutsideWorkspace?: boolean
		key: string
		content?: string
	}>
	onBatchFileResponse?: (response: { [key: string]: boolean }) => void
}

/**
 * Common component for file operations that can be used across different tools
 */
export const FileOperation: React.FC<FileOperationProps> = ({
	message,
	icon,
	title,
	path,
	content,
	language = "diff",
	isExpanded,
	onToggleExpand,
	isProtected,
	reason,
	batchFiles,
	batchPermissionFiles,
	onBatchFileResponse,
	onJumpToFile,
}) => {
	const style = {
		backgroundColor: "var(--vscode-editorWidget-background)",
	}
	let Content = (
		<CodeAccordian
			path={path}
			code={content}
			language={language}
			progressStatus={message.progressStatus}
			isLoading={message.partial}
			isExpanded={isExpanded}
			onToggleExpand={onToggleExpand}
			style={{
				...style,
				borderRadius: "0 0 4px 4px",
			}}
			onJumpToFile={onJumpToFile}
			reason={reason}
		/>
	)

	// Handle batch files (either diffs or permissions)
	if (
		(batchFiles && Array.isArray(batchFiles) && batchFiles.length > 0) ||
		(batchPermissionFiles && Array.isArray(batchPermissionFiles) && batchPermissionFiles.length > 0)
	) {
		// Convert batch files to the format expected by BatchFileGroup
		const groupFiles = []

		// Add diff files if they exist
		if (batchFiles?.length) {
			groupFiles.push(
				...batchFiles.map((file) => ({
					...file,
					type: "diff" as const,
				})),
			)
		}

		// Add permission files if they exist
		if (batchPermissionFiles?.length) {
			groupFiles.push(
				...batchPermissionFiles.map((file) => ({
					...file,
					type: "permission" as const,
				})),
			)
		}

		Content = (
			<BatchFileGroup
				files={groupFiles}
				onPermissionResponse={onBatchFileResponse}
				ts={message.ts}
				style={style}
			/>
		)
	}

	return (
		<div className="bg-vscode-editor-background rounded border border-vscode-input-border">
			<div className="flex items-center gap-2.5 wrap-anywhere border-b border-vscode-input-border p-1.5">
				<ToolIcon name={icon} isProtected={isProtected} />
				<span className="font-bold">{title}</span>
			</div>
			{Content}
		</div>
	)
}

export default FileOperation

