import { memo, useRef, useState, useMemo } from "react"
import { useTranslation } from "react-i18next"
import { FoldVertical, X, Coins, Globe } from "lucide-react"
import prettyBytes from "pretty-bytes"

import type { ClineMessage } from "@roo-code/types"

import { getModelMaxOutputTokens } from "@roo/api"

import { formatLargeNumber } from "@src/utils/format"
import { cn } from "@src/lib/utils"
import { StandardTooltip, Button } from "@src/components/ui"
import { useExtensionState } from "@src/context/ExtensionStateContext"
import { useSelectedModel } from "@/components/ui/hooks/useSelectedModel"
import { Mention } from "@/components/chat/Mention"
import { ContextWindowProgress } from "@/components/chat/ContextWindowProgress"
import { TaskActions } from "@/components/chat/TaskActions"
import Thumbnails from "@/components/common/Thumbnails"
import { vscode } from "@/utils/vscode"
import { VSCodeBadge } from "@vscode/webview-ui-toolkit/react"
import { BudgetTooltipContent } from "../../common/budgetIndicator/BudgetIndicator"
import TodoListDisplay from "../todoListDisplay"

export interface TaskHeaderProps {
	task: ClineMessage
	tokensIn: number
	tokensOut: number
	cacheWrites?: number
	cacheReads?: number
	totalCost: number
	contextTokens: number
	buttonsDisabled: boolean
	handleCondenseContext: (taskId: string) => void
	todos?: any[]
}

const TaskHeader = ({
	task,
	tokensIn,
	tokensOut,
	cacheWrites,
	cacheReads,
	totalCost,
	contextTokens,
	buttonsDisabled,
	handleCondenseContext,
	todos,
}: TaskHeaderProps) => {
	const { t } = useTranslation()
	const { apiConfiguration, currentTaskItem, clineMessages, isBrowserSessionActive } = useExtensionState()
	const { id: modelId, info: model } = useSelectedModel(apiConfiguration)
	const [isTaskExpanded, setIsTaskExpanded] = useState(false)

	const textContainerRef = useRef<HTMLDivElement>(null)
	const textRef = useRef<HTMLDivElement>(null)
	const contextWindow = model?.contextWindow || 1
	// Detect if this task had any browser session activity
	const browserSessionStartIndex = useMemo(() => {
		const msgs = clineMessages || []
		for (let i = 0; i < msgs.length; i++) {
			const m = msgs[i] as any
			if (m?.ask === "browser_action_launch") return i
		}
		return -1
	}, [clineMessages])

	const showBrowserGlobe = browserSessionStartIndex !== -1 || !!isBrowserSessionActive


	const condenseButton = (
		<StandardTooltip content={t("chat:task.condenseContext")}>
			<button
				disabled={buttonsDisabled}
				onClick={() => currentTaskItem && handleCondenseContext(currentTaskItem.id)}
				className="shrink-0 min-h-[20px] min-w-[20px] p-[2px] cursor-pointer disabled:cursor-not-allowed opacity-85 hover:opacity-100 bg-transparent border-none rounded-md">
				<FoldVertical size={16} />
			</button>
		</StandardTooltip>
	)

	// const hasTodos = todos && Array.isArray(todos) && todos.length > 0

	return (
		<div className="pt-2 pb-0 px-0.1">
			<div
				className={cn(
					"px-3 pt-2.5 pb-2 flex flex-col gap-1.5 relative z-1 cursor-pointer",
					"hover:bg-vscode-input-background/10",
					"text-vscode-foreground/80 hover:text-vscode-foreground",
					"rounded-t-2xl border-b-0",
					"[box-shadow:0px_-5px_7px_-1px_rgba(59,130,246,0.25)]",
				)}
				onClick={(e) => {
					// Don't expand if clicking on buttons or interactive elements
					if (
						e.target instanceof Element &&
						(e.target.closest("button") ||
							e.target.closest('[role="button"]') ||
							e.target.closest(".share-button") ||
							e.target.closest("[data-radix-popper-content-wrapper]") ||
							e.target.closest("img") ||
							e.target.tagName === "IMG")
					) {
						return
					}

					// Don't expand/collapse if user is selecting text
					const selection = window.getSelection()
					if (selection && selection.toString().length > 0) {
						return
					}

					setIsTaskExpanded(!isTaskExpanded)
				}}>
				<div className="flex justify-between items-center gap-0">
					<div className="flex items-center select-none grow min-w-0">
						<div className="whitespace-nowrap overflow-hidden text-ellipsis grow min-w-0 mr-2 font-bold">
							{isTaskExpanded && <span className="font-bold">{t("chat:task.title")}</span>}
							{!isTaskExpanded && <Mention text={task.text} />}
						</div>
						{!isTaskExpanded && contextWindow > 0 && (
							<div className="flex items-center gap-1.5 text-xs">
								<StandardTooltip
									content={
										<div className="space-y-1">
											<div>
												{t("chat:tokenProgress.tokensUsed", {
													used: formatLargeNumber(contextTokens || 0),
													total: formatLargeNumber(contextWindow),
												})}
											</div>
											{(() => {
												const maxTokens = model
													? getModelMaxOutputTokens({
															modelId,
															model,
															settings: apiConfiguration,
														})
													: 0
												const reservedForOutput = maxTokens || 0
												const availableSpace =
													contextWindow - (contextTokens || 0) - reservedForOutput
	
												return (
													<>
														{reservedForOutput > 0 && (
															<div>
																{t("chat:tokenProgress.reservedForResponse", {
																	amount: formatLargeNumber(reservedForOutput),
																})}
															</div>
														)}
														{availableSpace > 0 && (
															<div>
																{t("chat:tokenProgress.availableSpace", {
																	amount: formatLargeNumber(availableSpace),
																})}
															</div>
														)}
													</>
												)
											})()}
										</div>
									}
									side="top"
									sideOffset={8}>
									<span className="mr-1 whitespace-nowrap">
										{formatLargeNumber(contextTokens || 0, 0)} /{" "}
										{formatLargeNumber(contextWindow, 0)}
									</span>
								</StandardTooltip>
								{!!totalCost && (
									<StandardTooltip content={<BudgetTooltipContent />} side="top" sideOffset={8}>
										<VSCodeBadge
											className={`flex justify-end items-center cursor-pointer vscode-badge-custom ibm--budget--nutral`}>
											<Coins className="inline-block size-[1em] mr-1" />
											{totalCost.toFixed(2)}
										</VSCodeBadge>
									</StandardTooltip>
								)}
							</div>
						)}
						{showBrowserGlobe && (
							<div className="flex items-center gap-1 ml-2" onClick={(e) => e.stopPropagation()}>
								<StandardTooltip content={t("chat:browser.session")}>
									<Button
										variant="ghost"
										size="sm"
										aria-label={t("chat:browser.session")}
										onClick={() => vscode.postMessage({ type: "openBrowserSessionPanel" } as any)}
										className={cn(
											"relative h-5 w-5 p-0",
											"text-vscode-foreground opacity-85",
											"hover:opacity-100 hover:bg-[rgba(255,255,255,0.03)]",
											"focus:outline-none focus-visible:ring-1 focus-visible:ring-vscode-focusBorder",
										)}>
										<Globe
											className="w-4 h-4"
											style={{
												color: isBrowserSessionActive
													? "#4ade80"
													: "var(--vscode-descriptionForeground)",
											}}
										/>
									</Button>
								</StandardTooltip>
								{isBrowserSessionActive && (
									<span
										className="text-sm font-medium"
										style={{ color: "var(--vscode-testing-iconPassed)" }}>
										{t("ibm:browser.active")}
									</span>
								)}
							</div>
						)}
						<div className="flex items-center shrink-0 ml-1" onClick={(e) => e.stopPropagation()}>
							<StandardTooltip content={t("ibm:chat.closeTask")}>
								<button
									onClick={() => vscode.postMessage({ type: "clearTask" })}
									className="shrink-0 min-h-[20px] min-w-[20px] p-[2px] cursor-pointer opacity-85 hover:opacity-100 bg-transparent border-none rounded-md">
									<X size={16} />
								</button>
							</StandardTooltip>
						</div>
					</div>
				</div>
				{/* Expanded state: Show task text and images */}
				{isTaskExpanded && (
					<>
						<div
							ref={textContainerRef}
							className="text-vscode-font-size overflow-y-auto break-words break-anywhere relative">
							<div
								ref={textRef}
								className="overflow-auto max-h-80 whitespace-pre-wrap break-words break-anywhere cursor-text"
								style={{
									display: "-webkit-box",
									WebkitLineClamp: "unset",
									WebkitBoxOrient: "vertical",
								}}>
								<Mention text={task.text} />
							</div>
						</div>
						{task.images && task.images.length > 0 && <Thumbnails images={task.images} />}

						<div className="border-t border-b border-vscode-panel-border/50 py-4 mt-2 mb-1">
							<table className="w-full">
								<tbody>
									{contextWindow > 0 && (
										<tr>
											<th
												className="font-bold text-left align-top w-1 whitespace-nowrap pl-1 pr-3 h-[24px]"
												data-testid="context-window-label">
												{t("chat:task.contextWindow")}
											</th>
											<td className="align-top">
												<div className={`max-w-80 -mt-0.5 flex flex-nowrap gap-1`}>
													<ContextWindowProgress
														contextWindow={contextWindow}
														contextTokens={contextTokens || 0}
														maxTokens={
															model
																? getModelMaxOutputTokens({
																		modelId,
																		model,
																		settings: apiConfiguration,
																	})
																: undefined
														}
													/>
													{condenseButton}
												</div>
											</td>
										</tr>
									)}
									<tr>
										<th className="font-bold text-left align-top w-1 whitespace-nowrap pl-1 pr-3 h-[24px]">
											{t("ibm:taskId")}
										</th>
										<td className="align-top">
											<div className="flex items-center gap-1 flex-wrap">
												{` ${currentTaskItem?.id}`}
											</div>
										</td>
									</tr>
									<tr>
										<th className="font-bold text-left align-top w-1 whitespace-nowrap pl-1 pr-3 h-[24px]">
											{t("chat:task.tokens")}
										</th>
										<td className="align-top">
											<div className="flex items-center gap-1 flex-wrap">
												{typeof tokensIn === "number" && tokensIn > 0 && (
													<span>↑ {formatLargeNumber(tokensIn)}</span>
												)}
												{typeof tokensOut === "number" && tokensOut > 0 && (
													<span>↓ {formatLargeNumber(tokensOut)}</span>
												)}
											</div>
										</td>
									</tr>

									{((typeof cacheReads === "number" && cacheReads > 0) ||
										(typeof cacheWrites === "number" && cacheWrites > 0)) && (
										<tr>
											<th className="font-bold text-left align-top w-1 whitespace-nowrap pl-1 pr-3 h-[24px]">
												{t("chat:task.cache")}
											</th>
											<td className="align-top">
												<div className="flex items-center gap-1 flex-wrap">
													{typeof cacheWrites === "number" && cacheWrites > 0 && (
														<span>↑ {formatLargeNumber(cacheWrites)}</span>
													)}
													{typeof cacheReads === "number" && cacheReads > 0 && (
														<span>↓ {formatLargeNumber(cacheReads)}</span>
													)}
												</div>
											</td>
										</tr>
									)}

									{!!totalCost && (
										<tr>
											<th className="font-bold text-left align-top w-1 whitespace-nowrap pl-1 pr-3 h-[24px]">
												{t("chat:task.apiCost")}
											</th>
											<td className="align-top">
												<Coins className="inline-block size-[1em] mr-1" />
												<span>{totalCost?.toFixed(2)}</span>
											</td>
										</tr>
									)}

									{/* Size display */}
									{!!currentTaskItem?.size && currentTaskItem.size > 0 && (
										<tr>
											<th className="font-bold text-left align-top w-1 whitespace-nowrap pl-1 pr-2  h-[20px]">
												{t("chat:task.size")}
											</th>
											<td className="align-top">{prettyBytes(currentTaskItem.size)}</td>
										</tr>
									)}
								</tbody>
							</table>
						</div>

						{/* Footer with task management buttons */}
						<div onClick={(e) => e.stopPropagation()}>
							<TaskActions item={currentTaskItem} buttonsDisabled={buttonsDisabled} />
						</div>
					</>
				)}
			</div>
			<TodoListDisplay todos={todos ?? (task as any)?.tool?.todos ?? []} />
		</div>
	)
}

export default memo(TaskHeader)

