import { useAppTranslation } from "@src/i18n/TranslationContext"
import { BobIcon } from "./BobIcon"
import { BookOpen } from "lucide-react"
import { useBuildDocLink } from "@/utils/docLinks"
import { VSCodeLink } from "@vscode/webview-ui-toolkit/react"

interface WelcomeHeaderProps {
	/**
	 * Optional custom subtitle text. If not provided, uses the default translation key.
	 */
	subTitle?: string
	/**
	 * Optional className for additional styling of the container
	 */
	className?: string
}

/**
 * Reusable welcome header component displaying Bob's icon, name, and subtitle.
 * Used in chat view and other welcome screens.
 */
export const WelcomeHeader = ({ subTitle, className = "" }: WelcomeHeaderProps) => {
	const buildDocLink = useBuildDocLink()
	const { t } = useAppTranslation()

	return (
		<div className={`flex flex-col items-center bob-welcome-container ${className}`}>
			<BobIcon />
			<div className="text-center px-1.5">
				<h1 className="text-2xl font-medium">
					{t("ibm:welcome.title")}
					<span className="text-[#2764FE]">{t("ibm:welcome.name")}</span>
					{t("ibm:welcome.nameSuffix")}
				</h1>
				<p className="text-vscode-descriptionForeground mt-2 font-medium max-w-[350px] whitespace-pre-line">
					{subTitle ?? t("ibm:welcome.subTitle")}
				</p>
				<VSCodeLink href={buildDocLink()}>
					<div className="flex items-center gap-2 text-vscode-descriptionForeground hover:text-vscode-textLink-foreground hover:no-underline ml-2 bg-accent py-1 px-2 rounded">
						<BookOpen className="w-4 h-4" />
						<span>{t("ibm:welcome.documentation")}</span>
					</div>
				</VSCodeLink>
			</div>
		</div>
	)
}

