import * as React from "react"
import { Button } from "@/components/ui"
import { callCommand } from "@/ibm/utils/callCommand"
import { memo } from "react"
import { sendChatResponse } from "../../../sendChatResponse"
import { useAppTranslation } from "@/i18n/TranslationContext"
import {
	EJ_RUN_AUTOMATED_FIXES_COMMAND,
	EJ_SET_AUTOMATION_FLAG_COMMAND,
	GIT_ADD_RECENT_MODIFIED_COMMAND,
	GIT_COMMIT_COMMAND,
} from "../ejCommands"
import { ProgressNotification } from "@/ibm/components/common/progressNotification/ProgressNotification"

const ApplyAutomatedFixesStep: React.FC<{ config: any }> = ({ config }) => {
	// console.log('==> ApplyAutomatedFixesStep', config)
	const { t } = useAppTranslation()
	const [fixesApplied, setFixesApplied] = React.useState(config.props.isCompleted)
	const [isApplying, setIsApplying] = React.useState(config.props.isCompleted)
	const actionHasBeenTriggered = React.useRef(config.props.isCompleted)
	const handleApplyAutomatedFixes = async () => {
		if (actionHasBeenTriggered.current) {
			return
		}
		actionHasBeenTriggered.current = true
		if (config.props.isCompleted || fixesApplied) {
			setFixesApplied(true)
			return
		}

		setIsApplying(true)

		await callCommand(EJ_SET_AUTOMATION_FLAG_COMMAND, true)

		await callCommand(EJ_RUN_AUTOMATED_FIXES_COMMAND)

		if (config.props.fullyAutomatedMode) {
			await callCommand(GIT_ADD_RECENT_MODIFIED_COMMAND)
			await callCommand(GIT_COMMIT_COMMAND, `fix: apply automated fixes`)
		}

		setFixesApplied(true)
		setIsApplying(false)

		if (config.props.fullyAutomatedMode === false) {
			await callCommand(EJ_SET_AUTOMATION_FLAG_COMMAND, false)
		}

		sendChatResponse({
			flowId: config.flowId,
			stepId: config.stepId,
			message: t("ibm:javaUpgrade.applyAutomatedFixes.appliedMessage"),
			data: {
				isCompleted: true,
			},
		})
	}

	React.useEffect(() => {
		// If fully automated mode is enabled, automatically apply fixes
		if (config.props.fullyAutomatedMode) {
			handleApplyAutomatedFixes()
		}
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [])

	let progress = null
	let buttonText = ""
	if (fixesApplied) {
		buttonText = t("ibm:javaUpgrade.applyAutomatedFixes.buttonApplied")
		progress = <ProgressNotification mode="completed" message={t("ibm:javaUpgrade.applyAutomatedFixes.appliedMessage")} />
	} else if (isApplying) {
		buttonText = t("ibm:javaUpgrade.applyAutomatedFixes.buttonRunning")
		progress = <ProgressNotification mode="building" message={t("ibm:javaUpgrade.applyAutomatedFixes.applyingMessage")} />
	} else {
		buttonText = t("ibm:javaUpgrade.applyAutomatedFixes.buttonApply")
		progress = <ProgressNotification mode="loading" message={t("ibm:javaUpgrade.applyAutomatedFixes.awaitingConfirmation")} />
	}
	return (
		<div>
			<h3>{t("ibm:javaUpgrade.applyAutomatedFixes.title")}</h3>
			{config.props.fullyAutomatedMode && (
				<p>
					{t("ibm:javaUpgrade.applyAutomatedFixes.descriptionAuto")}
				</p>
			)}
			{!config.props.fullyAutomatedMode && (
				<div>
					<p>
						{t("ibm:javaUpgrade.applyAutomatedFixes.description")}
					</p>
					<div className="ibm--java-chat__content">
						<Button
							className="ibm--java-chat__button"
							disabled={actionHasBeenTriggered.current}
							onClick={handleApplyAutomatedFixes}>
							{buttonText}
						</Button>
					</div>
				</div>
			)}
			{progress}
		</div>
	)
}

export default memo(ApplyAutomatedFixesStep)
