import React, { useState } from "react"
import { useTranslation } from "react-i18next"
import { VSCodeButton } from "@vscode/webview-ui-toolkit/react"
import CodeBlock from "@/components/common/CodeBlock"
import { ClineMessage } from "@roo-code/types"
import { useCopyToClipboard } from "@/utils/clipboard"

/**
 * Props for DiffErrorMessage component
 */
export interface DiffErrorMessageProps {
	message: ClineMessage
	isDiffErrorExpanded: boolean
	setIsDiffErrorExpanded: (value: boolean) => void
}

/**
 * Component for displaying diff error messages
 */
export const DiffErrorMessage: React.FC<DiffErrorMessageProps> = ({
	message,
	isDiffErrorExpanded,
	setIsDiffErrorExpanded,
}) => {
	const [showCopySuccess, setShowCopySuccess] = useState(false)
	const { copyWithFeedback } = useCopyToClipboard()
	const { t } = useTranslation()

	return (
		<div className="mt-0 overflow-hidden mb-2 rounded-b">
			<div
				style={{
					borderBottom: isDiffErrorExpanded ? "1px solid var(--vscode-editorGroup-border)" : "none",
					fontWeight: "normal",
					fontSize: "var(--vscode-font-size)",
					color: "var(--vscode-editor-foreground)",
					display: "flex",
					alignItems: "center",
					justifyContent: "space-between",
					cursor: "pointer",
				}}
				onClick={() => setIsDiffErrorExpanded(!isDiffErrorExpanded)}>
				<div
					style={{
						display: "flex",
						alignItems: "center",
						gap: "10px",
						flexGrow: 1,
					}}>
					<span
						className="codicon codicon-warning"
						style={{
							color: "var(--vscode-editorWarning-foreground)",
							opacity: 0.8,
							fontSize: 16,
							marginBottom: "-1.5px",
						}}></span>
					<span style={{ fontWeight: "bold" }}>{t("chat:diffError.title")}</span>
				</div>
				<div style={{ display: "flex", alignItems: "center" }}>
					<VSCodeButton
						appearance="icon"
						style={{
							padding: "3px",
							height: "24px",
							marginRight: "4px",
							color: "var(--vscode-editor-foreground)",
							display: "flex",
							alignItems: "center",
							justifyContent: "center",
							background: "transparent",
						}}
						onClick={(e) => {
							e.stopPropagation()

							// Call copyWithFeedback and handle the Promise
							copyWithFeedback(message.text || "").then((success) => {
								if (success) {
									// Show checkmark
									setShowCopySuccess(true)

									// Reset after a brief delay
									setTimeout(() => {
										setShowCopySuccess(false)
									}, 1000)
								}
							})
						}}>
						<span className={`codicon codicon-${showCopySuccess ? "check" : "copy"}`}></span>
					</VSCodeButton>
					<span className={`codicon codicon-chevron-${isDiffErrorExpanded ? "up" : "down"}`}></span>
				</div>
			</div>
			{isDiffErrorExpanded && (
				<div
					style={{
						padding: "8px",
						backgroundColor: "var(--vscode-editor-background)",
						borderTop: "none",
					}}>
					<CodeBlock source={message.text || ""} language="xml" />
				</div>
			)}
		</div>
	)
}

export default DiffErrorMessage

