import { memo } from "react"
import AnalyzeApplicationStep from "./steps/analyzeApplicationStep"
import GenerateUpgradePlanStep from "./steps/generateUpgradePlanStep"
import ApplyAssistedFixesStep from "./steps/applyAssistedFixesStep"
import ApplyAutomatedFixesStep from "./steps/applyAutomatedFixesStep"
import CleanupStep from "./steps/cleanupStep"

const JavaUpgradeChat: React.FC<{ config: any }> = ({ config }) => {
	if (!config) {
		return null
	}
	switch (config.stepId) {
		case "analyzeApplication":
			return <AnalyzeApplicationStep config={config} />
		case "generateUpgradePlan":
			return <GenerateUpgradePlanStep config={config} />
		case "applyAutomatedFixes":
			return <ApplyAutomatedFixesStep config={config} />
		case "applyAssistedFixes":
			return <ApplyAssistedFixesStep config={config} />
		case "cleanup":
			return <CleanupStep config={config} />
		default:
			return null
	}
}

export interface Version {
	label: string
	id: string
	value: number
}

export default memo(JavaUpgradeChat)
