import { memo } from "react"
import JavaUpgradeChat from "./controlled-chat-flows/java-upgrade/JavaUpgradeChat"
import JavaModernizationChat from "./controlled-chat-flows/java-modernization/JavaModernizationChat"

const ControlledChat: React.FC<{ message?: any }> = ({ message }) => {
	if (!message || !message.text) {
		return null
	}
	const config = JSON.parse(message.text)

	if (config.flowId === "java-upgrade") {
		return <JavaUpgradeChat config={config} />
	}
	if (config.flowId === "java-modernization") {
		return <JavaModernizationChat config={config} />
	}
	return null
}

export default memo(ControlledChat)
