import React, { useState } from "react"
import { ClineMessage } from "@roo-code/types"
import { VSCodeButton } from "@vscode/webview-ui-toolkit/react"
import CodeBlock from "@/components/common/CodeBlock"
import { useCopyToClipboard } from "@/utils/clipboard"

/**
 * Props for NotificationMessage component
 */
export interface NotificationMessageProps {
	message: ClineMessage
	isExpanded: boolean
	setIsExpanded: (value: boolean) => void
	title: string
	hidePreview?: boolean
	icon: string
	iconColor: string
}

/**
 * Generic component for displaying notification messages (errors, warnings, etc.)
 */
export const NotificationMessage: React.FC<NotificationMessageProps> = ({
	message,
	isExpanded,
	setIsExpanded,
	title,
	hidePreview,
	icon,
	iconColor,
}) => {
	const [showCopySuccess, setShowCopySuccess] = useState(false)
	const { copyWithFeedback } = useCopyToClipboard()

	return (
		<div className="mt-0 overflow-hidden mb-2 rounded-b">
			<div
				className="mb-1"
				style={{
					fontWeight: "normal",
					fontSize: "var(--vscode-font-size)",
					color: "var(--vscode-editor-foreground)",
					display: "flex",
					alignItems: "center",
					justifyContent: "space-between",
					cursor: "pointer",
				}}
				onClick={() => setIsExpanded(!isExpanded)}>
				<div
					style={{
						display: "flex",
						alignItems: "center",
						gap: "10px",
						width: "100%",
						overflow: "hidden",
					}}>
					<span
						className={`codicon codicon-${icon}`}
						style={{
							color: iconColor,
							opacity: 0.8,
							fontSize: 16,
							marginBottom: "-1.5px",
							flexShrink: 0,
						}}></span>
					<span
						style={{
							fontWeight: "bold",
							flexShrink: 0,
						}}>
						{title}:
					</span>
					{hidePreview ? null : (
						<span
							className="truncate"
							style={{
								maxWidth: "70%",
								overflow: "hidden",
								textOverflow: "ellipsis",
								whiteSpace: "nowrap",
							}}>
							{`${message.text}`}
						</span>
					)}
				</div>
				<div style={{ display: "flex", alignItems: "center" }}>
					<VSCodeButton
						appearance="icon"
						style={{
							padding: "3px",
							height: "24px",
							marginRight: "4px",
							color: "var(--vscode-editor-foreground)",
							display: "flex",
							alignItems: "center",
							justifyContent: "center",
							background: "transparent",
						}}
						onClick={(e) => {
							e.stopPropagation()

							// Call copyWithFeedback and handle the Promise
							copyWithFeedback(message.text || "").then((success) => {
								if (success) {
									// Show checkmark
									setShowCopySuccess(true)

									// Reset after a brief delay
									setTimeout(() => {
										setShowCopySuccess(false)
									}, 1000)
								}
							})
						}}>
						<span className={`codicon codicon-${showCopySuccess ? "check" : "copy"}`}></span>
					</VSCodeButton>
					<span className={`codicon codicon-chevron-${isExpanded ? "up" : "down"}`}></span>
				</div>
			</div>
			{isExpanded && (
				<div
					className="rounded"
					style={{
						border: "1px solid var(--vscode-editorGroup-border)",
						padding: "8px",
						backgroundColor: "var(--vscode-editor-background)",
					}}>
					<CodeBlock source={message.text || ""} language="txt" />
				</div>
			)}
		</div>
	)
}

export default NotificationMessage

