import { useState, useEffect, useRef, memo } from 'react'
import MarkdownBlock from "../common/MarkdownBlock"

interface SmoothStreamingMarkdownProps {
	markdown: string
	speed?: number 
}

/**
 * Renders markdown with smooth character-by-character animation.
 */
export const SmoothStreamingMarkdown = memo(({ markdown, speed = 5 }: SmoothStreamingMarkdownProps) => {
	const [displayedText, setDisplayedText] = useState('')
	const bufferRef = useRef(markdown)
	const animationRef = useRef<number | null>(null)
	const lastUpdateRef = useRef(0)
	const displayedLengthRef = useRef(0)

	useEffect(() => {
		bufferRef.current = markdown

		const animate = (timestamp: number) => {
			if (!lastUpdateRef.current) {
				lastUpdateRef.current = timestamp
			}

			const elapsed = timestamp - lastUpdateRef.current
			const buffer = bufferRef.current

			if (elapsed >= speed && displayedLengthRef.current < buffer.length) {
				const charsToAdd = Math.max(1, Math.floor(elapsed / speed))
				const nextLength = Math.min(displayedLengthRef.current + charsToAdd, buffer.length)

				displayedLengthRef.current = nextLength
				setDisplayedText(buffer.slice(0, nextLength))
				lastUpdateRef.current = timestamp
			}

			if (displayedLengthRef.current < buffer.length) {
				animationRef.current = requestAnimationFrame(animate)
			} else {
				animationRef.current = null
			}
		}

		if (displayedLengthRef.current < markdown.length) {
			if (!animationRef.current) {
				lastUpdateRef.current = 0
				animationRef.current = requestAnimationFrame(animate)
			}
		} else if (displayedLengthRef.current > markdown.length) {
			displayedLengthRef.current = markdown.length
			setDisplayedText(markdown)
		}

		return () => {
			if (animationRef.current) {
				cancelAnimationFrame(animationRef.current)
				animationRef.current = null
			}
		}
	}, [markdown, speed])

	return <MarkdownBlock markdown={displayedText} />
})
