import React from "react"
import { useTranslation } from "react-i18next"
import CodeAccordian from "@/components/common/CodeAccordian"
import ToolIcon from "../common/ToolIcon"
import { ClineMessage } from "@roo-code/types"
import { headerStyle } from "../common/HeaderStyles"

interface FetchInstructionsToolProps {
	message: ClineMessage
	isExpanded: boolean
	onToggleExpand: () => void
	tool: {
		tool: string
		content?: string
	}
}

/**
 * Component for displaying fetched instructions
 */
export const FetchInstructionsTool: React.FC<FetchInstructionsToolProps> = ({
	message,
	tool,
	isExpanded,
	onToggleExpand,
}) => {
	const { t } = useTranslation()

	return (
		<>
			<div style={headerStyle}>
				<ToolIcon name="file-code" />
				<span style={{ fontWeight: "bold" }}>{t("chat:instructions.wantsToFetch")}</span>
			</div>
			<CodeAccordian
				code={tool.content}
				language="markdown"
				isLoading={message.partial}
				isExpanded={isExpanded}
				onToggleExpand={onToggleExpand}
			/>
		</>
	)
}

export default FetchInstructionsTool

