import * as React from "react"
import { memo } from "react"
import { sendChatResponse } from "../../../sendChatResponse"
import { EJ_SET_AUTOMATION_FLAG_COMMAND } from "../ejCommands"
import { callCommand } from "@/ibm/utils/callCommand"
import { useAppTranslation } from "@/i18n/TranslationContext"

const CleanupStep: React.FC<{ config: any }> = ({ config }) => {
	console.log("==> ApplyAutomatedFixesStep", config)
	const { t } = useAppTranslation()

	const handleCleanUp = async () => {
		if (config.props.fullyAutomatedMode === true) {
			await callCommand(EJ_SET_AUTOMATION_FLAG_COMMAND, false)
		}

		sendChatResponse({
			flowId: config.flowId,
			stepId: config.stepId,
			message: t("ibm:javaUpgrade.cleanup.finishedMessage"),
			data: {
				isCompleted: true,
			},
		})
	}

	React.useEffect(() => {
		handleCleanUp()
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [])

	return null
}

export default memo(CleanupStep)
