import { memo, useMemo, useEffect, useState } from "react"
import { useTranslation } from "react-i18next"
import { ExternalLink, TriangleAlert } from "lucide-react"
import { VSCodeButton } from "@vscode/webview-ui-toolkit/react"
import { useExtensionState } from "@/context/ExtensionStateContext"
import { vscode } from "@/utils/vscode"
import { getTrialStatus } from "@roo/IBM/userProfileHelpers"
import { getActiveProfile } from "@/ibm/utils/userProfile"
import { logger } from "@/ibm/utils/logger"
import { StructuredApiError } from "@roo/apiError"
import { ENTERPRISE_PLAN_ID } from "@/ibm/constants"

/**
 * Component to display a warning for users with a plan when the budget is exceeded.
 * Handles different states:
 * - Trial expired: Shows message that trial has expired with upgrade prompt
 * - Budget exceeded (trial): Shows budget exceeded message with days remaining
 * - Budget exceeded (paid): Shows budget exceeded message with plan info
 *
 * The component force fetches the latest profile data on mount to ensure accurate budget information.
 */

type BudgetExceededWarningPublicProps = {
	errorData?: StructuredApiError
}

export const BudgetExceededWarningPublic = memo(({ errorData }: BudgetExceededWarningPublicProps) => {
	const { t } = useTranslation()
	const { featureFlags, activeProfile } = useExtensionState()
	const [isLoading, setIsLoading] = useState(true)

	const isAccountSuspended = errorData?.message.includes("instance is suspended")

	// Force fetch the latest active profile data on mount
	useEffect(() => {
		const fetchLatestProfile = async () => {
			setIsLoading(true)
			try {
				await getActiveProfile(true) // Force refresh from API
			} catch (_error) {
				logger.error("Failed to fetch latest profile")
			} finally {
				setIsLoading(false)
			}
		}

		fetchLatestProfile()
	}, [])

	const manageSubscriptionUrl = useMemo(() => {
		return featureFlags?.["manage-subscription-url"]
	}, [featureFlags])

	const isEnterprisePlan = useMemo(() => {
		return activeProfile?.plan === ENTERPRISE_PLAN_ID
	}, [activeProfile?.plan])

	// Calculate trial status using shared helper
	const {
		isTrial,
		daysRemaining,
		isExpired: isTrialExpired,
	} = useMemo(() => {
		return getTrialStatus(activeProfile)
	}, [activeProfile])

	// Get budget limit from profile
	const budgetLimit = useMemo(() => {
		return activeProfile?.budget_limit
	}, [activeProfile])

	// Determine title and description based on state
	const { title, description } = useMemo(() => {
		if (isTrial && (isAccountSuspended || isTrialExpired)) {
			// Trial has expired
			return {
				title: t("ibm:apiRequest.budgetExceededPublic.trialTitle"),
				description: t("ibm:apiRequest.budgetExceededPublic.trialExpiredDescription"),
			}
		} else if (isTrial && daysRemaining !== null) {
			// Trial active but budget exceeded
			return {
				title: t("ibm:apiRequest.budgetExceededPublic.title"),
				description: t("ibm:apiRequest.budgetExceededPublic.trialDescription"),
			}
		} else if (isAccountSuspended) {
			// Paid plan budget isAccountSuspended
			return {
				title: t("ibm:apiRequest.budgetExceededPublic.planSuspendedTitle"),
				description: t("ibm:apiRequest.budgetExceededPublic.planSuspendedDescription", {
					maxBudget: budgetLimit?.toFixed(2) ?? "0.00",
				}),
			}
		} else {
			// Paid plan budget exceeded
			return {
				title: t("ibm:apiRequest.budgetExceededPublic.title"),
				description: t(
					isEnterprisePlan
						? "ibm:apiRequest.budgetExceededPublic.enterpriseDescription"
						: "ibm:apiRequest.budgetExceededPublic.description",
					{
						maxBudget: budgetLimit?.toFixed(2) ?? "0.00",
					},
				),
			}
		}
	}, [isTrial, isTrialExpired, isAccountSuspended, daysRemaining, budgetLimit, isEnterprisePlan, t])

	// Show loading state while fetching profile
	if (isLoading) {
		return (
			<div className="flex flex-col gap-2 w-full">
				<div className="flex gap-[5px] items-center w-full">
					<div className="flex gap-1 items-center justify-center p-[3px] shrink-0">
						<TriangleAlert size={16} />
					</div>
					<div className="flex-1 text-[13px] font-medium leading-normal">
						{t("ibm:apiRequest.budgetExceededPublic.loading")}
					</div>
				</div>
			</div>
		)
	}

	return (
		<div className="flex flex-col gap-2 w-full">
			{/* Warning Icon and Title - gap-[5px] per Figma design */}
			<div className="flex gap-[5px] items-center w-full">
				<div className="flex gap-1 items-center justify-center p-[3px] shrink-0">
					<TriangleAlert size={16} />
				</div>
				<div className="flex-1 text-[13px] font-medium leading-normal">{title}</div>
			</div>

			{/* Description */}
			<div className="flex items-start w-full">
				<div className="flex-1 text-[13px] font-medium leading-normal">{description}</div>
			</div>

			{/* Manage Subscription Button */}
			{manageSubscriptionUrl && !isEnterprisePlan && (
				<div className="flex items-start w-full">
					<div className="flex flex-1 items-center justify-center">
						<VSCodeButton
							onClick={() => vscode.postMessage({ type: "openExternal", url: manageSubscriptionUrl })}
							className="w-full">
							<div className="flex flex-1 gap-1 items-center justify-center">
								<span className="text-[13px] font-medium text-center">
									{t("ibmSettings:general.manageSubscription")}
								</span>
								<div className="flex flex-col items-center justify-center size-5 shrink-0">
									<ExternalLink className="w-4 h-4" />
								</div>
							</div>
						</VSCodeButton>
					</div>
				</div>
			)}
		</div>
	)
})

export default BudgetExceededWarningPublic

