import React, { useState, useEffect, useRef } from "react"
import { vscode } from "@src/utils/vscode"
import { useExtensionState } from "@src/context/ExtensionStateContext"
import UpdateTodoListToolBlock from "../../updateTodoListToolBlock/UpdateTodoListToolBlock"
import { TodoItem } from "../../updateTodoListToolBlock/types"

interface UpdateTodoListToolProps {
	tool: {
		tool: string
		todos: TodoItem[]
		content?: string
		isFirstCreation?: boolean
		isTodoContentModified?: boolean
	}
	editable?: boolean
	userEdited?: boolean
}

const holdOffPeriod = 600 // 0.6s matching TodoListDisplay

/**
 * Component for handling todo list updates with stable todos concept
 */
export const UpdateTodoListTool: React.FC<UpdateTodoListToolProps> = ({ tool, editable, userEdited }) => {
	// Get auto approval settings
	const { autoApprovalEnabled, alwaysAllowUpdateTodoList } = useExtensionState()

	// State to hold todos with debouncing
	const [stableTodos, setStableTodos] = useState<TodoItem[] | undefined>()

	const hasUserEdits = useRef(false)

	// Debounce timer ref
	const debounceTimerRef = useRef<NodeJS.Timeout | null>(null)

	// Extract values from tool
	const todos = tool.todos
	const isFirstCreation = tool.isFirstCreation === true
	// Use this to flag if the todo list changed since it was created
	const todosChanged = tool.isTodoContentModified === true
	const content = tool.content

	// Update stable todos when prop todos change, with debouncing
	useEffect(() => {
		// If the user has edited the todo ignore todos as they are out of sync
		if (hasUserEdits.current) {
			return
		}
		// Clear any existing timer
		if (debounceTimerRef.current) {
			clearTimeout(debounceTimerRef.current)
		}

		// Set a new timer to update the state after a delay
		debounceTimerRef.current = setTimeout(() => {
			if (Array.isArray(todos)) {
				setStableTodos(todos)
			}
		}, holdOffPeriod)

		// Cleanup on unmount
		return () => {
			if (debounceTimerRef.current) {
				clearTimeout(debounceTimerRef.current)
			}
		}
	}, [todos])

	// Return null if auto approval for todos is enabled AND it's not the first creation
	if (
		typeof stableTodos === "undefined" ||
		(autoApprovalEnabled && alwaysAllowUpdateTodoList && !isFirstCreation && !todosChanged)
	) {
		return null
	}

	return (
		<UpdateTodoListToolBlock
			todos={stableTodos}
			content={content}
			onChange={(updatedTodos) => {
				hasUserEdits.current = true
				setStableTodos(updatedTodos)
				if (typeof vscode !== "undefined" && vscode?.postMessage) {
					vscode.postMessage({ type: "updateTodoList", payload: { todos: updatedTodos } })
				}
			}}
			editable={editable}
			userEdited={userEdited}
			isFirstCreation={isFirstCreation}
		/>
	)
}

export default UpdateTodoListTool

