import React from "react"
import { useTranslation } from "react-i18next"
import { vscode } from "@src/utils/vscode"
import { getLanguageFromPath } from "@src/utils/getLanguageFromPath"
import { ClineMessage } from "@roo-code/types"
import FileOperation from "../common/FileOperation"

interface NewFileCreatedToolProps {
	message: ClineMessage
	isExpanded: boolean
	onToggleExpand: () => void
	tool: {
		tool: string
		path?: string
		content?: string
		isProtected?: boolean
		isOutsideWorkspace?: boolean
	}
}

/**
 * Component for handling new file creation
 */
export const NewFileCreatedTool: React.FC<NewFileCreatedToolProps> = ({
	message,
	tool,
	isExpanded,
	onToggleExpand,
}) => {
	const { t } = useTranslation()

	// Determine the title based on protection status
	const title = tool.isProtected
		? t("chat:fileOperations.wantsToEditProtected")
		: t("chat:fileOperations.wantsToCreate")

	return (
		<FileOperation
			message={message}
			icon="new-file"
			title={title}
			path={tool.path || ""}
			content={tool.content}
			language={getLanguageFromPath(tool.path || "") || "log"}
			isExpanded={isExpanded}
			onToggleExpand={onToggleExpand}
			isProtected={tool.isProtected}
			isOutsideWorkspace={tool.isOutsideWorkspace}
			onJumpToFile={() => vscode.postMessage({ type: "openFile", text: "./" + tool.path })}
		/>
	)
}

export default NewFileCreatedTool

