import { AppServerType, JavaModernizationSettings, TelemetryEventName } from "@roo-code/types"
import { vscode } from "@src/utils/vscode"
import { t } from "i18next"
import * as React from "react"
import { memo } from "react"
import { SettingToggleRow } from "../../../common/SettingToggleRow"
import StepButton from "../../../common/StepButton"
import StepContainer from "../../../common/StepContainer"
import { ControlledChatResponseObject, sendChatResponse } from "../../../sendChatResponse"
import { FLOW_ID } from "../../java-modernization/types"

const DEFAULT_TARGET_JAVA_VERSION = 25

type TileProps = {
	title: string
	description: string
	isSelected: boolean
	disabled: boolean
	onClick: () => void
}

function onModernizationTypeSelect(config: any, selectedOption: string, settings: JavaModernizationSettings) {
	const responseObject: ControlledChatResponseObject = {
		flowId: config.flowId,
		stepId: config.stepId,
		message: `Selected modernization type: ${selectedOption}`,
		data: {
			modernizationType: selectedOption,
			settings: settings,
			isCompleted: true,
		},
	}
	vscode.postMessage({
		type: "executeCommand",
		commands: ["bob-code.captureTelemetryEvent"],
		commandArgs: [
			TelemetryEventName.JM_MODERNIZATION_TYPE_SELECTED,
			{ flowID: FLOW_ID, actionType: selectedOption },
		],
	})
	sendChatResponse(responseObject)
}

function getReplatformingDescription(sourceAppServerType: AppServerType) {
	switch (sourceAppServerType) {
		case AppServerType.LIBERTY:
			return t("ibm:javaModernization.selectType.alreadyAtAppServerType", {
				appServerType: sourceAppServerType,
			})
		case AppServerType.NONE:
			return t("ibm:javaModernization.selectType.appNoneServerType")
		default:
			return t("ibm:javaModernization.selectType.libertyReplatforminDescription")
	}
}

const Tile: React.FC<TileProps> = ({ title, description, onClick, isSelected, disabled }) => {
	return (
		<div
			className={`border-2 border-solid rounded p-4 cursor-pointer transition-all duration-200 ease-in-out flex items-center
				${isSelected ? "border-[var(--vscode-button-background)]" : "border-[var(--vscode-input-border)]"}
				${disabled ? "opacity-50 pointer-events-none cursor-not-allowed" : "cursor-pointer"}
				hover:border-[var(--vscode-list-hoverForeground)] hover:bg-[var(--vscode-list-hoverBackground)]`}
			onClick={onClick}>
			<div className="flex items-center justify-center mr-4">
				<input
					type="radio"
					checked={isSelected}
					readOnly
					className="h-4 w-4 cursor-pointer"
					style={{
						accentColor: "var(--vscode-button-background)",
					}}
				/>
			</div>
			<div>
				<h4 className="mt-0 mb-2">{title}</h4>
				<p className="m-0">{description}</p>
			</div>
		</div>
	)
}

const SelectModernizationTypeStep: React.FC<{ config: any }> = ({ config }) => {
	const [selectedOption, setSelectedOption] = React.useState<string>(config.props?.["modernizationType"] || "")
	const [stepCompleted, setStepCompleted] = React.useState<boolean>(
		config.props?.["selectModernizationType.isCompleted"] || false,
	)
	const [sourceJavaVersion] = React.useState<string>(config.props?.envInfo["source-java"])
	const [sourceAppServerType] = React.useState<AppServerType>(config.props?.envInfo["source-app-server"])
	const [frameworks] = React.useState<string[]>(config.props?.envInfo?.frameworks || [])

	const [libertyReplatformingEnabled] = React.useState<boolean>(
		config.props?.featureFlags["libertyReplatformingEnabled"] || false,
	)
	const [javaUpgradeEnabled] = React.useState<boolean>(config.props?.featureFlags["javaUpgradeEnabled"] || false)
	const [javaUIModernizationEnabled] = React.useState<boolean>(
		config.props?.featureFlags["javaUIModernizationEnabled"] || false,
	)
	const libertyReplatformingEligible = React.useMemo(() => {
		return !["liberty", "none"].includes(sourceAppServerType)
	}, [sourceAppServerType])

	const javaUpgradeEligible = React.useMemo(() => {
		return parseInt(sourceJavaVersion) < DEFAULT_TARGET_JAVA_VERSION
	}, [sourceJavaVersion])

	const strutsUpgradeEligible = React.useMemo(() => {
		return frameworks.some((framework) => framework.toLowerCase().includes("struts"))
	}, [frameworks])
	const jsfUpgradeEligible = React.useMemo(() => {
		return frameworks.some((framework) => framework.toLowerCase().includes("jsf"))
	}, [frameworks])
	const [settings, setSettings] = React.useState<JavaModernizationSettings>(
		config.props?.settings || { enableGitFlow: true },
	)

	React.useEffect(() => {
		// automatically select the option if it is the only one enabled
		const enabledOptions = [
			libertyReplatformingEnabled && libertyReplatformingEligible && "liberty-replatforming",
			javaUpgradeEnabled && javaUpgradeEligible && "java-upgrade",
			javaUIModernizationEnabled && (strutsUpgradeEligible || jsfUpgradeEligible) && "java-ui-modernization",
		].filter(Boolean)

		if (enabledOptions.length === 1) {
			setSelectedOption(enabledOptions[0] as string)
		}
	}, [
		libertyReplatformingEnabled,
		javaUpgradeEnabled,
		libertyReplatformingEligible,
		javaUpgradeEligible,
		strutsUpgradeEligible,
		jsfUpgradeEligible,
		javaUIModernizationEnabled,
	])

	return (
		<>
			<h3>{t("ibm:javaModernization.selectType.title")}</h3>
			<p>{t("ibm:javaModernization.selectType.subTitle")}</p>
			<StepContainer>
				<div className="flex flex-col gap-2 mb-2 w-full">
					{libertyReplatformingEnabled && (
						<Tile
							title={t("ibm:javaModernization.selectType.libertyReplatforming")}
							description={getReplatformingDescription(sourceAppServerType)}
							onClick={() => setSelectedOption("liberty-replatforming")}
							isSelected={selectedOption === "liberty-replatforming"}
							disabled={libertyReplatformingEligible ? stepCompleted : true}
						/>
					)}
					{javaUpgradeEnabled && (
						<Tile
							title={t("ibm:javaModernization.selectType.javaUpgrade")}
							description={
								javaUpgradeEligible
									? t("ibm:javaModernization.selectType.javaUpgradeDescription")
									: t("ibm:javaModernization.selectType.alreadyAtJavaVersion", {
											version: sourceJavaVersion,
										})
							}
							onClick={() => setSelectedOption("java-upgrade")}
							isSelected={selectedOption === "java-upgrade"}
							disabled={javaUpgradeEligible ? stepCompleted : true}
						/>
					)}
					{javaUIModernizationEnabled && (
						<Tile
							title={t("ibm:javaModernization.selectType.javaUIModernization")}
							description={t("ibm:javaModernization.selectType.javaUIModernizationDescription")}
							onClick={() => setSelectedOption("java-ui-modernization")}
							isSelected={selectedOption === "java-ui-modernization"}
							disabled={strutsUpgradeEligible || jsfUpgradeEligible ? stepCompleted : true}
						/>
					)}
					{!libertyReplatformingEnabled && !javaUpgradeEnabled && !javaUIModernizationEnabled && (
						<div> {t("ibm:javaModernization.selectType.noModernizationAvailable")} </div>
					)}
				</div>

				<div className="p-1">
					<SettingToggleRow
						title={t(`ibm:javaModernization.selectType.settings.enableGitFlow.label`)}
						description={t(`ibm:javaModernization.selectType.settings.enableGitFlow.description`)}
						disabled={stepCompleted}
						checked={settings.enableGitFlow}
						onChange={(checked: boolean) => {
							setSettings({ ...settings, enableGitFlow: checked })
						}}
					/>
				</div>

				<StepButton
					disabled={!selectedOption || stepCompleted}
					onClick={() => {
						onModernizationTypeSelect(config, selectedOption, settings)
						setStepCompleted(true)
					}}>
					{t("ibm:javaModernization.proceed")}
				</StepButton>
			</StepContainer>
		</>
	)
}

export default memo(SelectModernizationTypeStep)
