import { useAppTranslation } from "@/i18n/TranslationContext"
import Select from "@/ibm/components/common/select/Select"
import { vscode } from "@/utils/vscode"
import { StepLike, SubStepId } from "@roo-code/types"
import { WebviewMessage } from "@roo/WebviewMessage"
import { CheckIcon, TriangleAlert } from "lucide-react"
import * as React from "react"
import { memo } from "react"

import { SettingToggleRow } from "../../../common/SettingToggleRow"
import StepButton from "../../../common/StepButton"
import StepContainer from "../../../common/StepContainer"
import { StepProgressNotifications, StepProgressTodoList } from "../../../common/StepProgressComponents"
import { isStepInProgress } from "../../../common/utils"
import { ControlledChatResponseObject, sendChatResponse } from "../../../sendChatResponse"
import { JavaEEVersion, JavaInstallation } from "../types"

// Define the Version interface
interface Version {
	label: string
	id: string
	value: number
	jakartaEEVersion?: string
}

// Define the UpgradePath interface based on the JSON structure
interface UpgradePath {
	path: string
	jee: boolean
	description: string
	riskAssessment: string
	keyTechnicalChallenges: string
}

interface JavaModRecommendations {
	upgradePaths: UpgradePath[]
}

// Function to shorten path for display
// Replace "home section" as "~"
const shortenPath = (path?: string): string => {
	if (!path) return ""

	// Handle Unix-style paths (macOS and Linux)
	if (path.startsWith("/Users/") || path.startsWith("/home/")) {
		const parts = path.split("/")
		if (parts.length >= 3) {
			// parts[0] is empty because the path starts with /
			// parts[1] is "Users" or "home"
			// parts[2] is the username
			const prefix = "/" + parts[1] + "/" + parts[2]
			return path.replace(prefix, "~")
		}
	}

	return path
}

const RecommendationSkeleton = () => (
	<>
		<div className="flex flex-col flex-1 overflow-hidden w-full gap-1 mt-2">
			<div className="h-[11px] w-full bg-vscode-input-foreground opacity-20 rounded animate-pulse" />
			<div className="h-[11px] w-full bg-vscode-input-foreground opacity-20 rounded animate-pulse" />
			<div className="h-[11px] w-[50%] bg-vscode-input-foreground opacity-20 rounded animate-pulse" />
		</div>
		<div className="flex flex-col flex-1 overflow-hidden w-full gap-1 mt-2">
			<div className="h-[11px] w-full bg-vscode-input-foreground opacity-20 rounded animate-pulse" />
			<div className="h-[11px] w-full bg-vscode-input-foreground opacity-20 rounded animate-pulse" />
			<div className="h-[11px] w-[50%] bg-vscode-input-foreground opacity-20 rounded animate-pulse" />
		</div>
	</>
)

const RecommendationSection: React.FC<{ selectedUpgradePath: UpgradePath }> = ({ selectedUpgradePath }) => {
	const { t } = useAppTranslation()

	return (
		<div className="flex gap-2 mb-2 text-sm">
			<div className="w-full">
				<div className="mb-2">
					<span>{selectedUpgradePath.description}</span>
				</div>
				{selectedUpgradePath.keyTechnicalChallenges && (
					<div className="mb-2">
						<span className="font-medium">
							{t("ibm:javaModernization.runRecipes.keyTechnicalChallenges")}
						</span>
						<span>{selectedUpgradePath.keyTechnicalChallenges}</span>
					</div>
				)}
			</div>
		</div>
	)
}

const RunRecipesStep: React.FC<{ config: any }> = ({ config }) => {
	const { t } = useAppTranslation()

	const envInfo = config.props.envInfo
	const sourceVersion = envInfo["source-java"]
	const jeeVersion = envInfo["java-ee-version"]
	const enableGitFlow = config.props.settings.enableGitFlow

	const [javaModRecommendations, setJavaModRecommendations] = React.useState<JavaModRecommendations>(
		config.props.javaModRecommendations,
	)
	const [showRecommendationSkeleton, setShowRecommendationSkeleton] = React.useState<boolean>(true)
	const [recommendationTimedOut, setRecommendationTimedOut] = React.useState<boolean>(false)
	const [selectedUpgradePath, setSelectedUpgradePath] = React.useState<UpgradePath | null>(null)

	const [targetOptions, setTargetOptions] = React.useState<Version[]>([])
	const [targetVersion, setTargetVersion] = React.useState<string>("")
	const [javaInstallationFound, setJavaInstallationFound] = React.useState<{ found: boolean; path?: string }>({
		found: false,
	})

	const [branchName, setBranchName] = React.useState<string>("")
	const [subSteps, setSubSteps] = React.useState<StepLike[]>([])
	// Determine if Jakarta EE should be enabled based on jeeVersion
	const shouldEnableJakartaEE = React.useMemo(() => {
		// If jeeVersion is unknown, default to false as application is not JEE application
		return jeeVersion !== JavaEEVersion.UNKNOWN ? true : false
	}, [jeeVersion])

	const [jakartaEEEnabled, setJakartaEEEnabled] = React.useState<boolean>(
		shouldEnableJakartaEE && (config.props?.["jakartaEE.enabled"] ?? true),
	)
	const [jakartaEEVersion, setJakartaEEVersion] = React.useState<string>(config.props?.["jakartaEE.version"] || "")
	const [stepCompleted, setStepCompleted] = React.useState<boolean>(config.props?.["runRecipes.isCompleted"] || false)
	const [isRunning, setIsRunning] = React.useState<boolean>(false)
	const [recipeResults, setRecipeResults] = React.useState<string>("")

	const TIMEOUT_UPGRADE_PATH: UpgradePath = React.useMemo(
		() => ({
			path: "",
			jee: false,
			description: t("ibm:javaModernization.runRecipes.recommendationsTimedOut"),
			riskAssessment: "",
			keyTechnicalChallenges: "",
		}),
		[t],
	)

	React.useEffect(() => {
		let targets: Version[] = [
			{
				label: "Java 11",
				id: "java11",
				value: 11,
				jakartaEEVersion: "9",
			},
			{
				label: "Java 17",
				id: "java17",
				value: 17,
				jakartaEEVersion: "10",
			},
			{
				label: "Java 21",
				id: "java21",
				value: 21,
				jakartaEEVersion: "10",
			},
			{
				label: "Java 25",
				id: "java25",
				value: 25,
				jakartaEEVersion: "10",
			},
		]
		if (sourceVersion) {
			targets = targets.filter((target) => target.value > parseInt(sourceVersion))
		}

		setTargetOptions(targets)

		// Now that we have targetOptions, set targetVersion if it's saved in config.props
		const configVersion = config.props?.["targetJavaVersion"]
		if (configVersion) {
			const defaultOption = targets.find((target) => target.value === configVersion)

			if (defaultOption) {
				setTargetVersion(defaultOption.id)
			}
		}
	}, [envInfo, sourceVersion, config.props])

	// Update Jakarta EE version when target Java version changes
	// Check if the selected Java version exists in the installations
	const checkJavaInstallation = React.useCallback(
		(version: string) => {
			if (!version || !envInfo["java-installations"]) {
				return { found: false }
			}

			// Extract the numeric version from the target version ID (e.g., "java11" -> "11")
			const targetVersionNumber = version.replace("java", "")

			// Find if this version exists in the java-installations
			const installation = envInfo["java-installations"]?.find(
				(install: JavaInstallation) => install.version === targetVersionNumber,
			)

			return installation ? { found: true, path: installation.path } : { found: false }
		},
		[envInfo],
	)

	React.useEffect(() => {
		if (targetVersion) {
			// Check if the selected Java version exists in the installations
			setJavaInstallationFound(checkJavaInstallation(targetVersion))
			// Extract the version number from jeeVersion
			let versionNumber
			if (jeeVersion.startsWith("Java-EE-")) {
				const versionStr = jeeVersion.replace("Java-EE-", "")
				versionNumber = parseInt(versionStr, 10)
			} else if (jeeVersion.startsWith("Jakarta-EE-")) {
				const versionStr = jeeVersion.replace("Jakarta-EE-", "")
				versionNumber = parseInt(versionStr, 10)
			}

			// Find the selected target version object
			const selectedTarget = targetOptions.find((target) => target.id === targetVersion)
			const toBeJEEVersion = selectedTarget?.jakartaEEVersion || ""

			if (versionNumber && toBeJEEVersion && parseInt(toBeJEEVersion, 10) > versionNumber) {
				setJakartaEEEnabled(true)
				setJakartaEEVersion(toBeJEEVersion)
			} else {
				setJakartaEEEnabled(false)
			}
		} else {
			setJakartaEEVersion("")
		}
	}, [targetVersion, jeeVersion, targetOptions, checkJavaInstallation])

	// Parse javaModRecommendations and find matching upgrade path when target version changes
	React.useEffect(() => {
		if (javaModRecommendations && targetVersion) {
			try {
				const recommendations: JavaModRecommendations = javaModRecommendations
				const targetVersionNumber = targetVersion.replace("java", "")

				const matchingPaths = recommendations.upgradePaths.filter((path) => path.path === targetVersionNumber)
				const matchingPath = matchingPaths.find((path) => path.jee === jakartaEEEnabled)
				setSelectedUpgradePath(matchingPath || null)
			} catch (error) {
				console.error("Error parsing javaModRecommendations:", error)
				setSelectedUpgradePath(null)
			}
		} else if (targetVersion && recommendationTimedOut) {
			setSelectedUpgradePath(TIMEOUT_UPGRADE_PATH)
		} else {
			setSelectedUpgradePath(null)
		}
	}, [
		javaModRecommendations,
		targetVersion,
		checkJavaInstallation,
		jakartaEEEnabled,
		recommendationTimedOut,
		TIMEOUT_UPGRADE_PATH,
	])

	// Timer to hide recommendation skeleton after 1 minute if no upgrade path is found
	React.useEffect(() => {
		if (targetVersion && !selectedUpgradePath && !recommendationTimedOut) {
			setShowRecommendationSkeleton(true)

			const timer = setTimeout(() => {
				if (!selectedUpgradePath) {
					setShowRecommendationSkeleton(false)
					setSelectedUpgradePath(TIMEOUT_UPGRADE_PATH)
					setRecommendationTimedOut(true)
				}
			}, 60 * 1000)

			return () => clearTimeout(timer)
		} else if (selectedUpgradePath || recommendationTimedOut) {
			// If upgrade path is found or recommendation timeout has elapsed, ensure recommendation skeleton is hidden
			setShowRecommendationSkeleton(false)
		}
	}, [targetVersion, selectedUpgradePath, recommendationTimedOut, TIMEOUT_UPGRADE_PATH])

	// Function to handle recipe runner results from the extension
	React.useEffect(() => {
		const handleMessage = (event: MessageEvent) => {
			const message = event.data
			if (
				message.type === "commandResult" &&
				message.requestId &&
				message.requestId.startsWith("recipe-runner-")
			) {
				if (message.commandResult.subSteps) {
					const subSteps: StepLike[] = message.commandResult.subSteps
					setSubSteps(subSteps)
					if (isStepInProgress(subSteps)) {
						setIsRunning(true)
					} else {
						const recipeStep = subSteps.find((s) => s.id === SubStepId.JAVA_UPGRADE_RECIPE_RUN)
						setRecipeResults(recipeStep?.result?.executionResult?.stdout ?? "")
						setBranchName(recipeStep?.result?.data?.branchName ?? "")
						setIsRunning(false)
					}
				}

				if (message.commandResult.javaModRecommendations) {
					setJavaModRecommendations(message.commandResult.javaModRecommendations)
				}
			}
		}

		// Add event listener for messages from the extension
		window.addEventListener("message", handleMessage)

		// Clean up the event listener when the component unmounts
		return () => {
			window.removeEventListener("message", handleMessage)
		}
	}, [])

	const handleRunRecipes = () => {
		if (!targetVersion) return

		setIsRunning(true)
		setRecipeResults("")

		// Extract the numeric version from the target version ID
		const targetJavaVersionNumber = targetVersion.replace("java", "")

		// Send a message to the extension to execute the recipe runner tool
		const message: WebviewMessage = {
			type: "executeCommand",
			commands: ["bob-code.executeRecipeRunner"],
			commandArgs: [
				sourceVersion,
				targetVersion,
				targetJavaVersionNumber,
				envInfo,
				jakartaEEEnabled,
				jakartaEEVersion,
				enableGitFlow,
			],
			eventId: `recipe-runner-${Date.now()}`,
		}
		vscode.postMessage(message)
	}

	React.useEffect(() => {
		if (recipeResults && !stepCompleted) {
			// Prepare Jakarta EE message part
			const jakartaMessage =
				jakartaEEEnabled && jakartaEEVersion ? ` with Jakarta EE ${jakartaEEVersion} migration` : ""

			// Recipes complete move to next stage
			const responseObject: ControlledChatResponseObject = {
				flowId: config.flowId,
				stepId: config.stepId,
				message: `Ran Java upgrade recipes from Java ${sourceVersion} to ${targetOptions.find((opt) => opt.id === targetVersion)?.label}${jakartaMessage}`,
				data: {
					sourceJavaVersion: sourceVersion,
					targetJavaVersion: targetVersion, // Keep the full value with "java" prefix for consistency
					jakartaEE: {
						enabled: jakartaEEEnabled,
						version: jakartaEEVersion,
					},
					recipeResults,
					branchName,
					fullyAutomatedMode: false, // TODO this should be removed and moved to agent section
					isCompleted: true,
				},
			}
			sendChatResponse(responseObject)
			setStepCompleted(true)
		}
	}, [
		config.flowId,
		config.stepId,
		branchName,
		recipeResults,
		stepCompleted,
		targetOptions,
		targetVersion,
		sourceVersion,
		jakartaEEEnabled,
		jakartaEEVersion,
	])

	return (
		<>
			<h3>{t("ibm:javaModernization.runRecipes.title")}</h3>
			<p>{t("ibm:javaModernization.runRecipes.subTitle")}</p>

			<StepContainer>
				<div className="flex gap-2 mb-2">
					<div className="w-full">
						<div className="mb-2 text-sm">{t("ibm:javaModernization.runRecipes.sourceJavaVersion")}</div>
						<Select
							className="w-full"
							options={[
								{
									label: `Java ${sourceVersion}`,
									id: `java${sourceVersion}`,
								},
							]}
							selectedValue={`java${sourceVersion}`}
							disabled={true}
							onChange={() => { }}
						/>
					</div>
					<div className="w-full">
						<div className="mb-2 text-sm">{t("ibm:javaModernization.runRecipes.targetJavaVersion")}</div>
						<Select
							className="w-full"
							options={targetOptions}
							selectedValue={targetVersion}
							disabled={isRunning || stepCompleted}
							onChange={(value: string) => {
								setTargetVersion(value)
							}}
						/>
					</div>
				</div>

				<div className="p-1 space-y-2">
					{/* Display Java installation status message when target version is selected */}
					{targetVersion && (
						<div className="text-sm">
							<div className="w-full">
								{javaInstallationFound.found ? (
									<div className="flex items-center gap-2 ">
										<CheckIcon size={20} className="text-sm text-green-500" />
										{t("ibm:javaModernization.runRecipes.javaVersionFound", {
											version: targetVersion.replace("java", ""),
											path: shortenPath(javaInstallationFound.path),
										})}
									</div>
								) : (
									<div className="flex items-center gap-2">
										<TriangleAlert
											size={20}
											className="text-[var(--vscode-editorWarning-foreground)] "
										/>
										{t("ibm:javaModernization.runRecipes.javaVersionNotFound", {
											version: targetVersion.replace("java", ""),
										})}
									</div>
								)}
							</div>
						</div>
					)}

					{targetVersion && jakartaEEVersion && shouldEnableJakartaEE && (
						<SettingToggleRow
							title={t(`ibm:javaModernization.runRecipes.settings.jakartaEEupgrade.label`)}
							description={t(`ibm:javaModernization.runRecipes.settings.jakartaEEupgrade.description`, {
								jeeVersion: jeeVersion,
								jakartaEEVersion: jakartaEEVersion,
							})}
							disabled={isRunning || stepCompleted}
							checked={jakartaEEEnabled}
							onChange={() => setJakartaEEEnabled(!jakartaEEEnabled)}
						/>
					)}

					{targetVersion &&
						(selectedUpgradePath ? (
							<RecommendationSection selectedUpgradePath={selectedUpgradePath} />
						) : (
							showRecommendationSkeleton && <RecommendationSkeleton />
						))}
				</div>

				<StepButton
					disabled={!targetVersion || isRunning || stepCompleted}
					onClick={handleRunRecipes}
					subSteps={subSteps}>
					{isRunning
						? t("ibm:javaModernization.runRecipes.runRecipesButtonProcessing")
						: t("ibm:javaModernization.runRecipes.runRecipesButton")}
				</StepButton>
				<StepProgressTodoList subSteps={subSteps} />
			</StepContainer>
			<StepProgressNotifications subSteps={subSteps} />
		</>
	)
}

export default memo(RunRecipesStep)
