import { memo, useCallback, useEffect, useMemo, useState } from "react"
import { cn } from "@/lib/utils"
import { useAppTranslation } from "../../../../i18n/TranslationContext"
import { vscode } from "@/utils/vscode"
import { useExtensionState } from "@/context/ExtensionStateContext"
import { litellmDefaultModelId } from "@roo-code/types" // ibm_change
import { DropdownOptionType, SelectDropdown } from "@/components/ui"

const ModelPicker: React.FC = () => {
	const { t } = useAppTranslation()
	const { apiConfiguration, currentApiConfigName, routerModels } = useExtensionState()

	const [selectedModelId, setSelectedModelId] = useState<string>(
		apiConfiguration?.litellmModelId || litellmDefaultModelId,
	)

	// Memoize options to prevent unnecessary recalculations
	const options = useMemo(() => {
		if (!routerModels?.litellm) {
			return []
		}

		return Object.entries(routerModels.litellm)
			.filter(([, modelProps]) => modelProps?.exposed)
			.map(([modelId]) => ({
				value: modelId,
				label: modelId,
				type: DropdownOptionType.ITEM,
			}))
			.sort((a, b) => a.label.localeCompare(b.label))
	}, [routerModels?.litellm])

	// Update selectedModelId when apiConfiguration changes
	useEffect(() => {
		const modelId = apiConfiguration?.litellmModelId
		if (modelId) {
			setSelectedModelId(modelId)
		}
	}, [apiConfiguration?.litellmModelId])

	const refreshModelList = useCallback(() => {
		const key = apiConfiguration?.litellmApiKey
		const url = apiConfiguration?.litellmBaseUrl

		if (!key || !url) {
			return
		}
		vscode.postMessage({ type: "requestRouterModels", values: { litellmApiKey: key, litellmBaseUrl: url } })
	}, [apiConfiguration?.litellmApiKey, apiConfiguration?.litellmBaseUrl])

	const handleModelChange = useCallback(
		(modelId: string) => {
			// Update local state immediately for UI responsiveness
			setSelectedModelId(modelId)

			const updatedApiConfiguration = {
				...apiConfiguration,
				litellmModelId: modelId,
				apiModelId: modelId,
			}
			// Update the model in the extension state
			vscode.postMessage({
				type: "upsertApiConfiguration",
				text: currentApiConfigName,
				apiConfiguration: updatedApiConfiguration,
			})
		},
		[apiConfiguration, currentApiConfigName],
	)

	// If less than 2 model options hide the picker as there isn't anything to choose from
	if (options.length < 2) {
		return null
	}

	return (
		<div className={cn("flex-1", "min-w-0", "overflow-hidden")} onClick={refreshModelList}>
			<SelectDropdown
				value={selectedModelId}
				title={t("ibm:chat.selectModel")}
				placeholder={selectedModelId || t("ibm:chat.selectModel")}
				options={options}
				onChange={handleModelChange}
			/>
		</div>
	)
}

export default memo(ModelPicker)

